window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_010"]={"n":"孙原湘","dyn":"清","poems":[{"t":"牧歌","f":"古风","c":["上牛坐，伏牛卧，牧童光阴牛背过。","牛尾秃速牛角弯，牛肥牛瘠心先关。","母呼儿饭儿不饭，人饿须知饲牛晚。","放之平泉，以宽牛劳；","浴之清浅，以息牛喘。","牛能养人识人意，一牛全家命所寄。","阿牛牵牛去输租，劝爷卖牛宁卖吾。"]},{"t":"澄海楼望海","f":"五言古诗","c":["振衣百尺楼，天风何浪浪。","天光与海色，一气同青苍。","是时日初升，赤霞烧扶桑。","照见诸岛屿，波上争低昂。","浮云从西来，万马奔洪涛。","气卷五岳走，天地俱动摇。","人坐此楼中，势若随波旋。","白日倒入海，青春走上天。","念当乘风去，玄览极八埏。","回头顾人世，一点如秋烟。"]},{"t":"真秀阁","f":"七言律诗","c":["雨后看云尽出城，最高楼阁有余清。","一帘空水摇天碧，半壁残虹浴海明。","花与蝶飞时下上，书无人揭自纵横。","不知何事凭栏立，落日苍茫百感生。"]},{"t":"夜坐","f":"五言律诗","c":["虫声破夜寂，小坐媆凉天。","病久花同瘦，愁多梦不圆。","孤怀凭月迥，静气得秋先。","惟有深闺里，应知客未眠。"]},{"t":"秋夜简吴顼儒","f":"五言古诗","c":["空房生秋烟，明月来窥我。","西风闪孤檠，人影右忽生。","落叶卷我心，飞向秋江堕。","秋江浮萍死，秋水贵于金。","天吴走阴谷，鲛客潜青林。","尽拘苍生泪，不成三日霖。","寒云锁孤蟾，野黑南山泣。","白骨照幽泉，秋坟鬼声涩。","遥知芦中人，掩卷三叹息。"]},{"t":"冬日由昭明台取径登辛峰亭观落日 其一","f":"五言律诗","c":["出门见飞鸟，岁晚吾独间。","白云先我心，摇曳苍林间。","古台木叶落，苍然见寒山。","高处望不极，努力穷跻攀。"]},{"t":"冬日由昭明台取径登辛峰亭观落日 其二","f":"五言古诗","c":["我游此山巅，兴落山外山。","岂知秀绝处，只在城市间。","凭高览全邑，屋密树尽删。","孤云飞出城，不敢敌人烟。","吁嗟殷庶风，此后几百年。"]},{"t":"冬日由昭明台取径登辛峰亭观落日 其三","f":"五言古诗","c":["远眺殊未已，前山已落日。","偏于欲落时，其势犹似出。","残霞明半天，并作暮云黑。","云中珊瑚盘，反弄黄金色。","人坐松林中，愈觉苍翠逼。","浩歌归去来，此意无人识。"]},{"t":"燕子矶望江","f":"七言律诗","c":["石壁翻江势动摇，荻花芦叶正萧萧。","青山有意摹三凫，白浪无情送六朝。","帆影不分京口树，钟声如答海门潮。","雄心慢击中流楫，且看鱼龙出没骄。"]},{"t":"晓过寒山","f":"五言古诗","c":["舟行先鸟起，反唤鸟梦醒。","霜华纳窗白，水气袭衣冷。","山头数游鱼，倒浸插天影。","云起失前林，萍开见孤岭。","渚鸿何嗷嗷，对我若悲哽。","稻粱何足谋，高飞碧天迥。"]},{"t":"晓发","f":"七言律诗","c":["霜天漠漠淡于波，月色连天一片和。","幽树瘦疑秋士立，远山平似晓烟抱。","梦残犹苦鸡声唤，愁重难胜马力驼。","十载征衫青未脱，祇余燕市酒痕多。"]},{"t":"五渠","f":"五言律诗","c":["一水围村市，非船路不通。","春醪人乳白，渔火妇颜红。","双塔浮波出，青山到郭穷。","正愁行易尽，偏是好东风。"]},{"t":"九日登北山作","f":"五言古诗","c":["木落原野清，陇首浮云飞。","高台一以眺，秋色苍然来。","孤村隐寒烟，远树带斜晖。","猿啼众山暝，雁度空江迟。","物澹我自得，情疏理无违。","美人在空谷，瑟瑟秋萝衣。"]},{"t":"夜宿小石洞","f":"七言律诗","c":["何处峰头铁笛声，飘然秋思与同情。","拨开落叶通泉细，喝破浮云放月明。","石气欲吹诗骨冷，天风如化羽衣轻。","举头不敢舒长啸，恐有林间宿鸟惊。"]},{"t":"雨霁","f":"五言律诗","c":["雨拨西风转，天容寸碧开。","出花孤蝶重，抱树一蝉哀。","爽气遥山下，愁心远渚来。","画檐云缕缕，秋叶是谁裁？"]},{"t":"九铁僧寮与兼山秋语 其一","f":"七言律诗","c":["豪丝哀竹近中年，过眼春痕水上烟。","一窖黄金先铸佛，半床青史小游仙。","引人入梦偏胡蝶，劝客归田有蜀鹃。","畅好尚湖秋万顷，几时同上钓鱼船。"]},{"t":"九铁僧寮与兼山秋语 其二","f":"七言律诗","c":["驱却青蝇百事宜，石幢松影下罘罳。","客磨诗里花同瘦，秋到人间佛不知。","万叶盛衰先有信，一蝉哀怨总无私。","红尘白社双青眼，如此相看得几时。"]},{"t":"春溪把钓曲","f":"七言律诗","c":["满溪春水绿可怜，桃花如云红上天。","远山倒浸碧波底，一堆春烟钓不起。","人目在鱼鱼目丝，人心动静鱼先知。","竹竿袅袅尾泼泼，翠荇一涡沧海阔。"]},{"t":"书杨忠悯公张夫人疏","f":"古风","c":["吉祥善事宁有此，夫作忠臣妇代死。","事虽未成志则尔，一疏煌煌播西市。","天河钓叟紫极翁，沈香叶冠翊赞功。","燎原之火倒海水，小儿鼾卧东楼东。","文管家，武管家，黄金鬻爵不肯赊。","赵家儿，鄢家儿，白日鬼蜮行其私。","除我疡，杀南塘。","比翟方，杀同乡。","下有杀人子，上事好杀皇。","椒山剌剌不晓事，十罪牵连二王字。","一鸾已困况百鸾，风吹枷锁倾城观。","窜张经尾取上旨，明杀谏官自此始。","尧斋英明四海钦，杀人反快奸人心。","幸遇邹徐霹雳手，射倒高山射培塿。","可怜一字不成时，二十七姬星散走。","不见苏纲息女代贵溪，两家不愧忠臣妻。"]},{"t":"归舟","f":"七言律诗","c":["鸥波摇荡绿参差，收起春帆去路迟。","过眼云山千幅画，破眠风雨一船诗。","悬猜帘影桥边柳，背嗅花香橹后枝。","如此浮家吾愿足，不归犹可况归时。"]},{"t":"月午楼歌","f":"七言古诗","c":["明月出海先上楼，我楼况在高山头。","开窗放出白云去，风帘尽控双银钩。","一丸才过高松顶，屏风乱泻虬龙影。","摊书不用青藜然，碧空自有明珠悬。","黄高峰头云浪涌，金鳌峰背沧波动。","山下万顷云海铺，天心一丝云气无。","清光愈高读愈苦，月照书丛月色古。","仙巢惊起老鹤舞，窗中不知月已午。","露珠瑟瑟风泠泠，屋角余挂三四星。","冰轮欲西还倒行。","似怜读书声好听。","冷光一线射人面，射月眼光亦如电。","明月不落读不厌，水滴蟾蜍欲穿砚。"]},{"t":"题姜白石像","f":"七言古诗","c":["七百年事如秋烟，劫灰中有不死仙。","六下下攫终得全，曹衣吴带何翛然。","当时鄱阳侠少年，雪花夜打乌篷船。","浪游南岳不得旋，手拔龙角弹湘弦。","彝陵幸遇萧东夫，东来径参范石湖。","声名一旦满天下，四顾谁能荐司马？","奋笔自议太常雅，其奈黄钟不敌瓦。","偶耽吴兴山水奇，白石洞天插我篱。","累累白石不疗饥，腹中惟燕潘柽诗。","兴酣自携碧玉箫，间鸥引过松陵桥。","鹰扬之印空佩腰，照水白发风萧萧。","马塍花开香沁土，小红偷洒燕脂雨。","鸑鷟无声石人语，一往孤云竟千古。","沈檀雕匣吴绫装，明珠辟火深深藏。","风吹鹤鳖如烟动，纸上古香发南宋。"]},{"t":"赠朱秋坪明经即题其洗砚图","f":"七言古诗","c":["南梁北刘无昔人，后来更推蔡与陈。","钟溪既老德清病，纷纷馆阁推麒麟。","朱君少有临池癖，日闭萧斋抚古迹。","杀尽山中紫兔毫，洒残绝域金壶墨。","五十头颅鬓骚屑，染翰朝朝腕欲折。","骆驼桥西片纸出，人道风神似松雪。","吾乡书法溯二冯，翁张汪邵谁雌雄？","绝伦虽无羲献迹，古法未失钟胡风。","自从俗书逞姿熊，子弟家家学姚派。","瓣香祇识奉华亭，笔阵谁知求晋代。","君今僻居临水村，罗列金石娱朝昏。","红柿周围白板屋，绿天自裹铁叶门。","香姜古砚浮寒碧，浸入明漪涨云色。","欲知君书得力处，但看一池秋水黑。"]},{"t":"精忠柏","f":"楚辞体","c":["万木畏枯枯则薪，一株独以枯见珍。","神斤鬼斧不敢近，忠义之气缠其身。","蛟虬翠郁风波亭，一夜号泣枯精英。","奸邪气横正气绝，感愤物理同人情。","不见百口保飞宗，正卿窜身南海以死争。","上书讼冤刘允升，横尸棘寺鸣不平。","区区小校犹忠诚，竟欲斩艾邪蒿萌。","柏虽草木气至清，肯与贼桧同时生。","死八百年挺不屈，蜕尽龙皮剩龙骨。","中有丹心不肯枯，只是春风吹不活。","天欲吹活柏固辞，偷生半壁匪我思。","除非痛饮黄龙时，枯枝一一回青枝。","天亦不能彊活之，任其一木乾坤支。","表忠但敕风雷司，霹雳老桧分其尸。","吁嗟南渡朝廷小，泥首北风如偃草。","只赏西湖花柳妍，浑忘朔漠椿棠老。","构兮构兮木不良，大厦以桧为栋梁，长城如檀翻见戕。","不如此柏有本性，直与精忠同正命。","但看枝枝北向枯，木理犹知朝二圣。","从来死贵得其死，不见死而不死树如此。"]},{"t":"大家 其一","f":"七言律诗","c":["风格天然是大家，不施金翠不铅华。","眉弯只仿三分月，心曲常期百合花。","早喜娇儿工蜡凤，每嗤小婢学涂鸦。","罗衣怕惹薰笼息，自有生香胜辟邪。"]},{"t":"大家 其二","f":"七言律诗","c":["形影相随语意关，调琴弄瑟两都娴。","心如江汉交流水，梦在罗浮合体山。","承露绮兰双箭起，凌波罗袜一弓弯。","春晴不敢楼头望，恐被桃花妒玉颜。"]},{"t":"大家 其三","f":"七言律诗","c":["七情雕刻玉珑玲，光彻玻璃一座屏。","约伴彩笺书日子，试儿锦字认风丁。","愁听谢豹啼残月，苦讽牵牛觅小星。","修得闺房清福胜，不教鹦鹉念心经。"]},{"t":"大家 其四","f":"七言律诗","c":["也愿红颜也白头，一分慧带一分愁。","恐防归燕常开箔，怕见飞英不下楼。","绮语尚耽平素癖，芳情早谢踏青游。","簪花写幅兰亭帖，便当初三禊事脩。"]},{"t":"乍嫁","f":"七言律诗","c":["冰肌雪腕藐姑仙，乍嫁还如未嫁年。","通脱转饶风格峻，低徊刚映日华妍。","胸前草佩添丁喜，髻上花删过午蔫。","却笑并船诸女伴，明珠压得翠鬟偏。"]},{"t":"画舫四首 其一","f":"七言律诗","c":["画舫相排若比邻，不曾珠箔障香尘。","一家语笑情初洽，半晌沉吟态更真。","纨扇偶擎非掩敛，罗衣欲换且逡巡。","凭阑囗自青天看，几见嫦娥要辟人。"]},{"t":"画舫四首 其二","f":"七言律诗","c":["一分才调一分情，全是玲珑不是轻。","倾国偶逢须福分，守宫才退更鲜明。","裙边蝴蝶郎持定，袖上花枝姊唾成。","仙骨未容人仿佛，自临春水照盈盈。"]},{"t":"画舫四首 其三","f":"七言律诗","c":["左倚兰桡右桂旗，惊鸿影落碧玻璃。","生成细骨轻躯好，悉听横看侧视宜。","恕我狂名帘不下，厌人谀语傍潜移。","幽兰自是深闺种，许蝶闻香禁蝶知。"]},{"t":"画舫四首 其四","f":"七言律诗","c":["亚字红桥折向东，橹枝摇曳太匆匆。","云多离合晴难定，花有阴阳致不同。","逼近更闻香荡越，薄瞑犹胜月朦胧。","明眸焉肯轻回睐，自觉微波面面通。"]},{"t":"层城 其一","f":"七言律诗","c":["望彻层城坐彻宵，苦将心眼记丰标。","生来仙骨非丹换，摹拟神情胜白描。","牛女若逢应妒巧，莺花相对苦争娇。","丹诚欲寄何由达，吹煞灯前白玉箫。"]},{"t":"层城 其二","f":"七言律诗","c":["别来追忆总模糊，祇悔当时领略粗。","妄想自知须忏悔，閒情何碍属虚无。","款门甘袖三年刺，屣画拚将百日呼。","愿化木兰舟上楫，供君稳坐玉纤扶。"]},{"t":"仙才","f":"七言律诗","c":["闺房林下誉难偏，一副身心两副妍。","不道聪明尤绝世，即论光艳合生天。","容教佛见拈花笑，诗到神来脱草传。","我欲讽卿键绣闼，放他霜月斗婵娟。"]},{"t":"兰信 其一","f":"七言律诗","c":["传来消息是耶非，错认湘妃作宓妃。","标识幸馀青玉佩，随常爱著白绡衣。","鸳鸯早誓横塘偶，蛱蝶遥从外幕飞。","怪道碧桃花独艳，只贪颜色子犹稀。"]},{"t":"兰信 其二","f":"七言律诗","c":["动是飞仙静是神，不容窥破意才真。","深情何但能容妾，绝色无须更妒人。","捏土互搀夫婿像，隔帏曾屈小郎宾。","寻常喜愠都藏过，还恐全家学笑颦。"]},{"t":"玉问 其一","f":"七言律诗","c":["误触晶屏獭髓敷，一丝霞气透云乌。","久知白璧推瑜瑾，肯把黄金属画图。","妒口悉凭同列谤，高情转避俗人谀。","山河倒影银蟾里，曾累姮娥绝色无。"]},{"t":"玉问 其二","f":"七言律诗","c":["草草梳头暖玉搔，青铜秘钥手轻操。","析来文箸湘妃竹，制就银杯阿母桃。","风雅最能倾女伴，雪花亲自靧儿曹。","乌丝掌籍烦书写，落笔先题一字糕。"]},{"t":"阿阁 其一","f":"七言律诗","c":["阿阁三层碧玉支，红栏刚倚绿梧枝。","偷窥云母围屏薄，潜伺星妃步辇迟。","隔座微闻花气息，绕廊暗想雪丰姿。","明知璧月朝难见，痴对青天立几时。"]},{"t":"阿阁 其二","f":"七言律诗","c":["明明可见似银蟾，只禁疏狂逼画檐。","纵少猜嫌宜引避，偶贪游戏实矜严。","轻衫着后无心换，团扇题成信手拈。","倘许朝朝窥素影，未妨常隔一重帘。"]},{"t":"新睛","f":"七言律诗","c":["丰姿瞥见更倾城，众里纤长最著明。","翠袖羞拢金钏影，画帘惊堕玉钗声。","贵人原自肌盈实，妃子何惭骨细轻。","一种大家风范在，暂来门巷看新晴。"]},{"t":"和美人扇头韵","f":"七言律诗","c":["人似青天近实遥，相思早暮两回潮。","风偏有力香亲染，水最多情影惯描。","车响乍通雷隐隐，帘痕斜劈月条条。","巫山更在蓬山顶，云气才容到半腰。"]},{"t":"纪遇 其一","f":"七言律诗","c":["蓦地娇羞不自禁，银钩却下绣帘深。","寻常难得花枝笑，咫尺微闻玉佩音。","半面向人犹掩敛，回身何事独沉吟。","眼波便是秦台镜，照彻狂生一寸心。"]},{"t":"纪遇 其二","f":"七言律诗","c":["桃溪重到月痕移，帘眼参差望眼痴。","镜影难凭方士觅，闺情曾访济尼知。","莲须水落才逢藕，柳为风狂已乱丝。","此是昨朝相见地，悄无人在立多时。"]},{"t":"纪遇 其三","f":"七言律诗","c":["藏却深情露却才，绿窗鬓影太低徊。","廋词竟被全猜著，眉语偏乘不备来。","蜡烛乍烧心已见，鱼书临发口难开。","从今紧闭看花眼，每到卿前展一回。"]},{"t":"纪遇 其四","f":"七言律诗","c":["意外逢欢倍可欢，小屏山角路漫漫。","月依眉样初三细，春减腰围尺六宽。","背影乍摇珠络索，笑声徐近画兰干。","九天咳吐随风落，邮得倾身化玉盘。"]},{"t":"纪遇 其五","f":"七言律诗","c":["一折回阑亚字雕，绿荷风引见云翘。","半遮蜥蜴金跳脱，小立蜻蜓玉步摇。","不为聪明争解怨，绝无羞涩是真娇。","持裙尚恐终仙去，更倩红鸾系紫绡。"]},{"t":"纪遇 其六","f":"七言律诗","c":["一日何妨见百回，一回经眼一心开。","平生已愿低头拜，险计犹拚折齿灾。","敢道看花非好色，早知掷果为怜才。","遥山眉黛天然秀，那是相如画得来。"]},{"t":"病耗","f":"七言律诗","c":["一春吟苦病恹恹，步屧新闻出画檐。","笑赌秘书常泼茗，戏拈险韵反题盐。","清欢久谢云为梦，素艳真疑月满帘。","谶得檀郎情性涽，略通私昵便矜严。"]},{"t":"写真","f":"七言律诗","c":["晓镜匀黄特地妍，风神追写未笄年。","见人偷眼频低首，为我回身恰比肩。","明慧最谙姑性格，温柔曲体婿矜怜。","阿侯姿貌浑相似，些子争差笑靥圆。"]},{"t":"荡舟小秦淮","f":"七言律诗","c":["幽溪曲折荡兰桡，夹岸花深路一条。","秀麦时光犹拥背，及瓜年纪正垂髫。","半松云鬓眠初起，屡受星眸意欲消。","忽忆真人天际影，此心已恐负丹霄。"]},{"t":"题扇 其一","f":"七言律诗","c":["水晶帘捲镜台安，晓起簪花露未干。","衣蕴奇香防母觉，面留真色尽人看。","轻躯细骨偏持重，龋齿愁眉也带欢。","偶忆郎诗惬侬意，泥将小字写冰纨。"]},{"t":"题扇 其二","f":"七言律诗","c":["蓬山处处月凄迷，梦觉流莺恰恰啼。","杜牧看花曾有约，冬郎吟草半无题。","宿缘最喜兰为字，欢绪从拼絮作泥。","换取定情团扇子，春风常似玉纤携。"]},{"t":"消夏词 其一","f":"七言绝句","c":["小谪人间萼绿华，墙头愁见石榴花。","洞房如雪帘如水，争及瑶池阿母家。"]},{"t":"消夏词 其二","f":"七言绝句","c":["妆台花露尚沾濡，趁个朝凉云髻扶。","生性梳妆非草草，不嫌妨却睡工夫。"]},{"t":"消夏词 其三","f":"七言绝句","c":["随意疏花插戴成，花枝颤颤若风倾。","玉搔头上双蝴蝶，翻教人看作像生。"]},{"t":"消夏词 其四","f":"七言绝句","c":["翠纱衫子玉玲珑，坐背风前意态慵。","犹恐玉肌人看见，轻绡一尺袜当胸。"]},{"t":"消夏词 其五","f":"七言绝句","c":["兰空午倦梦回迟，对镜花删半亸枝。","一线枕痕红未退，怪人半晌看侬时。"]},{"t":"消夏词 其六","f":"七言绝句","c":["细喘娇吁出浴初，云鬟依旧似新梳。","香融汗粉罗巾拭，越显肌肤雪不如。"]},{"t":"消夏词 其七","f":"七言绝句","c":["荷风几阵引新凉，吹灭荧荧画烛光。","恰好纱窗开半扇，额边斜月注娇黄。"]},{"t":"消夏词 其八","f":"七言绝句","c":["人语花香辨不情，水明帘捲夜云轻。","行来仙骨姗姗甚，暗里遥开玉钏声。"]},{"t":"情苗 其一","f":"七言律诗","c":["月华如雪露华浓，寻遍阑干隔岁踪。","祇觉东风苏病体，难遮西日驻欢容。","灯花刺眼双苞结，带子惊心一寸松。","除却寒衾温旧梦，春来无事不娇佣。"]},{"t":"情苗 其二","f":"七言律诗","c":["玉梅花下乍回嗔，却悔频年迹未亲。","出意为卿书扇子，倾心唤我作才人。","枕函弘结联环带，香饼潜薰垫角巾。","从此一泓清澈水，东风吹起绿鳞鳞。"]},{"t":"寒夜 其一","f":"七言律诗","c":["缟衣初出洞房门，比玉生香比雪温。","星眼暗抬人不觉，风情略透语无痕。","晓妆偷得元蝉影，春梦迷残粉蝶魂。","何处着卿踪迹好，梨花满地月黄昏。"]},{"t":"寒夜 其二","f":"七言律诗","c":["帘栊悄悄月冥冥，斜背银缸倚绣屏。","四面圆浑金跳脱，一心穿透玉珑玲。","垆香细熨寒衣煖，茶雾浓薰睡眼醒。","犹恐夜深人苦读，故拚风露隔窗听。"]},{"t":"密意 其一","f":"七言律诗","c":["待不消魂不自禁，乍黄昏又阁轻阴。","背灯佯溜搔头玉，隔座亲舒缠臂金。","竹小苦无栖凤力，花含先有许蜂心。","九天屈注银湾水，抵得恩多未抵深。"]},{"t":"密意 其二","f":"七言律诗","c":["意外欢期意倍开，云軿忽降九层台。","正愁汉使乘槎断，却讶神娥浴雨来。","众里廋词偏捷悟，人前娇眼不轻抬。","明知相守原无益，且得留卿坐一回。"]},{"t":"新年词 其一","f":"七言律诗","c":["新年和气护窗纱，宝镜台前落彩霞。","低髻恰笼如意玉，高情秖插素心花。","妆梳雅澹偏倾国，礼范从容本大家。","暗自喜欢佯面觍，紫兰争祝早抽芽。"]},{"t":"新年词 其二","f":"七言律诗","c":["剪烛春宵射覆工，相思骰子赌珍珑。","眼波敏捷回身溜，眉语聪明对面通。","险计欲拚孤注博，良媒拟策赐绋功。","此生定有双飞分，落手全盆轻六红。"]},{"t":"新年词 其三","f":"七言律诗","c":["九天珠玉堕云端，花里潜踪路渺漫。","侥倖下风兰气息，低徊昨日画阑干。","笑声尚带红绒落，瘦影应怜翠袖寒。","甘为立残虚幌月，待他徐照面痕乾。"]},{"t":"静志","f":"七言律诗","c":["有时欢笑有时颦，毕竟相亲可算亲。","爱极并忘容绝代，情深始觉礼拘人。","生生世世卿怜我，暮暮朝朝女是神。","不及画栏东畔树，花开常傍鬓边春。"]},{"t":"幽窗","f":"七言律诗","c":["静掩红窗锁绿筠，乌龙高卧雪狸驯。","飞花几误鱼吞影，密叶才容蝶过身。","得伺机缘情转怯，肯担惊恐爱方真。","风帆开到中流转，也胜江干坐守人。"]},{"t":"五更","f":"七言律诗","c":["洞房春暖万花香，半似分明半渺茫。","烛影乍遮金翡翠，簟纹亲展紫鸳鸯。","停云低阁三分雨，飞雪深投百沸汤。","正是五更寒彻骨，月华如水满匡床。"]},{"t":"小印","f":"七言律诗","c":["瑶台何处著纤尘，着个飘然咏絮人。","天上碧桃偏带雪，洞中珠树不知春。","閒情屡说元才子，杂事羞提汉秘辛。","偷下蟾宫修凤牒，自钤小印号长真。"]},{"t":"夜深","f":"七言律诗","c":["南斗参横北斗阑，熏垆几遍爇沉檀。","依依送别花间暗，快快归房露下寒。","乍拭粉痕肌愈白，暗腾酒晕颊微丹。","玉郎何处潜踪到，重剔银灯一晌看。"]},{"t":"绣鞋","f":"七言律诗","c":["六曲围屏换晚妆，倒提余缕学南唐。","鲜明乍脱春葱手，滑腻犹闻玉笋香。","合德双趺偏宛转，窅娘半月费裁量。","单凫分与郎收拾，省得摩挲灭烛狂。"]},{"t":"密札","f":"七言律诗","c":["绿窗亲寄砑红笺，十颗明珠抵万千。","秘字不教留札尾，开函先属背人前。","团香作炷要盟久，刻玉为钱卜事圆。","若使常娥推不管，上头还有碧青天。"]},{"t":"别恨","f":"七言律诗","c":["欢爱方浓别恨牵，三生祇结十宵缘。","香丝剪后云鬟乱，罗帕封来粉泪鲜。","花里俄延悲悄悄，梦中寻觅路绵绵。","遥知此后红窗月，一度思量一惘然。"]},{"t":"仙降","f":"七言律诗","c":["九疑仙子七香车，亲降羊权处士家。","风起路传花气息，日高帘射玉光华。","诗才入手眸凝水，酒略沾唇脸泛霞。","赢得墙头村妇满，竹篱茅舍见琼葩。"]},{"t":"书窗即事","f":"七言律诗","c":["妆成手整藕丝裳，立到琉璃砚匣旁。","腕玉特因磨墨健，口脂频度念诗香。","误翻古帖寻花样，偷接私缄解佩囊。","同学二王书法媚，被人猜是仿檀郎。"]},{"t":"半睡","f":"七言律诗","c":["钟铭催月转堂坳，残髻拖针线未抛。","暗曳衣襟知密约，轻钩履舄订先交。","梅阴巳落更番子，豆蔻犹合百结包。","一朵红云看不定，才移眼尾又眉梢。"]},{"t":"纪梦 其一","f":"七言律诗","c":["昨宵春梦太分明，乍倾欢娱作吃惊。","华褥妥时钗暗堕，罗襦解后烛羞擎。","心忪早树啼乌影，胆怯虚廊步舄声。","奇绝大都危绝处，仙游才得到蓬瀛。"]},{"t":"纪梦 其二","f":"七言律诗","c":["辟寒香暖绿熊茵，滑称凝酥转侧身。","枕畔昭仪珠作月，帏中甘后玉生春。","欢称何止卿怜爱，低语还防婢欠伸。","回忆向来翻似梦，矜严意态是何人。"]},{"t":"纪梦 其三","f":"七言律诗","c":["碧桃珠露润无痕，一夜仙源百夜恩。","斜月预通花径路，轻风偏打画楼门。","衣声綷縩搴帷缓，香气氤氲恋被温。","玉洞明知难再返，且申密约近黄昏。"]},{"t":"立夏日作","f":"七言律诗","c":["帘前春事柳绵飞，帘内春人较瘦肥。","赵后身轻宜入掌，沈郎腰细不胜衣。","弓鞋窄得无三寸，锦带量来减一围。","天赐良缘凭玉秤，双双轻重恰投机。"]},{"t":"新妆 其一","f":"七言律诗","c":["素娥新换紫霓裳，十二珠帘尽放光。","骨节非关金佩响，花枝翻借玉肌香。","夜珠神彩能离合，春柳苗条不短长。","内里轻衫齐揭起，天生原爱澹梳妆。"]},{"t":"新妆 其二","f":"七言律诗","c":["洗却浓姿总出尘，十眉图样自翻新。","从来窈窕倾城色，定属聪明绝世人。","三起三眠知柳重，一颦一笑比花真。","为卿别制閒情赋，要与陈思赌感甄。"]},{"t":"可人 其一","f":"七言律诗","c":["春思春愁搅不和，樱桃花下一回过。","即看背影难描画，却露神情教揣摩。","围带早从欢日减，衣香偏出静时多。","卿心如柳侬心水，其奈东风荡漾何。"]},{"t":"可人 其二","f":"七言律诗","c":["邢尹谁当第一俦，最矜严是最风流。","语缘性巧常倾座，酒怕颜赪略举瓯。","乍展画屏微着眼，却拈罗带旋低头。","黄昏几阵芭蕉雨，又被迁延半晌兜。"]},{"t":"慰词","f":"七言律诗","c":["回廊一角海棠阴，罥住低枝碧玉簪。","险计极欢惟握手，惊魂无泪更伤心。","耐烦莫废磨针铁，剖誓休忘约指金。","记取博山炉内火，百年温暖要如今。"]},{"t":"同病","f":"七言律诗","c":["日来同病更相怜，灵药偷将玉合传。","不比怀香防易泄，只难量水为亲煎。","情丝宛转牵如藕，心薏分明苦似莲。","若许玉容偎贴久，神方何必艾三年。"]},{"t":"娇妒 其一","f":"七言律诗","c":["蓦地生疏背画栏，二分推避一分酸。","妒情才显真恩爱，庄语能通暗喜欢。","踏月要防中妇觉，眼风休对小姑看。","乍来花下低声问，昨夜新凉可着寒。"]},{"t":"娇妒 其二","f":"七言律诗","c":["要试檀奴一片心，忽然调笑忽深沉。","花中望见佯佯去，月下闻声缓缓寻。","徐敛欢容浑不采，屡排冷语故相侵。","此身恰与风鸢似，直被柔丝七纵擒。"]},{"t":"妒媒 其一","f":"七言律诗","c":["燕妒莺猜要避嫌，近来行止倍矜严。","描成花样慵针黹，锁定眉痕对镜奁。","倚柱有时情怏怏，扶床终日病恹恹。","明知窗外檀郎过，反托关窗一捲帘。"]},{"t":"妒媒 其二","f":"七言律诗","c":["只隔欢娱不隔情，隔墙苦苦送莺声。","奇香透体闻先醉，软语关心听倍清。","红纸浪裁书百幅，黄昏空剪烛三更。","朝来百计图方便，才得帘前一度行。"]},{"t":"妒媒 其三","f":"七言律诗","c":["一对聪明小凤凰，凭他猜作野鸳鸯。","行间字里心心印，眼角眉梢面面防。","飞语难禁人偶中，廋词休认婢无妨。","金堂妒目如城绕，始悔从前太审详。"]},{"t":"忍笑","f":"七言律诗","c":["丰神林下态河洲，不为情迷骨岂柔。","窥到雪肌微掩敛，引开翠靥渐风流。","两行烛暗人声细，一阵香浓佛手揉。","提起去年今日事，红腮无处躲娇羞。"]},{"t":"晓露","f":"七言律诗","c":["湘帘窣地绿云裁，寂寂鹦哥几遍催。","侍女偷摇团扇去，小郎私泥解围来。","梦中唤起星眸滟，背后惊回秀靥开。","最是残妆难得见，暂停梳洗向妆台。"]},{"t":"生辰曲","f":"七言律诗","c":["锦瑟华年似水流，赪颜犹带嫁时羞。","袖中蜥蜴欢痕褪，发后蝤蛴齧印留。","户耿玉蝇逾半夜，帘霏金粟近中秋。","盟香共拜如环月，稳取团圞在后头。"]},{"t":"踪迹","f":"七言律诗","c":["画帘鹦鹉偶疏防，偷近妆台看晚妆。","斗叶互翻双陆谱，簪花教写十三行。","娇嗔偏喜逢卿怒，欢醉难禁对婢狂。","熟径不愁行触瑟，等他秋月下回廊。"]},{"t":"瑶缄","f":"七言律诗","c":["玉郎苦索定情词，几拂花笺下笔迟。","女伴忽来当面笑，侬家那有背人时。","私书频向窗中展，秘藁偷从枕上思。","只有寻常调笑语，一经香口便成诗。"]},{"t":"玉恙","f":"七言律诗","c":["药炉烟袅篆丝斜，压体浓香翠被纱。","绣枕卸头犹拥髻，银匙颤手自擎茶。","犀株镇定恇还甚，蝶梦潮回热转加。","雪白梨花疑两颊，从中一朵泛桃花。"]},{"t":"小堂","f":"七言律诗","c":["小堂秋气不胜寒，待得人眠月巳残。","灯下剪刀声未放，窗前指甲响轻弹。","料卿步屧关心听，知我房栊蹑足难。","犹恐旁人猜妒起，隔宵先自坐更阑。"]},{"t":"阿侯","f":"七言律诗","c":["惊心妒眼列东西，幽约心齐事不齐。","恐益悲愁颜愈冷，遥猜踪影首先低。","私缄微示红笺露，密坐悬将翠袖携。","戏逗阿侯啼笑起，却探绣褓挽柔荑。"]},{"t":"可恨辞八首 其一","f":"七言律诗","c":["中道风波暂毁妆，纺声凄咽近长廊。","小怜著布光迎面，苏蕙回文曲写肠。","玉色要防西日晒，雪肤争受北风凉。","可知一寸相思意，随著车轮百转忙。"]},{"t":"可恨辞八首 其二","f":"七言律诗","c":["垂帘作节雨萧萧，苦隔相思又两朝。","弱线定随情绪乱，寒灯应带泪痕抛。","坐来自分身难近，别后无如骨暗销。","记否去年飞雪夜，鸭炉心字共香烧。"]},{"t":"可恨辞八首 其三","f":"七言律诗","c":["捣麝为烟玉作尘，当时形迹悔教亲。","姊归空唤春江渡，姑恶方鸣暮雨津。","尽道得愆由薄倖，翻称无福近才人。","隔窗听得消魂语，越不相逢爱越真。"]},{"t":"可恨辞八首 其四","f":"七言律诗","c":["不见含愁见耐惊，一波才息一波生。","王郎已占痴顽福，石尉偏多恚怒声。","转为情深招分浅，自蒙恩重觉身轻。","明眸两剪如秦镜，那用笺书表至诚。"]},{"t":"可恨辞八首 其五","f":"七言律诗","c":["宜男小像供难真，供个维摩示疾身。","萧女精诚惟绣佛，灵芸指爪是针神。","巧凭翻译传情事，频属诗词避熟人。","心似水沉香一缕，随风委曲几时伸。"]},{"t":"可恨辞八首 其六","f":"七言律诗","c":["刻意防闲敛翠襟，隔帘消息太沉沉。","谀辞未必非谗口，诡计何曾是吉音。","身在妒丛潜制泪，人来欢处默关心。","自从听彻琴声夜，已把相如当稿砧。"]},{"t":"可恨辞八首 其七","f":"七言律诗","c":["破除才尽又萦牵，如此相思命在天。","趣入形骸能解脱，欲关情性最缠绵。","蚕丝自缚重重茧，蜡烛空熬寸寸煎。","回忆未成欢爱日，一泓清澈在山泉。"]},{"t":"可恨辞八首 其八","f":"七言律诗","c":["欲扣瑶阊问夙因，醉中心胆近天真。","千秋恨事花三月，四海知音玉一人。","无可奈何身向佛，不曾真个梦为神。","抽刀欲断东流水，又被风吹涨绿鳞。"]},{"t":"兰舟纪遇 其一","f":"七言律诗","c":["半欲天晴半未晴，百禽呜处变春声。","树离圆峤珠先落，月见方诸水自生。","爱极翻教成怨恨，悟来始悔忒聪明。","无情最是堤边柳，眼看桃花带雨倾。"]},{"t":"兰舟纪遇 其二","f":"七言律诗","c":["只在波光淡荡中，橹枝无力忽西东。","难从白日回惊电，反恨青天转顺风。","燕子逼帘时远近，桃花隔竹更玲珑。","如何十二峰峦远，只与阑干一抹同。"]},{"t":"丹诚 其一","f":"七言律诗","c":["桃花输艳雪输明，说阿侯时便说卿。","恐露悲愁增别憾，强为欢笑徇多情。","矜持巳被人猜料，疏远还防事变更。","一任浮云翻覆手，总难离间到丹诚。"]},{"t":"丹诚 其二","f":"七言律诗","c":["豆蔻梢头月一钩，照人欢喜照人愁。","三年已受登墙爱，九死终拚抱柱谋。","敢望犀帷充面首，空分鸾镜挂心头。","赠卿一把珍珠泪，好作金钗钿合收。"]},{"t":"玉楼 其一","f":"七言律诗","c":["一声玉笛倚瑶台，风荡珠帘扇扇开。","祇恐君看犹约略，不关侬影太低徊。","远闻香气和花乱，微接音辞带笑猜。","欲觅仙人来往迹，石阶无纬长春苔。"]},{"t":"玉楼 其二","f":"七言律诗","c":["已闻春病与花疏，又值杨花扑面初。","怨极梦魂思越礼，愁来情性悔知书。","莲含苦意才成实，竹有深心可奈虚。","欲寄綵笺消息去，侍儿诚伪定何如。"]},{"t":"玉楼 其三","f":"七言律诗","c":["红滴胭脂翠滴螺，有人清影独凌波。","似从明月飞来辽，却比清霄艳得多。","珠箔尽教花掩敛，画阑偏受玉摩挲。","春芜一被倾城体，应使人间薄绮罗。"]},{"t":"玉楼 其四","f":"七言律诗","c":["五铢衣薄剪元绡，越衬肌肤雪易消。","静里忽参眉黛活，笑时反助鬓花娇。","无言早信丹诚达，着迹才须绿绮挑。","但使常娥心暗许，未妨白日对青霄。"]},{"t":"即事 其一","f":"七言绝句","c":["梳匀才了画阑凭，双鬓安花百媚增。","为是玉郎亲折赠，碧桃除却换银藤。"]},{"t":"即事 其二","f":"七言绝句","c":["小园春早露华香，偷掐晨葩助晓妆。","如雪花枝如漆鬓，碧纱窗里翠衣裳。"]},{"t":"即事 其三","f":"七言绝句","c":["眼耳丛中分限清，敢将平视效刘桢。","低头只作枯禅坐，暗看莲花贴地生。"]},{"t":"即事 其四","f":"七言绝句","c":["拜月盟星坐彻宵，日长神倦苦无聊。","双眸忽地清如水，对着芳姿睡思消。"]},{"t":"即事 其五","f":"七言绝句","c":["簪花楷格似人妍，下笔明珠个个圆。","除却答郎诗句外，不曾轻易落云笺。"]},{"t":"即事 其六","f":"七言绝句","c":["泪珠和墨写成书，词令风华绰有馀。","但使玉台司笔札，也应唤作女相如。"]},{"t":"即事 其七","f":"七言绝句","c":["水晶帘下恣窥张，半臂才遮菽乳香。","姑射肌肤真似雪，不容人近已生凉。"]},{"t":"即事 其八","f":"七言绝句","c":["鸭鲈心字守香盟，一纸私书百种情。","放着今生缘未了，思量又要订来生。"]},{"t":"即事 其九","f":"七言绝句","c":["愿作鸳鸯梦未成，肯担惊恐始真情。","忍将绝世才兼貌，草草相思过一生。"]},{"t":"即事 其十","f":"七言绝句","c":["情丝细剪与檀奴，纤软才离腻玉肤。","何物生香堪配取，梅花心里数茎须。"]},{"t":"无题 其一","f":"七言律诗","c":["青粉墙头日易沉，每来一刻抵千金。","眼波频遣魂摇荡，眉语能通思款深。","觌面欢愁先在意，病躯塞暖总关心。","此生脱屣功名想，愿举双飞水上禽。"]},{"t":"无题 其二","f":"七言律诗","c":["偷赠新诗妙绝伦，平时拈管却瞒人。","才偏不露方为大，情到能痴始信真。","欲表素心频送睐，难通私语只含颦。","何愁团扇秋风起，比目双身是一身。"]},{"t":"无题 其三","f":"七言律诗","c":["火伞当空不可行，别来十日抵三生。","可能眠食如前胜，略觉风姿比昔清。","缟素农裳逾妩媚，寻常言语尽聪明。","幽窗尽许俄延坐，饱听青荷洒雨声。"]},{"t":"无题 其四","f":"七言律诗","c":["恩重惟拚一命酬，狂心那复恤娇羞。","行云神女难为夜，奔月垣娥自耐秋。","梦好惜无痕可记，香消还有誓长留。","两情但使如金石，不作鸳鸯死不休。"]},{"t":"慰个人 其一","f":"七言绝句","c":["已苦鸳鸯锦翼分，祇留弱息慰文君。","罡风又夺明珠去，从此孤身似片云。"]},{"t":"慰个人 其二","f":"七言绝句","c":["往事前尘付逝波，何须清泪滴银河。","仙家瑶草原无种，不似桃花结子多。"]},{"t":"维摩示疾志感","f":"七言律诗","c":["天女云軿下碧空，维摩丈室顿春融。","悄移画屧防惊枕，微揭绡帏恐透风。","有泪但看含脉脉，无言祇索去匆匆。","再三珍重临行意，只在横波一转中。"]},{"t":"无题","f":"五言古诗","c":["天女凌华婉，神人韩子湘。","奇缘逢汉浦，宿分阻高唐。","交甫曾投佩，云英可乞浆。","屡通姜氏信，总恕阮生狂。","目语当窗送，琴心隔座商。","事虽殊卓女，情早许刘郎。","佳约常敲月，幽期每犯霜。","步声才蹀躞，帘额已飞扬。","欲露全身影，先舒半面妆。","来时窥了了，见后走佯佯。","实怨身难近，聊称礼自防。","潜裁红锦袜，偷送紫罗囊。","好句奁中绣，私书袖底藏。","他生期蛱蝶，来世效鸳鸯。","瑶札频催试，缗钱暗润装。","临歧颜黯惨，远送意徬徨。","归梦萦珠帐，轻身到玉堂。","暂回辞弱水，小住觅柔乡。","芳意宁知变，仙踪不可望。","无由排邃闼，空自绕修廊。","寒雾迷金屋，飞泉障石粱。","摩挲存旧物，思忆启缄箱。","戚氏彄环重，麻姑指爪长。","青丝封一握，素纸擘千张。","乌鲗盟犹在，红鸾愿岂忘。","卿诚薄韩寿，我肯负兰香。","文胄针双络，繁钦泪两行。","明星昭密誓，皦日鉴回肠。","剖腹难陈诉，题诗倍惋伤。","丹诚如不灭，片语报王昌。"]},{"t":"内人指甲","f":"七言绝句","c":["不爱匀黄不染丹，生来偏喜近豪端。","只因久惯拈花后，落剪依然气似兰。"]},{"t":"书所见","f":"七言绝句","c":["环佩璆然脸晕潮，露华喷著海棠娇。","愁他烛影摇红里，映得梨花暖欲消。"]},{"t":"重认","f":"七言绝句","c":["重认天台路不差，花中艳煞碧桃花。","人间无此娇红色，除是青天一片霞。"]},{"t":"别惊 其一","f":"七言律诗","c":["九十莺花日日忙，行歌到处识清狂。","曾无齿受金梭折，旧有才蒙玉尺量。","仙籍可能通弱水，诗名早巳播柔乡。","终拚夺取芙蓉镜，送喜妆台玉镜旁。"]},{"t":"别惊 其二","f":"七言律诗","c":["九州才得一知音，况是聪明绝世心。","直谓才华无我敌，每将诗句背人吟。","私书纵写愁空阁，别泪难流恨始深。","只有丹诚期报答，不逢君更不弹琴。"]},{"t":"寄远","f":"七言绝句","c":["画楼烟雨泼双湖，六六鸳鸯对岸呼。","为问语儿亭畔柳，春波绿似去年无。"]},{"t":"舟中月夜","f":"七言绝句","c":["蓬窗深闭奈愁何，恐见姮娥愁更多。","此际夜明帘底月，有人无那注横波。"]},{"t":"题闺人团扇","f":"七言古诗","c":["秋天薄如纸欲飞，秋云乱卸秋罗衣。","碧空无人紫箫响，灵风来往皆真妃。","月中素娥面如月，青女霜中带霜骨。","清气都乘白帝凝，冰心共守青天活。","相对婵娟秋夜长，看他织女度银潢。","月作明珠来赠嫁，霜为铅粉助亲妆。","须臾花发黄金粟，玉杵捣香香万斛。","纨扇遥开三界闻，霓裳舞散诸天馥。","分明擎出一枝斜，要与人间富贵家。","赢得少年齐仰首，不知若个得簪花。","卿家扇子清风发，洁若秋霜激如月。","欲识云中缥缈仙，先参画里芙蓉阙。","霜月同时藻鉴开，一双仙影下瑶台。","意中早有探花客，故著青衣仔细猜。"]},{"t":"烧香曲","f":"七言律诗","c":["红窗十二扇明纱，喜鹊催成两鬓鸦。","背影玲珑俱绝世，才情宛转总宜家。","工诗惯削檀郎草，解语亲擎绣佛花。","手爇水沉香一缕，月轮心事镜年华。"]},{"t":"红楼","f":"七言律诗","c":["闻声睹影尽聪明，心似荷珠滴滴倾。","新月痕留眉际澹，幽兰香自骨中生。","呼为才子名俱艳，供作观音画不成。","隔着红楼亲下拜，可怜情重觉身轻。"]},{"t":"九月见碧桃花","f":"七言绝句","c":["记得花飞洞口天，重逢又值小春前。","芳心更比侬情热，那忍相离到隔年。"]},{"t":"书悔","f":"七言律诗","c":["过后思量百悔迟，昨宵当面错良期。","玉盘谏果亲传出，瑶札情悰密递知。","蹑迹潜教人静后，卸头明示睡来时。","如何误会消魂意，半晌绸缪只论诗。"]},{"t":"夏晓","f":"七言律诗","c":["似闻蝙蝠拂帘旌，手揽铢衣笑出迎。","一种风情初睡起，半偏云髻未梳成。","眼波钩去魂先荡，心火然来胆易惊。","身愿化为珠露点，天风吹向玉盘倾。"]},{"t":"林下 其一","f":"七言律诗","c":["洞房香雾罨朦胧，唤起惺忪浅梦中。","直与春风俱淡荡，若临秋水更玲珑。","前身合是沉檀化，到眼能教粉黛空。","才见萧然林下品，一经芳泽便雷同。"]},{"t":"林下 其二","f":"七言律诗","c":["环佩珊然落九霄，珠圆心事玉华雕。","生成仙骨非丹换，朗彻神情要白描。","浴罢不愁云鬓乱，灯前还怕雪肌消。","料应除却盘龙镜，那得人间有二乔。"]},{"t":"林下 其三","f":"七言律诗","c":["彻底聪明藕共莲，情深何碍旧生天。","吹来语气香如佛，修到身旁坐亦仙。","绝色也敦名土品，奇才只受美人怜。","他生愿化双蝴蝶，一绕裙边一鬓边。"]},{"t":"林下 其四","f":"七言律诗","c":["锦瑟年华似水添，红蛛送喜鹊巡檐。","春痕宛转裙双幅，秋影澄泓月一帘。","戏咒灯花佳谶卜，楷书贝叶小名签。","芳心托付消魂处，只在眉尖与指尖。"]},{"t":"林下 其五","f":"七言律诗","c":["憔悴秋容怨小春，碧桃花里露丰神。","乍搴绣幕容通语，略近妆台却敛身。","莫讶至情翻似客，可知相敬本如宾。","无端一点关心处，还恐旁人看得真。"]},{"t":"林下 其六","f":"七言律诗","c":["惊才绝艳总缘情，百节疏通百媚生。","便到中年乃绝世，但留小影足倾城。","月安眉际三分曲，秋在心头一字横。","长笛自吹花自落，不知何事又干卿。"]},{"t":"意中人 其一","f":"七言律诗","c":["万树夭桃百啭莺，意中别有最倾城。","神楼缕缈身难到，心地空灵目已成。","水月镜花偏可恋，农香人影总多情。","扫除倚翠偎红念，消受相思过一生。"]},{"t":"意中人 其二","f":"七言律诗","c":["楼前花放下楼行，态自矜严体自轻。","语出眉梢须领会，波生眼角定聪明。","罗襦难掩肌香透，纨扇犹缘脸晕擎。","越近中年人越艳，半关风韵半关情。"]},{"t":"意中人 其三","f":"七言律诗","c":["画堂前后寂无人，逼近丰容看个真。","那料窗中先着眼，却逢帘底乍回身。","为卿来意情应会，教婢传声语实亲。","平日持家风格峻，不曾轻易露微嚬。"]},{"t":"意中人 其四","f":"七言律诗","c":["不是琴挑卓女丝，不关天壤恨凝之。","若论才调原如婿，祇觉聪明独让伊。","过眼风情俱是约，真心恩爱本非私。","愁来只怨天多事，偏有今生见面时。"]},{"t":"索书","f":"七言律诗","c":["玉纤亲举墨隆隆，索写簪花仿帖工。","着意防闲帘幕外，关心燥湿砚池中。","深情暗托双钩递，私语潜凭一字通。","绝妙人前留客计，教侬端楷莫匆匆。"]},{"t":"芳姿","f":"七言律诗","c":["凭阑千里渺相思，说与西风总不知。","一片落花人去久，二分明月客眠迟。","事经可喜皆如梦，情到无聊便是痴。","青粉墙高在天上，却书团扇寄芳姿。"]},{"t":"寒绣词","f":"七言律诗","c":["一点芳心不忍瞒，买丝亲绣与君看。","金针窍本玲珑透，綵线纹都宛转盘。","灯影挑残花络索，钗痕刻到月阑干。","拈毫呵尽冰壶墨，未报寒窗十指寒。"]},{"t":"曲题","f":"七言律诗","c":["曲阑风定雨初晴，瞥面花光识是卿。","弱腕一双金钏重，颓云十二玉钗横。","芭蕉尽可藏人影，鹦鹉刚无唤客声。","不敢搴帘通一顾，恐教着眼太分明。"]},{"t":"疑悰","f":"七言律诗","c":["千呼万唤隔帘旌，未肯同眸一笑迎。","此地不应犹碍婢，平时始悔错怜卿。","偎依转傍生人热，恩分翻缘熟极轻。","那怪幼舆遭折齿，东家邻女本无情。"]},{"t":"仙踪二首 其一","f":"七言律诗","c":["十二琼楼境宛然，杏花亲折玉台前。","愁痕祇觉双眉重，春气偏增两颊妍。","别不多时看越好，俏无人处见犹怜。","东风一觉流莺梦，又报红窗柳脱绵。"]},{"t":"仙踪二首 其二","f":"七言律诗","c":["明珠捧出价难论，筑玉丰姿剪雪痕。","小字呼来仙有骨，双眸着处佛销魂。","偶临浅水教花妒，若化轻云定月奔。","一粒江南红豆子，还依芳草长情根。"]},{"t":"远归奏记妆楼 其一","f":"七言律诗","c":["红楼咫尺是蓬瀛，手展文窗扇扇明。","裙带早徵三日解，罗衣特为一人更。","花阴匝地常如水，云气漫天忽漏晴。","坐久思量才省得，分明来使出帘迎。"]},{"t":"远归奏记妆楼 其二","f":"七言律诗","c":["经过瞥眼画楼中，来是无言去又空。","情在不言须领会，事除有迹尽通融。","白描素影花双箭，难缩蓝桥地一弓。","但得朝朝见明月，也如身到广寒宫。"]},{"t":"赠春芜 其一","f":"七言绝句","c":["覆额轻云覆体绡，风前摇曳正苗条。","侬心自为香兰醉，嗅得蘼芜意亦消。"]},{"t":"赠春芜 其二","f":"七言绝句","c":["染翰朝朝侍镜台，簪花仿格许亲开。","郑家枉诵葩经熟，未带温柔福分来。"]},{"t":"衣香","f":"七言律诗","c":["玉雪狸奴感主恩，当帘深护洞房门。","柳腰入抱疑无骨，梨颊偎人怕有痕。","何处星辰移碧落，此时风露近黄昏。","归来不敢人前坐，衣上馀香一月温。"]},{"t":"声影","f":"七言律诗","c":["一声玉笛海天空，十二楼台面面通。","人影与梅同隐约，月光兼雪更玲珑。","生香忽起疏帘外，私语偏闻小阁中。","真个消魂原是假，赚他灯蕊结双红。"]},{"t":"心香","f":"七言律诗","c":["十二红窗手展迟，眉能为语目通辞。","柔乡福分输卿婿，绝世聪明足我师。","水底更无容藕处，泥中或有见莲时。","丹城一片何由达，愿捧心香拜茂漪。"]},{"t":"夏夕","f":"七言律诗","c":["蝉翼轻衫杏子红，纱巾浴罢出帘栊。","风扶绿水莲初起，云让青天月正中。","香气似传肌细腻，光华翻逼眼朦胧。","无端惆怅无端喜，一度凭阑幸不空。"]},{"t":"盛暑","f":"七言律诗","c":["彻夜难安小阁眠，消魂入处尺书传。","缘知弱质支离苦，却累深情宛转怜。","蜡烛有心偏暖热，藕丝无孔不缠绵。","分明一纸相思字，抵得清凉万斛泉。"]},{"t":"惆怅 其一","f":"七言律诗","c":["当年小住郁金堂，一折屏山近曲房。","夜月潜踪听响屧，晨葩偷掐供梳妆。","百愁对我欢成笑，十索瞒人苦要偿。","今日藕丝风剪断，相看单道莫思量。"]},{"t":"惆怅 其二","f":"七言律诗","c":["昨朝仙佩下江皋，赠我丁香百结绦。","似诉隐肠难解系，不辞纤手为亲缫。","缠绵正好笼梳发，宛转何从落剪刀。","一线深恩重挂起，鬓丝撩乱玉频搔。"]},{"t":"晓睡","f":"七言律诗","c":["桃笙难得一宵宜，偏是郎来妾起迟。","连夕可曾成稳睡，此时何事触炎曦。","花浮磁盎霞犹湿，镜掩纹台月未移。","翻把罗帏低放下，玉肌消减怕教知。"]},{"t":"晚妆","f":"七言律诗","c":["最高楼阁倚雕阑，一种光华射月寒。","心有幽期要佛證，身从明处任郎看。","芙蓉堕髻连云重，蕉葛裁衫映雪单。","恰是不曾当面错，料应欢意似侬欢。"]},{"t":"病讯","f":"七言律诗","c":["日炙红酥汗体香，玉人小病倚银床。","心如莲子中间苦，面带葵花一半黄。","小婢那知窥喜怒，庸医枉自臆温凉。","君身何作灵芝药，只许侬看不许尝。"]},{"t":"赠花","f":"七言律诗","c":["小朵华鬘向夕开，玉纤亲摘赐妆台。","要君魂梦都香透，似我肌肤得傍来。","倘置仙鬟茑亦好，便将佛座供应该。","他时憔悴终怜惜，况捧仙妍雪一堆。"]},{"t":"恩波","f":"七言律诗","c":["受恩容易报恩难，难在深情事事瞒。","怜我病躯如婿弱，要郎珍重使侬安。","语经述口犹香气，影亦消魂耐细看。","今日露华浓似酒，始知身自作荷盘。"]},{"t":"仙人","f":"七言律诗","c":["姑射仙人碧玉家，一泓秋水托轻纱。","常缘养病兼锄药，偶罢烧香为护花。","垂帐怕闻灯气息，悬珠白放月光华。","饶卿静极难遮艳，脸际横波接媚霞。"]},{"t":"翠荚","f":"七言律诗","c":["翠荚新看一瓣生，鹦哥唤后兽环鸣。","罗衣耐热曾缘我，茗椀先凉最感卿。","众里眼波潜送媚，閒中口角总关情。","炎风如炙云如火，值得今朝触暑行。"]},{"t":"天台图","f":"七言律诗","c":["桃花流水影参差，刚是胡麻饭熟时。","笑语暗闻天上落，星辰偷向月边移。","授来灵笈须频检，捧出云浆未忍辞。","身到人间增怅惘，石粱临渡合迟迟。"]},{"t":"梳头词 其一","f":"七言绝句","c":["委地香云散不纷，何曾露盥与兰薰。","风前自把轻纨扇，扇与檀郎仔细闻。"]},{"t":"梳头词 其二","f":"七言绝句","c":["炎曦不耐挽云堆，巧髻分梳蝶翅开。","自出侬家新样子，要将名色试郎猜。"]},{"t":"梳头词 其三","f":"七言绝句","c":["懒梳云髻太峨峨，挽个家常髻似螺。","一幅白描南海像，只差莲瓣瘦凌波。"]},{"t":"梳头词 其四","f":"七言绝句","c":["玉色琼梳两不分，镜奁都作月波纹。","水晶帘子风微卷，一树梨花一朵云。"]},{"t":"咏协兰阁茉莉","f":"七言律诗","c":["浓香五百朵齐开，绣阁分移到玉台。","自是芳心工选择，更逢仙手善栽培。","晚风劝插高堂鬓，馀雪从教满案堆。","闻道城南秋水婢，寄书翻为索花来。"]},{"t":"谢女","f":"七言律诗","c":["五尺轻绡曳佩琚，天然清水出芙蕖。","人缘倾国光常敛，仙亦宜家俗自除。","旷世一空脂粉黛，中闺三绝画诗书。","若将玉尺量才子，正恐相如愧不如。"]},{"t":"懊侬","f":"七言律诗","c":["最好无情最苦情，思量百恨总情生。","恩深要断他人宠，痴绝求坚隔世盟。","月为速圆翻易缺，风才微顺又兼横。","閒阶一缕沾泥絮，曾向楼头赴蝶轻。"]},{"t":"知己","f":"七言律诗","c":["弹彻峨眉响雪琴，三生石上少知音。","一双仙佩殷勤下，十里桃花曲折深。","授我神方皆上口，负他鬼谤亦甘心。","酬恩剩有琼瑰泪，洒作秋空片片阴。"]},{"t":"秋怀","f":"七言律诗","c":["仙露泠泠滴晚蕖，隔江消息近何如。","天长祇许同看月，路远还防错寄书。","蝶梦人耶人梦蝶，鱼知我否我知鱼。","淩风欲趁如船藕，一叩潇湘帝子居。"]},{"t":"露立","f":"七言律诗","c":["西风刀尺几时休，盼煞青天月一钩。","燕剪原知多宛转，蚕丝祇恐太绸缪。","言无人达难成信，秋上心来尽是愁。","苦立夜深凉露下，遥陪灯火玉楼头。"]},{"t":"香梦","f":"七言律诗","c":["月华如雪满琼楼，楼上齐悬翡翠钩。","云气空濛连渤海，花光离合是罗浮。","洛神自许遮须国，织女曾逢博望侯。","身惹玉炉香不散，醒时翻替梦时愁。"]},{"t":"夜过妆阁","f":"七言律诗","c":["相思不见还相觅，三日休嫌两度来。","无月且将明烛忆，有花须趁好时开。","冰盘捧出经仙手，綵笔吟成自主裁。","为报维摩秋病起，愿随天女进霞杯。"]},{"t":"玉台","f":"七言律诗","c":["玻璃为障玉为台，一点灵犀自辟埃。","花片欲随双管落，诗情都傍九天来。","妆临秋水清无染，梦与湘云撇不开。","事事要如明月满，昨宵眉影画刚裁。"]},{"t":"皈依","f":"七言律诗","c":["綵云飞下十三楼，悄立屏山最后头。","离客香风才一尺，照人秋月是双眸。","瘷声临去讹中妇，笑靥微圆认阿侯。","我已皈依仙座下，见花无那转含愁。"]},{"t":"秋九即事","f":"七言律诗","c":["云母屏开晓镜移，綵鸾如与玉蟾期。","花依瘦骨工摹影，酒入欢肠不透肌。","仙佩远闻鸣琥珀，神光早见彻玻璃。","深情要以香炉火，热太心焦暖最宜。"]},{"t":"再奏妆楼","f":"七言律诗","c":["管夫人画易安诗，二妙能兼冠一时。","清净福还分婿享，温柔情恰与家宜。","楼高碧落心同寄，秋到黄花影独知。","自有闺中千古在，漫劳王母赐余卮。"]},{"t":"常娥","f":"七言律诗","c":["本是常娥一辈人，木樨开日作生辰。","大江南北无其偶，明月中间着此身。","筠管著书偏自富，荆钗绝口不首贫。","直将冰雪都消净，秋水空灵为写真。"]},{"t":"隔水楼高","f":"七言律诗","c":["思君不见且寻君，隔水楼高未夕曛。","正欲与言三夜梦，只馀迎面一窗云。","竹阴深护湘帘碧，兰气微沾茗盌芬。","手拂银墙留句在，好教惆怅到宵分。"]},{"t":"怀远","f":"七言律诗","c":["吴山青接越山青，愁思如云入杳冥。","镜影已看虚一月，香盟犹忆对双星。","揉残诗草书难寄，挑尽灯花兆不灵。","梦里相逢了无益，秋来况是梦苏醒。"]},{"t":"花影","f":"七言律诗","c":["水中花影太夸犹，香不能沾影自留。","咫尺直须论万里，终朝何止似三秋。","月临窗纸将穿眼，风透帘栊未上钩。","此是最消魂境界，蓬山何处海西头。"]},{"t":"冲寒","f":"七言律诗","c":["相见明知枉断肠，相违无奈便思量。","来如江上潮通信，人似天边月放光。","风勒暗香穿小阁，花迷清影转回廊。","玉池常赐云浆暖，那惜冲寒度石梁。"]},{"t":"护萱","f":"七言律诗","c":["书阁沉沉闭寂寥，药炉烟影伴昏朝。","潜来外院金钱卜，暂撤中厨玉膳调。","围带已随秋月减，芳心休逐夜香焦。","仙人手护忘忧草，历尽冰霜定不凋。"]},{"t":"秋夕即事","f":"七言律诗","c":["越到矇胧见越真，暗香霏雾细如尘。","烟中摇曳还生玉，月里依稀定有人。","花为遥看须正面，山从低处得全身。","此情不料卿能会，始觉兰香果是神。"]},{"t":"翠袖","f":"七言律诗","c":["翠袖亭亭倚暮寒，手裁慈竹护平安。","临风玉臂娇难举，平日金条约渐宽。","霜杵敢辞亲和药，银匙还要劝加餐。","暂偷半晌支颐坐，缫笔无心拂素纨。"]},{"t":"瑶池","f":"七言律诗","c":["佩声何日返层台，十二文窗绝点埃。","宝鸭暗烧心火热，银蟾清对眼波来。","觞飞灵液和云捣，裙拂仙葩带露开。","辛苦瑶池陪阿母，芙蕖双颊减丰裁。"]},{"t":"画廊","f":"七言律诗","c":["郁金堂北画廊深，云弄秋光月弄阴。","殊色芙蕖偏并蒂，异香兰蕙本同心。","吴宫自漾珠帘影，楚水都含玉佩音。","毕竟昭阳谁第一，尹夫人在不须寻。"]},{"t":"道是","f":"七言律诗","c":["道是才人是美人，前身端是屈灵均。","心思有孔皆生慧，眉睫无愁亦带颦。","爱极难将诗句写，缘悭只许画图亲。","分明一片潇湘水，莫为惊鸿误洛神。"]},{"t":"口寒阻","f":"七言律诗","c":["霜肃风凄不可行，转缘情重似无情。","修成蛱蝶原孤梦，订定鸳鸯是再生。","银烛几曾知喜恨，金钱空为卜阴晴。","分明见面仍河汉，却费相思到五更。"]},{"t":"妒菊","f":"七言律诗","c":["鹦哥见客唤帘栊，乙字银钩漾好风。","屏影欲翔花宛转，窗光先映雪玲珑。","情辞远托双眉递，羞晕微添两颊烘。","瓶菊如星看渐减，每朝侥倖上钗丛。"]},{"t":"三妇艳 其一","f":"七言律诗","c":["佩环宛转下瑶京，五百仙中第一名。","大地寒消春艳冶，中天云净月空明。","欲求髣髴还形影，爱读离骚见性情。","除却潇湘烟水上，人间何处着卿卿。"]},{"t":"三妇艳 其二","f":"七言律诗","c":["翡翠帘栊透日华，窗光迎面泛朝霞。","清癯未称金为屋，朗彻原应月是家。","百窍含香非豆蔻，一生偏爱属梅花。","慧心那有纤尘起，脆雪分明在齿牙。"]},{"t":"三妇艳 其三","f":"七言律诗","c":["风韵飘飘落半天，左芬才调本如仙。","聪明解道因风絮，潇洒真同出水莲。","泼茗偶同开口笑，拥书常不卸头眠。","一春花下芳踪少，只在琉璃砚匣边。"]},{"t":"病讯 其一","f":"七言律诗","c":["向晚飞鸿报远音，玉人秋病为谁深。","肝虚枉自煎银叶，背冷应嫌压绣衾。","楼下人行还侧耳，瓶中花落漫经心。","丰容回想清癯甚，耐过重阳又到今。"]},{"t":"病讯 其二","f":"七言律诗","c":["写赋私书欲寄难，灯前翻覆自家看。","灵方未必全关药，软语何劳更劝餐。","况隔重门如梦里，应防孤枕触愁端。","缄成依旧潜烧却，两字单留是问安。"]},{"t":"寒况","f":"七言律诗","c":["凄寒事事易消魂，况是西风雨打门。","击楫谁迎桃叶渡，捧心又病苧萝村。","鱼鳞剖去空无信，獭髓涂来怕有痕。","吹灭幽窗桦烛坐，不教孤影伴黄昏。"]},{"t":"有答","f":"七言律诗","c":["佩响帘栊屧响苔，嫣然一笑百花开。","光生殿角惊同列，慧辨宫商叹异才。","交颈鸳鸯亲绣出，随身蛱蝶自飞来。","新恩暂渴金盘露，已是椒房中选材。"]},{"t":"次韵再答","f":"七言律诗","c":["聚锦秋生玉砌苔，瑶缄湘帙对香开。","吟成检点无邪思，曲罢倾输有善才。","抱石自盟心不转，买丝非绣佛如来。","绿窗一树孤桐影，知是琴材是瑟材。"]},{"t":"玉尺词","f":"七言律诗","c":["何人玉尺敢量诗，楼上昭容字婉儿。","秋月剪眸书万卷，春花着手笔双枝。","捧来香气含薇露，评出芳心费藕丝。","却笑卫家风调别，祇将八法授羲之。"]},{"t":"秋楼","f":"七言律诗","c":["一楼秋气太苏醒，病起新妆出画屏。","花入瘦来偏旖旎，柳经眠后更娉婷。","食单尚饬中厨禁，绣剪应知小阁停。","愁绝绿窗风影里，远山早睹一痕青。"]},{"t":"玉阶","f":"七言律诗","c":["望影猜声巳断魂，况容平视近中门。","楚天含雨常疑碧，湘水和云不着痕。","仙要几生修得到，佛因无尔敢称尊。","玉阶秋草临纤步，翻许亲承足下恩。"]},{"t":"叠韵三答","f":"七言律诗","c":["压鬓花钿翠似苔，文窗窈窕竹间开。","风情别有三生契，月旦能空一世才。","身为聪明常病扰，光因亲合觉神来。","幽兰带得骚人性，合是灵均作赋材。"]},{"t":"叠韵四答","f":"七言律诗","c":["楼中凤屧不沾苔，楼上珠帘飏日开。","无目亦应知绝色，有情方许得兼才。","衣翔轻影愁仙去，镜迸圆光讶佛来。","朔雪梅花春月柳，是卿身分是身材。"]},{"t":"展画","f":"七言律诗","c":["西风渺渺洞庭寒，环佩声虚罢采兰。","巫峡峰峦偏侧好，楚天云雨欲晴难。","翩翩翠凤旗空下，缥缈苍龙瑟自弹。","一片澄泓湘水在，不如归展画图看。"]},{"t":"誓约","f":"七言律诗","c":["宝鸭添香彻底温，思量一遍尽消魂。","金针刺绣连诗赠，瑶札焚灰和酒吞。","年与水波看渐长，事如花影过无痕。","鸳鸯只誓来生约，拚负深情不负恩。"]},{"t":"叠韵五答","f":"七言律诗","c":["绿窗间闭锦纹苔，落尽春灯销未开。","怕听子规添旧恨，偶翻花样见新才。","玉屏罢算围棋劫，瑶札偏期斗草来。","偶抱雪猧犹胆怯，当熊终竟是粗材。"]},{"t":"回廊","f":"七言律诗","c":["回廊曲折遇芳踪，髻影低围钏影松。","西子纱衾间自浣，小怜玉杵偶亲舂。","憨来略比司花女，痴绝求为买菜佣。","深院日斜帘幕下，泥人刚道是娇慵。"]},{"t":"新病","f":"七言律诗","c":["近如蟾亦远如蟾，心自通融迹自严。","极检点时惟手札，最分明语在眉尖。","乍中年纪花三月，不定情悰絮一帘。","才是几朝贪染翰，绿窗又报病愁添。"]},{"t":"寒悰 其一","f":"七言律诗","c":["一寸工夫一寸金，不多时别更情深。","相看消瘦还如旧，孤负清秋直到今。","悲喜此时难露面，寒暄常语亦关心。","茶瓯暂作留君计，不是临行不教斟。"]},{"t":"寒悰 其二","f":"七言律诗","c":["炉烟摇漾奈风何，似妾心头委曲多。","担得虚名招嫉妒，悔因坚约致蹉跎。","双关语秘瞒青鸟，一尺身悬抵绛河。","剩有悲愁相对分，不忙时节定来过。"]},{"t":"病述 其一","f":"七言律诗","c":["十二文窗扇扇关，清眠消受病中间。","强将笑语酬夫婿，拚得摩挲累小鬟。","蓬鬓簪花翻更好，丛笺堆草倦加删。","别饶心事常温处，银叶甜香炷博山。"]},{"t":"病述 其二","f":"七言律诗","c":["不知嗔燕是嗔莺，病颊红潮一缕生。","有甚薄言偏往愬，无端失手又翻羹。","几曾喜怒轻颦笑，转为温柔郁性情。","究竟深愁难料着，檀郎枉自负聪明。"]},{"t":"忍姑 其一","f":"七言律诗","c":["月有方诸铁有磁，不容相近转相思。","炉灰至死中心热，蜡烛难烧一味痴。","别后思量偏嚏觉，来时欢喜只腰知。","凭他妒眼应无计，剪到柔肠寸寸丝。"]},{"t":"忍姑 其二","f":"七言律诗","c":["偶然相见郁金堂，收却聪明敛却狂。","茗椀未妨留熟客，熏炉何患泄生香。","祇馀典午清言习，那用仓庚疗妒方。","若许天台长借住，桃花翻看得寻常。"]},{"t":"解嘲","f":"七言律诗","c":["蚕眠小字綵笺投，绛帐遥开白玉楼。","自是上官真慧眼，非关内史肯低头。","裁将桃李成香阁，薰到芝兰借翠篝。","值得旁人姗笑起，胜他长跪见公侯。"]},{"t":"寒闺","f":"七言律诗","c":["小窗寒意晚来严，瘦玉腰支半臂添。","睡思不堪将茗破，病怀偏觉与香嫌。","间和镜影论心曲，只许炉熏着指尖。","正是扑帘风信紧，为谁轻立到琼檐。"]},{"t":"晓堂","f":"七言律诗","c":["晓堂风格太矜严，强起佯佯倚绣帘。","隐语百无半妒忌，灵心一半避猜嫌。","河深未许填乌鹊，天阔才容见素蟾。","却忆小屏山角事，烛花昏暗雨廉纤。"]},{"t":"银潢","f":"七言律诗","c":["红楼隔雨似潇湘，梅额才呈半面妆。","绝不抬头心自会，早知着眼愿都偿。","云行水上原无迹，风过花中已得香。","脩到神仙夫妇分，未妨长县隔银潢。"]},{"t":"书愤","f":"七言律诗","c":["绝无波处忽生澜，如此情场涉历难。","本不嫌疑何用避，果然礼法那须拦。","花缘香极能招蠹，酒为甘多易致酸。","只隔一重棂槛地，青天碧海路漫漫。"]},{"t":"晨妆","f":"七言律诗","c":["玉楼清晓整严妆，坐到花阴转曲廊。","乍听舄声先认迹，才窥钗影巳闻香。","偏逢外院开金钥，未许中门度石梁。","娇鸟漫歌泥滑滑，从来辛苦做萧郎。"]},{"t":"屏山","f":"七言律诗","c":["门外鹦哥唤客来，金堂亲揭绣帘开。","重裘不改纤腰柳，低髻初围磬口梅。","暗炷甜香笼麝火，潜催苦茗拭螺杯。","此身贪与郎依傍，才转屏山又折回。"]},{"t":"赋得吹气如兰有赠","f":"五言古诗","c":["之子如兰质，天然胜麝芬。","一丝清气吐，四座妙香闻。","舌有生花本，心原得蕙薰。","转喉先馥郁，粲齿便氤氲。","呵罢疑成露，吹来欲化云。","人宜湘水住，风自谢庭分。","莫认秋英佩，非关午篆焚。","馀芳还竟体，沾惹到同群。"]},{"t":"春感","f":"七言律诗","c":["淅沥西风透晚寒，画屏前事忆漫漫。","抱香蝴蝶魂犹颤，承露芙蓉泪未乾。","缘阻自怜生我早，情多方信做人难。","愿将心化中天月，不是知音亦与看。"]},{"t":"雨 其一","f":"七言律诗","c":["一声清脆玉钩鸣，手整鸾钗笑出迎。","是甚好风吹得至，如何微雨滑能行。","花阴匝地都成障，云气漫天未定晴。","可奈流莺衔不得，红栏的的绽朱樱。"]},{"t":"雨 其二","f":"七言律诗","c":["新妆灼灼比花娇，隔雨看如隔雾绡。","知我欲来开小阁，累卿久立倚疏寮。","莺声自教双鬟度，燕睇先偷四目招。","可是玉楼天半迥，湘帘更复障条条。"]},{"t":"缚笔词","f":"七言律诗","c":["翠羽离披渐不才，素丝缠缚荷妆台。","几成鬓发蓬松候，却费心思约束来。","墨要浓时如意态，书须瘦绝称身材。","从今只作兰花蕊，任尔纵横莫放开。"]},{"t":"春游","f":"七言律诗","c":["云叶为帆藕作舟，一双神女弄珠游。","堤边柳亦争舒眼，舻后山多欲掉头。","环燕任人施月旦，尹邢各自占风流。","侍儿一种倾城色，已是桃花见面羞。"]},{"t":"仙人","f":"七言律诗","c":["姑射仙人缥缈间，乘风一片綵云还。","眼波自注潇湘水，眉黛遥分宛委山。","梦好巳拚星独宿，情深能使月连环。","分明只坐芙蓉里，隔著轻烟不可攀。"]},{"t":"手札","f":"七言律诗","c":["一纸私书密语温，缄封犹自带啼痕。","愿郎自保风霜体，胜妾亲承雨露恩。","隔世有盟须结发，今生无益枉销魂。","凄凉那忍低徊读，烛下焚灰并泪吞。"]},{"t":"病耗","f":"七言律诗","c":["深昼间垂窣地帘，双鬟又报病恹恹。","巳妨听雨三宵睡，还是看花一日添。","凤子魂灵空澹荡，鹦哥声影亦沉潜。","回廊值得移时立，翻恨今朝莫避嫌。"]},{"t":"曲意","f":"七言律诗","c":["无意莺啼恰恰啼，曲阑东畔画廊西。","未知人影香先至，得近花光目转迷。","略罥帘旌钗欲溜，似拈裙带首旋低。","相逢已是空惆怅，况更相逢未必齐。"]},{"t":"花下","f":"七言律诗","c":["碧桃花下定相寻，道我铂魂恐不禁。","岂有容如明月好，祇缘情比绿波深。","痴云未散终成雨，顽铁能磨尚作针。","就使春残秋更艳，莫添无益祇伤心。"]},{"t":"情悰","f":"七言律诗","c":["恻恻东风透骨寒，罗衣映雪五铢单。","焦心守定香边誓，忍泪偷从烛后弹。","凄婉笛声三五夜，玲珑花影一重阑。","蜘蛛送喜鹃啼恨，此刻情悰恰两难。"]},{"t":"邂逅","f":"七言律诗","c":["绝不相思思转深，隔年看见到如今。","飞花着雨犹粘树，残线临风强度针。","事秘怕人偏料得，梦醒还自费追寻。","如何邂逅翻羞涩，心在郎边眼在心。"]},{"t":"病讯","f":"七言律诗","c":["茜子红杉水样柔，轻寒恻恻下帘钩。","肌肤越显娇如雪，丰韵偏宜瘦似秋。","为我关心犹强笑，妮他回首却微羞。","但令蜜味中边满，幽恨原非药可瘳。"]},{"t":"青粉墙头","f":"七言律诗","c":["青粉墙头碧玉檐，柳条金嫩罩纤纤。","似无人在空飞絮，疑有风来忽卷帘。","清脆铃声兼语细，模糊花气杂香甜。","情深那用多相见，犹恐金堂未免嫌。"]},{"t":"双艳词","f":"七言律诗","c":["一树垂杨一画船，绮罗丛里斗婵娟。","香虽异种闻皆醉，莺有回声啭各圆。","比作花枝应姊妹，脱离烟火便神仙。","心头不是天人影，如此倾城亦可怜。"]},{"t":"初夏","f":"七言律诗","c":["郁郁红楼过却春，传来消息昨方真。","月宫尚懒仙梯下，天女还须病榻亲。","拒药自含深意思，画兰偏露瘦精神。","卷帘早见樱桃熟，莫为飞花又损身。"]},{"t":"病中苦忆 其一","f":"七言律诗","c":["金堂侵晓寂无人，帘底偷窥沈约身。","消渴已闻中酒日，冲寒犹犯落花晨。","就嫌浓睡宜过午，便事清游亦耐辛。","别有愿郎珍重处，却无一语自沾巾。"]},{"t":"病中苦忆 其二","f":"七言律诗","c":["屏东阁后遇临邛，细叩文园病里悰。","悬弩急须寻乐广，生刍且莫诣林宗。","窗疏着眼人私听，竹密惊心婢蹑踪。","翻折花枝欢笑去，已防愁思上眉峰。"]},{"t":"病中苦忆 其三","f":"七言律诗","c":["花笺封题小印严，玫瑰香酷蔗霜甜。","禁方虽载中心补，饱食终愁内热添。","小别光阴红雨尽，相思滋味绿饧粘。","为郎手解烦襟渴，别制新茶碧玉尖。"]},{"t":"病中苦忆 其四","f":"七言律诗","c":["曾觅幽屏晤一巡，烛花如豆雨如尘。","镂金香枕虚长夜，屑玉清谭是慧人。","误触宝縆犹窸窣，任铺湘簟太因循。","思量好景都成梦，只恐当时已不真。"]},{"t":"无题","f":"七言律诗","c":["双铜环响噪栖鸦，特揭金堂浅碧纱。","潇洒自如胸有竹，聪明相照眼无花。","香含幽极方为祖，艳透颦中是若耶。","璧月在天光在地，认来虽远不曾差。"]},{"t":"秋夕","f":"七言律诗","c":["碧天隐隐紫云歌，金粟香霏染袖罗。","此地更无尘世想，满身祇觉露华多。","呼来小字同明月，卷起轻帘即绛河。","应笑丽华璚树底，教人强唤作嫦娥。"]},{"t":"真真 其一","f":"七言律诗","c":["眼福输他老画师，碧桃花下对明姿。","竟容平视如公干，悔不前身是恺之。","泼茗偏邀当面笑，含毫还要点睛迟。","十年枉号平原客，才有楼头一见时。"]},{"t":"真真 其二","f":"七言律诗","c":["一泓秋水影玲珑，捧出生绡綵雾笼。","相识似曾鸾镜里，分明差胜蝶魂中。","温柔恰许传神得，供养真应绣佛同。","毕竟是烟还是玉，却愁神物化遥空。"]},{"t":"真真 其三","f":"七言律诗","c":["蔷薇露浣晚妆成，别倚瑶台弄玉笙。","綵凤自来刚翼比，银蟾可到是身轻。","人担艳冶原须福，天赋聪明必有情。","不画幽兰定梅萼，更无他物着卿卿。"]},{"t":"懊侬 其一","f":"七言律诗","c":["花下明妆嘱写真，转于调笑致娇嗔。","济尼失口称闺秀，伯玉无心诵洛神。","似畏窗光旋頫首，乍拈镜影欲回身。","画师解道愁尤好，却倚蛾眉更一颦。"]},{"t":"懊侬 其二","f":"七言律诗","c":["谁将消息报画帘，偷写崔徽入素缣。","未是描摹嫌仲朗，秪因唐突怪无盐。","鸩媒已恨胡香泄，鹤钥从添屈戍严。","可记镜中欢笑语，要图双影学鹣鹣。"]},{"t":"懊侬 其三","f":"七言律诗","c":["冷眼斜睼尔许时，临行却又教迟迟。","呼鬟别进先春茗，掠紒重删过午枝。","薄怒始知深似笑，娇憨尤爱近于痴。","比肩半晌嫌都释，那用烧灯密咒辞。"]},{"t":"感旧","f":"七言律诗","c":["青梅一树暗疏棂，桂户铜铺画亦扃。","映日帘波摇细细，隔花香雾起冥冥。","前尘恍惚曾游月，昔梦依稀是谪星。","竹密枝繁迷路久，不关容易动金铃。"]},{"t":"春社","f":"七言律诗","c":["六街箫鼓任阗门，寂静琼楼睡思昏。","蹑迹忽来飞鸟影，幽期不负刻花痕。","羞无可掩全呈媚，香莫能名但觉温。","回忆向时惊颤味，已销魂尚未销魂。"]},{"t":"小楼","f":"七言律诗","c":["唐梯徐点屧声娇，立定惊鸿脸晕潮。","罗带乍松先色战，玉钗将堕最魂销。","关心恐被雏鬟觅，侧耳疑闻彩伴邀。","欲去未能留不可，且申密约待明朝。"]},{"t":"背影","f":"七言律诗","c":["削玉双肩秀绝群，遥从背影识文君。","衣裁藕色偏如雪，窗透兰香可待薰。","别后金堂刚半月，望中珠箔抵重云。","明知小立青苔久，唤彻鹦哥似不闻。"]},{"t":"幽槛","f":"七言律诗","c":["贪依幽槛立花阴，忘却冥冥细雨侵。","替整莲巾防折角，代障葵扇示同心。","怜卿秀色调饥慰，知我清姿病渴深。","戏语他年身后事，带瞋和笑未沾襟。"]},{"t":"晓妆","f":"七言律诗","c":["水晶帘射日曈昽，茜子裈裆八尺红。","羞对熟人呈晕月，笑持雏婢作屏风。","梳头惯学轻云立，靧面才将艳雪融。","偷描珠兰笼袖底，觑人方便掷奁中。"]},{"t":"晚妆","f":"七言律诗","c":["轻雷隐隐过池塘，珠押风开换晚妆。","碧玉奁梳清彻水，紫荆钗股暗通香。","烛边元发光堪鉴，浴后冰肌近自凉。","日对远山眉一角，未妨四壁自清狂。"]},{"t":"依夕 其一","f":"七言律诗","c":["月波裁剪作轻绡，著向风前水漾摇。","谢女襟情原雪澹，萧郎踪迹比天遥。","曾劳花胜同同结，枉盼瓜期昔昔邀。","输与鬓师偏逼近，豪犀亲见拨云翘。"]},{"t":"依夕 其二","f":"七言律诗","c":["一钩黄月最多情，斜影惊眉喜气生。","出浴衣香如昨日，断肠书约是初更。","偷窥竹径原微掩，惊避花丛却缓行。","踪迹自疏心自密，玉环须认隔帘声。"]},{"t":"口午晤","f":"七言律诗","c":["越桃花发小阑偏，香气撩人易破眠。","八尺琅玕凉欲雨，一层纰缦薄于烟。","鬟因睡起偏尤好，妆为慵来洗更妍。","才是折花苔径湿，连环纤印玉阶前。"]},{"t":"暮雨","f":"七言律诗","c":["听尽莲花漏转迟，黄昏偏又雨丝丝。","寒轻那禁重帘袭，梦远惟应薄被知。","瘦影定怜秋水隔，良缘空与碧云期。","红楼巳恨如天上，更有天难望见时。"]},{"t":"二妙词","f":"七言律诗","c":["杨柳阴通白石渠，绕渠多种水芙渠。","小姑家具红牙管，大妇妆奁碧玉梳。","爱仿簪花倾逸少，工题欢果号相如。","何当辟作双清子，掌我诗筒替我书。"]},{"t":"曲阑","f":"七言律诗","c":["隔墙花气隔墙风，知是钗丛是露丛。","妆罢定应重顾盼，语来光认独朦胧。","能教妒女甘居殿，羞对痴郎验守宫。","行过曲阑还伫立，水晶帘罥玉莲蓬。"]},{"t":"桃源","f":"七言律诗","c":["桃源流水带花香，飞瀑通身度石梁。","仙掌忽开青菡萏，神楼刚曝翠衣裳。","难将隐影传张硕，谁许同来挈阮郎。","翻趁出山泉水活，寄流清泪教君尝。"]},{"t":"天生","f":"七言律诗","c":["天不轻生是美人，每逢佳节始生辰。","香偏耐冷霜为骨，影只宜秋月是神。","肌雪愈添眉上翠，眼波微透意中春。","玉杯浇取双红豆，不化湘梅定楚筠。"]},{"t":"清斋","f":"七言律诗","c":["绣阁清斋荐露盘，近来小恙爱吴酸。","甜香共爇名宜爱，佳果亲投是合欢。","扇底簪花题拂暑，尊前箸玉劝加餐。","要知怜惜恩深处，只与王郎一例看。"]},{"t":"暑窗即事 其一","f":"七言律诗","c":["镜鹊晨开象簟清，乍梳妆后又钗横。","风姿偏是慵时好，仪节多缘熟极轻。","障扇自通眉款曲，簪花也露性聪明。","尽留真色教人看，一洗檀郎错爱名。"]},{"t":"暑窗即事 其二","f":"七言律诗","c":["风日阑干晓露稀，嫩炎轻袭碧罗衣。","蝽蛛偏爱当窗挂，蝴蝶犹贪绕扇飞。","含怨笑言终郁郁，钟情形迹莫依依。","无端慧舌酬清辨，又道关心替解围。"]},{"t":"无题和竹桥丈韵二十四章 其一","f":"七言律诗","c":["洛神一赋诵回环，宛在盈盈一水间。","色为兼才偏觉秀，情何累德未妨閒。","鱼笺细摺同心胜，鲛帕牢收别泪斑。","每到黄昏更凄绝，慢凭月色洗愁颜。"]},{"t":"无题和竹桥丈韵二十四章 其二","f":"七言律诗","c":["羊脂白玉碾连环，只系裙腰一寸间。","欲报手书嫌语琐，为悬心事怕身閒。","鲜妍未透蛇医迹，妩媚翻留獭髓斑。","薄怒深愁看更好，倾城原不在欢颜。"]},{"t":"无题和竹桥丈韵二十四章 其三","f":"七言律诗","c":["象牙梳似月弯环，镜槛钗奁曲尺间。","幽梦思量心暗喜，低鬟商略性多閒。","裙花那禁郎持绉，袖碧宁嗔姊唾斑。","多和燕脂轻傅粉，怕人看出病中颜。"]},{"t":"无题和竹桥丈韵二十四章 其四","f":"七言律诗","c":["天半微闻响佩环，红墙银汉在人间。","徒劳翠鸟殷勤探，难伺鸟龙一隙閒。","卓女调琴囊瑟瑟，卫娘拈管竹斑斑。","可怜枉负如花貌，输与桃花有笑颜。"]},{"t":"无题和竹桥丈韵二十四章 其五","f":"七言律诗","c":["线阴宛转小廊环，日暮佳人倚竹间。","细步最怜幽草弱，渺怀偏寄去云閒。","花如倾国何关笑，玉果连城不讳斑。","一种乾坤清气在，秋颜须识胜春颜。"]},{"t":"无题和竹桥丈韵二十四章 其六","f":"七言律诗","c":["晶帘不隔洞如环，浅淡眉峰隐约间。","自读郎诗书尽废，翻邀姊绣线都閒。","镜奁圆浸蟾蜍影，砚匣香生翡翠斑。","周防描摹应未到，才人风格美人颜。"]},{"t":"无题和竹桥丈韵二十四章 其七","f":"七言律诗","c":["绛阙宸妃字阿环，云軿小谪凤城间。","神光离合随方变，仙梦凄迷竟夕閒。","凝雪自穿衫缕瑩，纤尘不上袜罗斑。","玉楼咫尺如天远，何况楼中润玉颜。"]},{"t":"无题和竹桥丈韵二十四章 其八","f":"七言律诗","c":["丽质休猜燕与环，秾纤修短适中间。","小鬟戏学晨梳懒，中妇偷窥午睡閒。","画角暗搔纤指晕，墨痕微舐绛唇斑。","不知忆着何年事，半晌妆台独解颜。"]},{"t":"无题和竹桥丈韵二十四章 其九","f":"七言律诗","c":["一年小梦事循环，又值秋分白露间。","十洞三清皆阻碍，六张五角每空閒。","诉将幽怨鹍弦语，替得悲啼凤蜡斑。","镇日画图中看杀，何如暂许对芳颜。"]},{"t":"无题和竹桥丈韵二十四章 其十","f":"七言律诗","c":["妒眼如城绕一环，屧声遥认桂堂间。","燕来暂撤中门禁，花落潜行外院閒。","身隔画丝邀絮语，手提金缕怕苔斑。","教人陡识平时意，暖在心头冷在颜。"]},{"t":"无题和竹桥丈韵二十四章 其十一","f":"七言律诗","c":["诃梨新剪片云环，人在炉熏镜里间。","困倦未容双鬓亸，聪明肯放一心閒。","欢情渐引眸无缝，羞晕微烘颊似斑。","七分桃花三分雪，是郎诗句是侬颜。"]},{"t":"无题和竹桥丈韵二十四章 其十二","f":"七言律诗","c":["手解婴年旧弄环，带郎第五指中间。","幽期误约心非活，哑谜旁猜语总閒。","乍冷慢缄纨扇素，再来须验绣衾斑。","此情要比天长久，那在多贫识面颜。"]},{"t":"无题和竹桥丈韵二十四章 其十三","f":"七言律诗","c":["环痕约指指如环，预种芳缘隔世间。","论阀未甘鱼媵贱，处囮何用雉媒閒。","花开艳极偏无子，笋出尖多易有斑。","只合化身明月镜，笑颦都得照卿颜。"]},{"t":"无题和竹桥丈韵二十四章 其十四","f":"七言律诗","c":["柔肠蚤暮鹿卢环，只在郎行左右间。","誓密记曾邀月證，情多恐又爱花閒。","占晴可奈时时变，踏湿还防处处斑。","作计恼伊佯怒去，明朝相见看何颜。"]},{"t":"无题和竹桥丈韵二十四章 其十五","f":"七言律诗","c":["海榴花下脱金环，小病刚刚一月间。","食味本来当暑断，睡眸还得彻宵閒。","频惊石鼎松涛沸，细展罗衾药沈斑。","输与衙推偏得见，捧心时节最真颜。"]},{"t":"无题和竹桥丈韵二十四章 其十六","f":"七言律诗","c":["红阑干角绿蕉环，竹色茶香阁半间。","帘押迎风抛绣乱，枕函送日赖书閒。","长来指爪逾脂印，浓得眉痕透黛斑。","人自惯看侬转讶，镜中消瘦甚人颜。"]},{"t":"无题和竹桥丈韵二十四章 其十七","f":"七言律诗","c":["衔耳明珰小凤环，戏擒胡蝶出花间。","绀珠艳事星星记，碧玉芳时日日閒。","晓雾迷成三里障，秋云巧作五铢斑。","厌人絮问将雏近，赢得羞颜似醉颜。"]},{"t":"无题和竹桥丈韵二十四章 其十八","f":"七言律诗","c":["一曲明河列宿环，佩声遥在碧云间。","生逢独立人难得，除却相思事总閒。","仙字早凭心勒印，神光翻逼眼成斑。","直须亵念都消尽，才许亲承水月颜。"]},{"t":"无题和竹桥丈韵二十四章 其十九","f":"七言律诗","c":["欲把名花当屋环，只宜兰畔与梅间。","心思手口三般巧，坐起眠行一味閒。","艳雪题成宁有对，香云剪与并无斑。","常娥尚自多情甚，偷下雕梁为照颜。"]},{"t":"无题和竹桥丈韵二十四章 其二十","f":"七言律诗","c":["蛇报灵珠鹊报环，深情难报隐微间。","香投异域嫌轻亵，丝绣平原只等閒。","素约敢消乌鲗誓，丹诚空渍杜鹃斑。","酬恩自保千金体，捣药拚为悦己颜。"]},{"t":"无题和竹桥丈韵二十四章 其二十一","f":"七言律诗","c":["玉扉清响小铜环，履迹衣声眼耳间。","预碾茶枪消吻渴，细听莲箭耐身閒。","草虫戏捉还谋对，花虱亲除更拭斑。","顷刻欢愁千百变，作秋天气似卿颜。"]},{"t":"无题和竹桥丈韵二十四章 其二十二","f":"七言律诗","c":["左手除来右手环，珠胎盈满月轮间。","柳经眠后蛮腰重，果到垂时蝶影閒。","喜搯茶膏津化液，怕拈花样汗生斑。","刘桢莫恨难平视，伫看娇儿似母颜。"]},{"t":"无题和竹桥丈韵二十四章 其二十三","f":"七言律诗","c":["栀子银墙面面环，依稀仿佛玉楼间。","通融恰许行相近，分别仍教坐各閒。","薤叶双钩新墨拓，菱花七出古铜斑。","梦中历历分明记，难记偏生绝世颜。"]},{"t":"无题和竹桥丈韵二十四章 其二十四","f":"七言律诗","c":["洞房帘箔水晶环，偷看香笼绣箧间。","书卷纵横风揭转，簟纹斜整日抛閒。","乾藏凤子芙蓉粉，驯养狸奴玳瑁斑。","真个到来翻不见，梦中情事意中颜。"]},{"t":"自题二十四诗后每句藏二十四意","f":"七言律诗","c":["吹箫桥畔月如环，亚字阑干对照间。","写遍乌丝三页满，弹来雁瑟一条閒。","清波双现金钗影，和气全飞玉琯斑。","慢说荷花共生日，十年年减丽娟颜。"]},{"t":"艳体一章每句戏藏十六意","f":"七言律诗","c":["十二阑干花四环，美人二八倚中间。","蛾眉那厌重新画，象戏刚抛一半閒。","两度界笺书锦字，更番排卦炙香斑。","嬉游二九还初七，生过娇儿尚玉颜。"]},{"t":"闺人养疴辞 其一","f":"七言绝句","c":["工愁善病女相如，暂徙瑶斋检道书。","一缕药烟清似水，云屏隔断广寒居。"]},{"t":"闺人养疴辞 其二","f":"七言绝句","c":["小庭花木费平章，终日琴鸣古研旁。","却下水晶帘一扇，仙肌冰雪自生凉。"]},{"t":"闺人养疴辞 其三","f":"七言绝句","c":["南窗置榻北窗宽，一曲书廊镜槛安。","那有红尘飞得到，绿芭蕉映雪阑干。"]},{"t":"闺人养疴辞 其四","f":"七言绝句","c":["双扉閒锁一阶苔，屈膝铜铺昼不开。","只有常娥推不去，夜深远近小窗来。"]},{"t":"闺人养疴辞 其五","f":"七言绝句","c":["刺铜清影拂帘长，鼎沸松风药透香。","亲把银匙调一过，同心甘苦愿分尝。"]},{"t":"闺人养疴辞 其六","f":"七言绝句","c":["暂废椒花格律新，绕床书卷尚逡巡。","卧中听得秦嘉咏，一字推敲又损神。"]},{"t":"闺人养疴辞 其七","f":"七言绝句","c":["竹床冰簟镇相亲，吟瘦身看病瘦身。","听说莲塘遭雨打，今年花更瘦于人。"]},{"t":"闺人养疴辞 其八","f":"七言绝句","c":["疏云先作一分秋，添得窗棂绿更幽。","几点雨弹凉叶上，红心枯草又新抽。"]},{"t":"闺人养疴辞 其九","f":"七言绝句","c":["隔年情事记分明，雪椀冰盘夜话清。","昨日到门亲听得，小鬟偷学诵诗声。"]},{"t":"闺人养疴辞 其十","f":"七言绝句","c":["妆楼昼静屦聋无，画稿丛残墨未枯。","等月再生人病起，拜双星夜玉梯扶。"]},{"t":"小阁","f":"七言律诗","c":["檐际凉云冰漾浮，果然小阁胜琼楼。","竹阴满榻清如扫，花影移帘渐上钩。","守礼敢烦郎熨体，倦妆还唤婢梳头。","病馀偶揭閒书卷，本为消愁却惹愁。"]},{"t":"七夕再叠环字韵","f":"七言律诗","c":["水玉兰钗火齐环，隐然黄色透眉间。","十分月有三分过，九孔针无一孔閒。","心巧素娴牛女慧，指尖红沁凤仙斑。","不消始影重祈祷，越病深时越丽颜。"]},{"t":"新凉","f":"七言律诗","c":["小窗幽梦咋宵凉，宝簟重移绣榻量。","楼阁自开秋世界，云霄原近月家乡。","竹枝浪认钗钿影，花气犹含语笑香。","六曲屏山移不去，是曾亲照玉容光。"]},{"t":"玉恙新起","f":"七言律诗","c":["病馀眠食强支撑，秋暑宜逃味要清。","侍女且教铺象簟，厨娘还忌进鱼羹。","极关情语唯珍重，不避嫌时更至诚。","如此相思天亦许，两边心似玉壶明。"]},{"t":"晨晤","f":"七言律诗","c":["木樨香里海棠阴，四面秋光照此心。","情在不言方是契，眉如为语转非深。","玲珑日影穿丹縠，叆叇炉烟袅翠襟。","为我强支晨倦坐，未须一刻已千金。"]},{"t":"长廊","f":"七言律诗","c":["如云罗绮万花前，众里纤长独逞妍。","住近浮图光似佛，幼餐沉水体俱仙。","梳匀信手人争学，调笑无心语可传。","半晌眼波娇不溜，待人临别却嫣然。"]},{"t":"艳缘","f":"七言律诗","c":["郁金堂古麝兰熏，掩过银屏露翠裙。","仓卒似惊生客语，缠绵犹与小鬟云。","花迎斜日翻舒蕊，月过中天却漏云。","偏是徐行容细认，艳缘真悔阮郎分。"]},{"t":"游仙辞 其一","f":"七言律诗","c":["洞门翠荚暖生烟，微叩瑶扃谒上仙。","任诞偏逢方朔过，胜常惟许密香传。","云浆末识何花气，星汉空思在月边。","暂缓碧桃三日放，可知人世似经年。"]},{"t":"游仙辞 其二","f":"七言律诗","c":["神楼缈缈接瑶京，八面红窗对八瀛。","花顶佛光留髻影，画中仙指落琴声。","天空不许云留迹，潭净偏容月印明。","此是消魂真境界，最高情又最深情。"]},{"t":"重帘","f":"七言律诗","c":["洞房深昼却寒垂，朱舄窗明未许窥。","着眼预防人见我，关心早识影为谁。","绿翘进茗纤纤手，绛树添香瑟瑟帷。","情到神仙情更好，紫阑亲自护葳蕤。"]},{"t":"银湾","f":"七言律诗","c":["翻喜疏棂扇扇关，黄姑亲得渡银湾。","沁人肌息如沉水，煖我心肠似博山。","极慰离情惟握手，偶思前事转低颜。","欲将栀子连诗赠，恩意还须托令娴。"]},{"t":"深秋","f":"七言律诗","c":["玉恙经秋辗转深，上池清水渍罗衾。","莫缘知己真披胆，可是吟诗欲呕心。","鱼目那堪通夜醒，犀株枉自辟寒簪。","黄花慢想倾城顾，病过荷花直到今。"]},{"t":"纪旧梦","f":"七言律诗","c":["纤袿一抹限红墙，暗里温柔别有乡。","浴室喜无通德侍，壁衣偷把彦回藏。","莲房久禁閒蝴蝶，桐树新栖小凤凰。","今日分明转惆怅，双峰如雪射窗光。"]},{"t":"露立","f":"七言律诗","c":["合既无缘竟别离，可堪相见又时时。","风来水面非关约，月上梢头未可期。","厚施恩情消薄福，浅尝滋味耐深思。","明知取冷难身熨，痴立空庭任露滋。"]},{"t":"今生","f":"七言律诗","c":["旧事思量历历明，拂檐蝙蝠悄无声。","忽惊月自怀中堕，犹喜云从梦里行。","离恨有天终古漏，爱迷填海几时盈。","多情随处看花好，可奈今生是寡情。"]},{"t":"婉儿","f":"七言律诗","c":["楼上昭容是我师，天教玉尺为量诗。","直空四海才人望，独许千秋幼妇词。","青眼或来温峤目，素心难定叔牙知。","感恩若仿平原例，先买红罗绣婉儿。"]},{"t":"卫娘","f":"七言律诗","c":["绿梅花下有人居，正恐梅花秀不如。","每恨王郎痴似叔，独怜邹忌美于徐。","盘周四角辞难毕，漏尽三商梦竟虚。","欲表同心心迹处，右军能乱卫娘书。"]},{"t":"炉灰复然","f":"七言律诗","c":["帘外西风扫聚苔，已寒重暖玉炉灰。","草书结体联无断，花胜同心解不开。","才欲见时先震荡，是曾立处定徘徊。","一生自抱千秋信，莫管佳人果否来。"]},{"t":"同心曲","f":"七言律诗","c":["一寸窗光一寸金，暂邀欢坐绿纱深。","戏搀瓯茗脂香度，偷掣簪花粉本临。","纵使旁挠无计遣，但留前约有时寻。","郎今莫问侬心事，侬与郎心是一心。"]},{"t":"步虚辞","f":"七言律诗","c":["三生辛苦捣元霜，口嚼梅花齿尽香。","鹤背几时邀子晋，蝶魂无路上高唐。","卷中还恐非仙影，裙底空疑是佛光。","采采玉芝何处好，秪留云气满虚筐。"]},{"t":"惊疑","f":"七言律诗","c":["倾国何曾定有方，情波照玉玉生光。","聪明眉黛先天秀，宛转香丝委地长。","巧语猝投工应变，笑容先见道胜常。","背人偷握春葱好，一种惊疑味乍尝。"]},{"t":"密绪 其一","f":"七言律诗","c":["兜罗绵手罢花拈，亲为檀郎熨指尖。","背地暂将凫藻让，耳边低劝翠裘添。","转参庄语教人听，徐敛明眸觉婢觇。","离席不妨端坐好，莫因匆遽召猜嫌。"]},{"t":"密绪 其二","f":"七言律诗","c":["才欲回身却敛身，郁金堂上暂逡巡。","同心那在相逢数，半面何尝不看真。","尽可端详馀背影，断难描画是丰神。","临行尚有消魂处，未敢题诗浪示人。"]},{"t":"绣屧","f":"七言律诗","c":["绣屧才围缝合欢，无心偶置画阑干。","量来新月还形窄，裹尽春云定觉宽。","可许玉尖亲赋着，未妨香屑代装安。","红帮残绫拖针在，秪嘱檀奴仔细看。"]},{"t":"几度","f":"七言律诗","c":["几度寻花花不开，今朝花影下瑶台。","天教生日同霜菊，人喜临风似玉梅。","隔院图郎闻笑语，当窗借婢共徘徊。","博山炉火情常暖，值得冲寒犯雪来。"]},{"t":"水晶帘下即事","f":"七言律诗","c":["逋发初撩待画眉，镜台偷傍立多时。","熏香乍喜眠娇女，倾水刚逢遣侍儿。","皓腕先攘容捉搦，朱唇欲啮费矜持。","幽情未了馀欢在，留作今宵翠被思。"]},{"t":"朝来","f":"七言律诗","c":["朝来座客向余誇，亲睹红妆展碧纱。","秋水神凝如有待，早梅光映两无瑕。","关心偏在屏风近，错眼真成薄雾遮。","辜负临邛深爱意，翻教人得见如花。"]},{"t":"献果","f":"七言律诗","c":["檀郎何处得尝新，翻作妆台掷果人。","入手已知仙味美，分甘先惧妹心嗔。","笑君怀核宁无意，献佛将花早有因。","一幅定情罗帕在，轻红虽退认犹真。"]},{"t":"问讯","f":"七言律诗","c":["斜门风逆送氤氲，帘卷金堂袅水纹。","几度空来应怨我，此时强坐半缘君。","早抛眼媚红窗里，那惜脂香碧盌分。","娇语平安亲问讯，芳姿传出已先闻。"]},{"t":"熏炉","f":"七言律诗","c":["新寒跨火辟邪炉，藕覆双凫色色殊。","兰篆静看烟似水，梅花亲点笔为图。","比肩可许充佳婿，拥背何妨借小姑。","推就暖香熏一过，留仙裙底按纤趺。"]},{"t":"临去","f":"七言律诗","c":["来何缓缓去匆匆，朱角门西小院东。","一剪晴波劳远送，两番平视竟通融。","神情意致都闲雅，坐立行时不苟同。","那似小家羞涩态，见人先自下帘栊。"]},{"t":"簪梅","f":"七言律诗","c":["兰房曲折透幽香，绣褓亲擎小凤凰。","笑靥乍看儿绝似，廋词相谑婢无妨。","妆交二九梳头懒，裘袭双重触手忙。","袖笼玉梅三百朵，为卿低插鬓云傍。"]},{"t":"评花","f":"七言律诗","c":["桃花不及李花妍，一笑欣逢缟袂仙。","同是无言芳独擅，从来绝色秀为先。","中天皓月人争看，委地春云我最怜。","拈出退之诗句好，渔郎应悔武陵船。"]},{"t":"下楼","f":"七言律诗","c":["楼上斜阳楼下行，鹦哥消息透前楹。","云鬟偏觉家常好，花气原从坐处生。","瞥见玉光惊又喜，乍回钗影避还迎。","双星但隔秋河照，眼自模糊意自明。"]},{"t":"乳香","f":"七言律诗","c":["幽香一缕透罗襦，亲乳桐花小凤雏。","密室喜无樊嫟侍，潜身悔与阮郎俱。","良期每被惊心误，坚坐还防妒口诬。","却忆独来时节好，同群又碍阮咸姑。"]},{"t":"云軿","f":"七言律诗","c":["宛转香车绕绿溪，一泓秋水彻玻璃。","良缘对面谁能阻，好事无心比约齐。","似惜萧郎门外立，几将小宋路傍提。","个人巧笑寻常见，不似今番易着迷。"]},{"t":"窄径","f":"七言律诗","c":["邂逅重门窄径偏，翔风依鬓总嫣然。","花从转侧看尤媚，云为夷犹态更妍。","暖语兜来心坎里，柔魂钩去眼梢边。","何因却把双鬟见，缓住工鞋一细怜。"]},{"t":"芳筵","f":"七言律诗","c":["隔座芳兰一点心，潜凭传婢语知音。","杯行喜听斟时浅，烛换愁看坐夜深。","力为加餐须自努，饮当微醉莫教沉。","拥炉默计君归候，忍比君先到绣衾。"]},{"t":"密意","f":"七言绝句","c":["柳样春浓絮样颠，轻云无迹过青天。","人前第一须留意，莫把双眸注妾边。"]},{"t":"金堂","f":"七言律诗","c":["初日瞳瞳上画梁，佩声钗影郁金堂。","蘋蘩久诵葩经熟，姜橘亲调豆实香。","方朔暗窥思割肉，裴航消渴愿分浆。","此生许作花间活，甘奉王褒约数行。"]},{"t":"松实","f":"七言律诗","c":["新罗松实剖芳鲜，亲把朝饥疗偓佺。","尚带灵芸香唾湿，定劳钩弋玉纤妍。","小姑却讶晨馐早，雏婢空猜夙嗜偏。","偷递袖中银合子，佯佯走过镜台前。"]},{"t":"咏雪","f":"七言律诗","c":["云母围屏俨画图，一奁秋水照凝酥。","未堪仙子藏金屋，如此楼台便玉壶。","鬓影泊风尤绰约，鞋尖印雪巳模糊。","笑他痴叔向清赏，解赏因风柳絮无。"]},{"t":"寒妆","f":"七言律诗","c":["今朝且不系香缨，覆额貂冠衬发明。","赵姊丰容灯下好，谢娘神味雪中清。","泥人更此香鬟媚，隔座终闻画屧轻。","笑把手抄诗一卷，问郎堪否号书生。"]},{"t":"春憾","f":"七言绝句","c":["西风吹月满高楼，楼上珠帘尽下钩。","兰病未苏梅欲褪，二分春色十分愁。"]},{"t":"舟中书感时阻风暨阳","f":"七言律诗","c":["无数新愁并旧愁，暗风吹雨入孤舟。","寒梅未肯藏金屋，清梦先疑到玉楼。","花落忽闻天女病，珠寒偏值洛妃游。","封姨苦把归期阻，想杀多情是石尤。"]},{"t":"美人家饮花露饮毕而馀香在盌 其一","f":"七言绝句","c":["琼浆滴滴入诗喉，香气犹沾碧玉瓯。","恰似鬓边花落下，芬芳常在美人头。"]},{"t":"美人家饮花露饮毕而馀香在盌 其二","f":"七言绝句","c":["一朵仙霞捧九霄，散花天女手亲调。","玉瓯本是无情物，入骨浓香不肯消。"]},{"t":"有两美人见小影而相爱者","f":"七言律诗","c":["松欢柏悦总前因，心自相亲迹未亲。","我见犹怜何况汝，卿如欲下定疑神。","湘云湘水原同梦，秋月秋河是比邻。","认得邢家真国色，从来只有尹夫人。"]},{"t":"琼花阁春宴 其一","f":"七言律诗","c":["琼台缥缈接空冥，面面湘波作翠屏。","诗梦一天如雪艳，酒花二月有兰馨。","碧云界断忘人世，红豆拈来尽性灵。","风卷玉箫声缓缓，群真都在上头听。"]},{"t":"琼花阁春宴 其二","f":"七言律诗","c":["冰盘行炙月轮擎，多是芳心结撰成。","花气一楼难辨种，食单三日预商名。","新歌乍学狂何惜，罚盏虽冤醉亦轻。","赢得归家争问讯，酒香还似玉梅清。"]},{"t":"携眷属游山","f":"七言律诗","c":["鱼朵轻云覆綵軿，佩环声到半空停。","幽香自杂松花落，细语难兼瀑布听。","樵客尽疑仙眷属，侍儿都带佛精灵。","艳情證取西来意，螺髻蛾眉一样青。"]},{"t":"玉楼供花辞和楼中人韵 其一","f":"七言律诗","c":["摘取晨葩晓梦中，玉楼分插小窗红。","人间风雨应无恨，天半园林别有丛。","频嘱侍儿新水换，不嫌供佛净瓶同。","暂时收拾熏垆起，自有香云护梵宫。"]},{"t":"玉楼供花辞和楼中人韵 其二","f":"七言律诗","c":["名花四座镜当中，映出深红间浅红。","着水宛如新沐后，披香疑入古书丛。","瓶缘放胆春能管，灯替传神夜不同。","面面湘帘围梦住，枉他粉蝶效秦宫。"]},{"t":"玉楼清福","f":"七言律诗","c":["不通融处似通融，飞絮游丝扑绣栊。","三月诗情多艳冶，一楼春梦太玲珑。","略嫌琴脆贪微雨，自惜衣香爱逆风。","十二胆瓶花四面，神仙清福坐当中。"]},{"t":"怀个人归宁 其一","f":"七言律诗","c":["月白江空鹤一声，美人香梦可曾惊。","瑶台自划天为界，玉笛实飞雪满城。","春有去时谁定例，潮闻来处敢相迎。","藐姑只合罗浮宿，金屋如何好贮卿。"]},{"t":"怀个人归宁 其二","f":"七言律诗","c":["望仙楼上望朝霞，隔断瑶池阿母家。","蛛网有丝萦屋角，鹊巢无喜报檐牙。","难将芳讯通行李，未必归期准及瓜。","曾是往时携手处，绿窗开煞碧桃花。"]},{"t":"美人病目","f":"七言律诗","c":["梦觉空闻百啭莺，一帘香雾未分明。","诗成只泥同心写，琴罢偏猜落指生。","慢托微波通款曲，任抛残局自纵横。","万花应是羞相见，暂借轻云障太清。"]},{"t":"评画","f":"七言律诗","c":["绝色休从画裹看，须知落笔绘天难。","描摹西子凭凡笔，颠倒明妃在素纨。","身到岱峰诸岳小，花开若木众星阑。","妍媸只把丹青定，何限人间老试官。"]},{"t":"题兰绝句 其一","f":"七言绝句","c":["只合离骚一卷书，水仙相伴住清虚。","诗人眼底花如海，除却寒梅尽不如。"]},{"t":"题兰绝句 其二","f":"七言绝句","c":["楚云旖旎水缠绵，生就珠胎玉骨仙。","昨夜潇湘明月下，意中人恰似卿妍。"]},{"t":"并船纪事","f":"七言律诗","c":["花光相映并头船，竟有珠联壁合天。","一水香交通笑语，两家帘卷见神仙。","清波照影尤增艳，好事无心转得圆。","偏是情深偏分浅，何时刑尹却骈肩。"]},{"t":"春芜婉仙夫人侍儿也风致婉妙年甫及笄其父将为择耦夫人送之以诗余为继声","f":"七言律诗","c":["来是嫣然去黯然，盈盈未是嫁时年。","鸟犹带绫方呼熟，草亦如花要趁鲜。","曾学大家羞更好，便为贫妇德须贤。","遥知此去芦帘下，魂绕璚楼玉镜前。"]},{"t":"移巢","f":"七言律诗","c":["翡翠移巢晓出城，多情先往等云英。","明知此客来缘我，无计教伊得见卿。","纡步欲从花径过，回身图向画廊行。","芳心苦被王郎觉，甘受无端恚怒声。"]},{"t":"水嬉同泛","f":"七言律诗","c":["卷起东风雀舫帘，戏临春水照鹣鹣。","比肩暗学双星渡，放胆明欺万目瞻。","浓笑索花频恃爱，清谈闻曲转生嫌。","延挨别有消魂计，只等船梢上玉蟾。"]},{"t":"心招","f":"七言律诗","c":["兰堂寂静袅游丝，举手相招目送辞。","事到极欢情转怯，态无纤匿礼犹持。","竹声疑雨惊秋早，花影如云出梦迟。","踪迹自忙心自细，教人重整鬓边枝。"]},{"t":"小病","f":"七言律诗","c":["小病才回午汗潮，为谁强起倚疏寮。","作秋庭院花含怯，过雨帘栊日放娇。","密约纵虚心有迹，深情欲吐语无聊。","坐来莫恨如天远，转眼银河又昨朝。"]},{"t":"自持 其一","f":"七言律诗","c":["未须惆怅但闻香，修到香中愿已偿。","欲报深思难著迹，每窥微笑越周防。","花前苦劝耽诗瘦，灯后坚辞被酒狂。","除却衾窝同梦外，尽抛心力效鸳鸯。"]},{"t":"自持 其二","f":"七言律诗","c":["不矜风格转超群，委地湘波拂拂裙。","逼眼光华花上月，荡心仪态水中云。","任教离间情终合，尽意绸缪界自分。","深感琴心通委曲，自怜无福作文君。"]},{"t":"自持 其三","f":"七言律诗","c":["偶将谰语抵清狂，底事前盟苦索偿。","极婉转时心自许，暂通融处眼犹防。","茶瓯密度樱桃味，衣扣牢缄豆蔻香。","倾吐兰胸岂无意，玉楼何日去梯桄。"]},{"t":"雨窗","f":"七言律诗","c":["绿梅花下坐卿卿，神与梅花一样清。","得意事须防失意，深情人肯浪多情。","心挑祇益羞颜热，眉语还遮妒眼明。","欲去尚留留未可，恰来丝雨洒帘声。"]},{"t":"横波","f":"七言绝句","c":["百巧千灵藕孔多，泥人全在两横波。","如愁如喜还如怒，媚态三番一刹那。"]},{"t":"双红豆辞 其一","f":"七言律诗","c":["称出双株红豆红，暗将心事卜东风。","意中人病朝朝减，梦里欢归夜夜同。","翡翠楼高天共远，鸳鸯湖判水难通。","春愁化作杨花点，半入清波半碧空。"]},{"t":"双红豆辞 其二","f":"七言律诗","c":["去年消息望今年，及到今年转忆前。","扶病尚因花强出，归宁差喜事迁延。","机缘半为忙中错，滋味都从过后鲜。","欢笑要期来日补，却愁追忆更茫然。"]},{"t":"双红豆辞 其三","f":"七言律诗","c":["知是蓝桥是鹊桥，一双解下佩琼瑶。","情同沧海无深浅，缘比浮云有近遥。","花纵可攀容易别，月虽频望手难招。","不如身化王馀片，分属江东大小乔。"]},{"t":"双红豆辞 其四","f":"七言律诗","c":["心中眼底与眉头，积得离愁又病愁。","小玉瘦来眠反侧，飞琼归去信沉浮。","缘悭莫要真成玦，痴绝难甘枉下钩。","每到幽窗閒把玩，团圞一对鍊金彄。"]},{"t":"双红豆辞 其五","f":"七言律诗","c":["叠笺书恨祇焚灰，剪纸酬神枉费财。","一半聪明知误用，两无消息肯传来。","慢凭问卜蓍归妹，悔不能医药作媒。","愿学维摩行脚状，替人担病觅人回。"]},{"t":"双红豆辞 其六","f":"七言律诗","c":["双珠托出水晶盘，欲定高低两字难。","论岁参差原姊妹，比花先后似梅兰。","泥中尔我应三分，林下神情祇一般。","对面看来形与影，切休分作尹邢看。"]},{"t":"双红豆辞 其七","f":"七言律诗","c":["喜蛛灵鹊满檐前，道是佳音却浪传。","炙罢艾香心愈捧，占残花信眼徒穿。","他乡未必全无恙，久卧何如各一天。","如此思量人易瘦，又愁相见定凄然。"]},{"t":"双红豆辞 其八","f":"七言律诗","c":["人竟归来病竟除，极寻常事却疑虚。","愁他慈母留偏强，怨到庸医术太疏。","欲剖素心潜和药，想呼黄耳妄传书。","从知一面难消受，休说鸳禽与鲽鱼。"]},{"t":"双红豆辞 其九","f":"七言律诗","c":["閒里寻思太认真，最痴情却最伤身。","挽车陌上谁迎汝，取冷庭中自有人。","弱体枉禁风五夜，柔肠偏转日双轮。","汉皋明月天台树，不是今生是夙因。"]},{"t":"双红豆辞 其十","f":"七言律诗","c":["紫袖昭容玉尺温，青绫步障粲花论。","手抄罗隐江东集，心订韦皋蜀道婚。","极恍惚中烟有影，最缠绵处梦无痕。","不妨说与青天晓，卿自怜才我感恩。"]},{"t":"七夕惆怅辞","f":"七言绝句","c":["天上相思有了时，一年一度一佳期。","人间只有相看分，也要迢迢远别离。"]},{"t":"晓语","f":"七言律诗","c":["画檐鹦鹉唤人来，一扇湘帘自荡开。","微露丰容教瞥见，熟闻声息故惊猜。","云含疏雨频延伫，水遇轻风又折回。","还恐未曾亲切看，玉楼天半重徘徊。"]},{"t":"借得","f":"七言律诗","c":["借得神仙七宝床，梦魂先到白云乡。","鄂君绣被真奇煖，荀令熏炉是异香。","花气袭人如二月，竹声含雨似三湘。","青天定有星辰影，暂宿银河便渺茫。"]},{"t":"情诗","f":"七言律诗","c":["一分消瘦一分娇，玉恙才闻起昨朝。","膏沐脩容还自强，羹汤亲手为谁调。","愿将郎作鸳鸯绣，曾把花同蛱蝶描。","情比博山炉更煖，那须炙盏始寒消。"]},{"t":"无题","f":"七言绝句","c":["就使楼头响佩环，娟娟秋影隔银湾。","如今影也无从见，学到双星夙分难。"]},{"t":"别有所感","f":"七言律诗","c":["瑶京曾侍阿环旁，熟极双鬟郭密香。","若论风姿真绝似，争差笑靥要端详。","亲烦记曲拈红豆，巧值移巢过海棠。","宛胜相逢在天上，相怜何况是同乡。"]},{"t":"新年即事 其一","f":"七言绝句","c":["中门夜静不惊厖，鱼媵樵青病一双。","却喜个人犹健在，小楼灯火自关窗。"]},{"t":"新年即事 其二","f":"七言绝句","c":["恹恹春瘦强支持，定累多情百遍思。","特向窗中传数语，要人知道未眠时。"]},{"t":"怜才 其一","f":"七言律诗","c":["九州四海一倾城，独感怜才出至情。","绛帖愿称诗弟子，红楼许拜女先生。","隔帘遥授簪花格，立雪微闻咏絮声。","佛意仙心多占却，最慈悲又最聪明。"]},{"t":"怜才 其二","f":"七言律诗","c":["满楼明月满楼诗，独赏江东第一枝。","书罢便誇王逸少，吟成定压沈佺期。","擎荷尽有生怜意，浮麦终无见面时。","空忍两行知己泪，碧桃花下雨如丝。"]},{"t":"病起书寄个人","f":"七言律诗","c":["情到无聊浅愈深，暂抽书传卜佳音。","古人绝少痴于我，举世谁能谅此心。","一自病躯亲药石，终虚俊眼盼泥金。","临卬配后天缘改，鸾凤参差直到今。"]},{"t":"叠韵再寄","f":"七言律诗","c":["自分情无似我深，深情除是我知音。","发肤以外皆君物，眼耳丛中罄妾心。","死去定成双抱木，生怜亲赠四知金。","天然守礼矜严甚，不为因循误到今。"]},{"t":"真意","f":"七言律诗","c":["似无关涉似心交，一缕轻云曳柳梢。","小影常将花供养，新诗曾授札亲抄。","声名拚为君微损，心力知缘我尽抛。","只合预脩来世果，玉梅枝上结双苞。"]},{"t":"幽怀集兰亭序字 其一","f":"七言律诗","c":["暂同幽晤暮阴天，坐次因知室又迁。","言带一丝兰气在，情犹九曲水流然。","觞脩故事娱生日，竹遇春风亦少年。","会得管夫人静致，今人殊类古人贤。"]},{"t":"幽怀集兰亭序字 其二","f":"七言律诗","c":["幽兰清气极于斯，静坐春风自得之。","左右无人初目遇，死生相感在情知。","一言领悟由当地，万念悲欣集此时。","形迹虽殊怀可述，托将流水作弦丝。"]},{"t":"佩声","f":"七言律诗","c":["佩声归自楚云边，金粟香中拜玉仙。","略带病容尤窈窕，每临高处更鲜妍。","九天早遗眉传语，半日悬知眼欲穿。","偏我来时偏得见，不应如此巧因缘。"]},{"t":"薄游阳羡探张公善卷诸胜舟中书寄妆楼 其一","f":"七言律诗","c":["此间原不是湘湄，无奈平生读楚辞。","云雨易猜神女梦，烟波多似水仙祠。","馨香何处吹兰叶，哀怨频年写竹枝。","小别佩声犹在耳，偶拈红豆又相思。"]},{"t":"薄游阳羡探张公善卷诸胜舟中书寄妆楼 其二","f":"七言律诗","c":["瑶台缥缈楚云端，翠袖亭亭念客寒。","宛转自循栀子佩，清虚应减菊花餐。","预占归日翻书吉，替卜晴天听叶乾。","那得纪游诗百首，尽将踪迹写卿看。"]},{"t":"萼绿","f":"七言律诗","c":["萼绿华来竟体芬，绛纱高揭拜宣文。","诗篇露借蔷薇浣，衣袖香嫌豆蔻熏。","皓月不遮云一点，寒梅常带雪三分。","才名艳福谁双占，冷对风前妒此君。"]},{"t":"从美人家折得桃花一枝归供胆瓶","f":"七言律诗","c":["折得天台顶上枝，争开已近十分时。","祇缘来自倾城处，顿觉生成绝世姿。","物但关情皆可爱，事真入手不嫌迟。","人间多少娇红色，不种伊家不耐思。"]},{"t":"自题筠翠山房 其一","f":"七言绝句","c":["四山流水应宫商，风细吹来箨粉香。","生就几枝斑竹好，被人猜道是潇湘。"]},{"t":"自题筠翠山房 其二","f":"七言绝句","c":["梅语兰香若个温，好将红豆唤山村。","美人欲识相思苦，但看枝枝竹上痕。"]},{"t":"释猜","f":"七言律诗","c":["休猜青鸟浪传书，久畏仙鞭亵念除。","岂料悬弓疑未释，便携团扇计原疏。","星盟那忍抛中道，云气何曾累太虚。","一朵琼花天上影，定无人采似芙蕖。"]},{"t":"梅","f":"七言绝句","c":["月落参横近晓时，人间何处寄相思。","道人自入罗浮梦，除却梅花总不知。"]},{"t":"昨梦","f":"七言律诗","c":["昨梦冥冥夕照黄，青宵归卧细思量。","人因憔悴连书瘦，曲为凄迷比话长。","指水要盟心一片，对花亲授法三章。","几多密誓何由记，隐括新词贮锦囊。"]},{"t":"水仙","f":"七言绝句","c":["花如梅萼玉为肌，叶似兰苕翠带飞。","若与二花同供养，便应猜作古三妃。"]},{"t":"昔梦 其一","f":"七言绝句","c":["圆纹碧浪小红槎，笑倚东南看日华。","醉杀九天霞一朵，那知人世有桃花。"]},{"t":"昔梦 其二","f":"七言绝句","c":["风轮小劫病天魔，一枕颓云散髻螺。","龙树药王医不得，手拈红豆示维摩。"]},{"t":"昔梦 其三","f":"七言绝句","c":["手解婴年旧簸钱，胜如条脱赠羊权。","两边小字绸缪印，尽铸鸳鸯万万年。"]},{"t":"湘妃曲 其一","f":"五言律诗","c":["缥缈三湘瑟，空灵八月槎。","碧天无界限，秋水是人家。","奇玉雌雄佩，幽兰姊妹花。","君山荡空翠，散作洞庭霞。"]},{"t":"湘妃曲 其二","f":"五言律诗","c":["一片潇湘水，春情比我深。","云为神女梦，月是美人心。","眉黛将秋画，衣香弄夕阴。","三星光艳绝，不与夜珠沉。"]},{"t":"楚云","f":"七言律诗","c":["楚云飞破洞庭秋，应是神娥夜出游。","乐府定誇三妇艳，仙家犹带一生愁。","眉如翠羽天难学，手解明珠水共流。","肠自九回湘九曲，通辞何处托横眸。"]},{"t":"题周防背面美人图 其一","f":"七言绝句","c":["惊鸿瞥见又逡巡，珠压腰裾稳称身。","绝似簸钱堂上事，忍羞和笑避生人。"]},{"t":"题周防背面美人图 其二","f":"七言绝句","c":["小朵樱桃折得不，无人窥见绿蛾愁。","玉阶唤杀红鹦鹉，不是欢来不转头。"]},{"t":"题周防背面美人图 其三","f":"七言绝句","c":["脸波藏却媚霞痕，只露双肩削玉温。","心自向君身自背，省他一见一消魂。"]},{"t":"题周防背面美人图 其四","f":"七言绝句","c":["只量钿尺认腰支，那有春风见面时。","会得李夫人意态，背人翻是耐人思。"]},{"t":"题周防背面美人图 其五","f":"七言绝句","c":["妙句青邱最有情，倾城虽见画难成。","诗人设想还痴绝，要看回头百媚生。"]},{"t":"题周防背面美人图 其六","f":"七言绝句","c":["不用传神阿堵中，画师妙手只空空。","累他多少旁观眼，相背人人学蒯通。"]},{"t":"题周防背面美人图 其七","f":"七言绝句","c":["几时回首眼波横，枉费千呼万唤声。","画里未容人省识，如何妄想作刘桢。"]},{"t":"新年纪别","f":"七言律诗","c":["梅花如雪冻檐阴，阁住斜阳不肯沉。","颜为避人温似玉，语因惜别重于金。","莫云未定缘离合，春水难知分浅深。","坐久翻催君速去，带香和笑已沾襟。"]},{"t":"有寄","f":"七言绝句","c":["苦被东风柳色催，红窗辜负玉梅开。","相思寄与清淮水，流到长江莫打回。"]},{"t":"生辰日 其一","f":"七言绝句","c":["卖冰声唤小窗眠，梦想江南远似天。","记得年年今日事，并头花下拜双仙。"]},{"t":"生辰日 其二","f":"七言绝句","c":["鸥波仙馆即莲台，绣佛炉香煖不灰。","应有兜罗绵样手，笑持荷叶捧觞来。"]},{"t":"生辰日 其三","f":"七言绝句","c":["小阮风情记我家，与君同日好年华。","而今憔悴相如病，辜负芙蓉脸际花。"]},{"t":"生辰日 其四","f":"七言绝句","c":["更有参军小妹清，藕花生日一齐生。","无端吹折同心蒂，零落红衣画不成。"]},{"t":"写梅寄个人 其一","f":"七言绝句","c":["画梅多画影姗姗，一动萧疏耐远看。","我道至情须领会，疏时容易密时难。"]},{"t":"写梅寄个人 其二","f":"七言绝句","c":["澹著胭脂澹扫螺，亭亭瘦影照横波。","由来绝色人难画，只画梅花便当他。"]},{"t":"写梅寄个人 其三","f":"七言绝句","c":["也知眼孔小于纱，守定西溪当若耶。","天上纵然花绝代，老逋只解爱梅花。"]},{"t":"写梅寄个人 其四","f":"七言绝句","c":["平生空说爱南枝，一岁相逢得几时。","自拂银笺写来看，胜如閒坐苦相思。"]},{"t":"读史","f":"七言绝句","c":["心头眼底一真真，料得人间定绝伦。","读尽史书佳丽传，何人如我意中人。"]},{"t":"自题横霞仙馆 其一","f":"七言绝句","c":["万树梅花水一村，春山如梦月如魂。","只消一角横波翠，阑住诗人不出门。"]},{"t":"自题横霞仙馆 其二","f":"七言绝句","c":["四禅天上住人家，手札青鸾扫落花。","收拾红香到仙枕，一去同梦是朝霞。"]},{"t":"深恩四首 其一","f":"七言律诗","c":["一绺轻云落剪香，缄题和泪报王昌。","并头私愿知难遂，束发深情誓莫忘。","绾住同心须不乱，祝将恩分愈加长。","从今添入潘郎鬓，胜捧仙鬟嗅枕旁。"]},{"t":"深恩四首 其二","f":"七言律诗","c":["画帘鹦鹉语呼茶，天女亲擎一朵霞。","味美那滑添茗叶，香清浑似带梅花。","早知郎性凉须忌，不避人嫌爱越加。","我却贪痴还未足，比卿芳乳略差些。"]},{"t":"深恩四首 其三","f":"七言律诗","c":["玉壶春色比花妍，纤手亲斟与谪仙。","情到十分如酒满，缘徵百岁似杯圆。","为卿拚死何辞醉，知我沉酣屡劝眠。","馀沥互搀莲子盏，分明合卺绣床前。"]},{"t":"深恩四首 其四","f":"七言律诗","c":["百花谁似玉梅妍，动是飞仙静益仙。","绝色惊看天不老，同心痴望月常圆。","三年尽受回眸爱，一夕曾邀恣意怜。","素女若容缘再续，今宵双拜桂花前。"]},{"t":"仲冬十一日纪事","f":"七言绝句","c":["红入双腮四体酥，绣帏沉醉不胜扶。","玉郎悄地潜踪到，细看杨妃美睡图。"]},{"t":"绝世 其一","f":"七言律诗","c":["意态浓纤世所稀，梅花嫌瘦海棠肥。","媚生一笑能苏病，秀出双眸可疗饥。","发美尽人分作剃，肌香从小罢熏衣。","卫风借作卿图影，才得形相欠入微。"]},{"t":"绝世 其二","f":"七言律诗","c":["闲房左右寂无人，偷齧樱桃一点春。","事后思量犹错过，忙中惊颤已逡巡。","防闲暗许鞋尖觉，偎傍遥贪袖角亲。","十五年前常意态，消魂此日胜尝新。"]},{"t":"密字 其一","f":"七言律诗","c":["密字珍珠侧理裁，问郎何处恣徘徊。","终年细数无多见，隔日幽期不定来。","凤响误猜搴绣箔，花阴闲看过妆台。","芳心一寸芸香瓣，炉篆成灰未肯灰。"]},{"t":"密字 其二","f":"七言律诗","c":["日来憔悴瘦腰身，兰语当窗嘱付谆。","随意清游聊遣闷，韬精沉饮恐伤神。","蔗梢细嚼终无味，桃核双欢别有仁。","每到花丛须记忆，东风岑寂倚楼人。"]},{"t":"个人 其一","f":"七言绝句","c":["个人第一是青丝，委地春云挽髻迟。","记得刺桐花下等，水晶帘外日斜时。"]},{"t":"个人 其二","f":"七言绝句","c":["个人第一是双蛾，澹扫春山不费螺。","自识玉郎心事重，展时偏少蹙时多。"]},{"t":"个人 其三","f":"七言绝句","c":["个人第一是星眸，载得聪明又载愁。","只许消魂人自觉，暗传心事不抬头。"]},{"t":"个人 其四","f":"七言绝句","c":["个人第一是双腮，酒晕微涡笑靥堆。","一缕睡情支不住，红云飞上限梢来。"]},{"t":"个人 其五","f":"七言绝句","c":["个人第一是朱樱，匿笑搴帷皓齿呈。","翻道诗人莲舌好，愿通花气过聪明。"]},{"t":"个人 其六","f":"七言绝句","c":["个人第一是兰胸，菽发凝脂隐约中。","一抹红褂严结束，却逢郎手自通融。"]},{"t":"个人 其七","f":"七言绝句","c":["个人第一是春纤，亲替檀奴熨指尖。","丁嘱避嫌心事切，人前卮酒莫同拈。"]},{"t":"个人 其八","f":"七言绝句","c":["个人第一是双莲，风韵行来步步妍。","可记暗中金钿落，绣鞋香气泊人肩。"]},{"t":"灯夕即事","f":"七言律诗","c":["千枝灯火一枝花，十二瑶台耸翠霞。","仙去偏愁郎有伴，月来如梦姊为家。","微闻人语疑清瑟，近隔天河只片纱。","应被市中吹笛者，遥占珠斗贯浮槎。"]},{"t":"蓄兰一本数年始得花","f":"七言律诗","c":["几年珍重护春寒，一箭才逢白玉阑。","静色能消粗气味，异香不是古旃檀。","半生心力全抛与，万事艰难倍可欢。","真到眼前偏认作，画中看又梦中看。"]},{"t":"娇女","f":"七言律诗","c":["左思娇女似娇禽，来道胜常送好音。","书是宣文亲口授，花令小玉上头簪。","学分绣线宜纤手，解辨琴弦有慧心。","一点樱唇留墨在，曹娥碑字甫抚临。"]},{"t":"品花","f":"五言律诗","c":["花里三倾国，梅兰及海棠。","可餐皆秀色，不断是生香。","春思依依梦，秋阴寸寸肠。","何时满人意，都植在潇湘。"]},{"t":"花朝","f":"七言律诗","c":["碧云特地破新晴，小阁玲珑即玉京。","花影尽如人窈窕，语香多将佛聪明。","思量过此春非浅，欢喜来时病亦轻。","脩到群芳缘恰好，不同开日却同生。"]},{"t":"寒宵纪梦仿会真体","f":"七言古诗","c":["青粉墙高接半天，黄昏风紧月娟娟。","斜门寂静推敲细，曲巷阴沉伺守坚。","乍听钟声空外动，忽惊人语暗中传。","朱唇微嗽来屏角，纤指轻弹近阁边。","预启间窗教侧足，偷开秘钥许容肩。","中途几被监奴觉，内院才闻采伴眠。","入户衣裳防綷縩，牵帏步屧屡蹁跹。","卸颐别绾珑松髻，熏被犹馀叆叇烟。","展侧冰肌如水滑，偎依粉颊比花妍。","一弯雪臂玲珑藕，三寸红帮窄小莲。","脂熟樱桃鹦饱啄，香披豆蔻蝶深穿。","流苏悄击银钩宕，密炷潜吹宝鼎然。","眼媚横流微腼觍，唤声低彻恣缠绵。","当胸袜绣堆茵软，衔耳环铛堕枕偏。","惊颤芙蓉承露重，狂飞柳絮逞风颠。","幽欢放胆终虚怯，浓笑回身忽涕涟。","长恨赤绳愆夙分，自嫌锦瑟过华年。","鸳囚难卜重逢日，鱼媵甘图再世缘。","可奈晨鸡先促迫，尚贪宿鲽暂流连。","钗分紫玉酬深爱，裯拥青绫耐细怜。","剪发早申偕老愿，抽毫索记定情篇。","前游历历明于镜，回忆茫茫坠似钿。","姑射神妃原幻梦，维摩天女本空禅。","觉来襟袖沾霞气，赢得人呼是谪仙。"]},{"t":"深恩","f":"七言律诗","c":["手缄瑶札报知音，昨夜云窝昨夜衾。","蝶梦正酣香万顷，鸡声偏断刻千金。","花缘露重翻含泪，烛为风流尽吐心。","自把深恩酬至爱，如何转说受恩深。"]},{"t":"续美人诗二首前首续上二句后首续下二句凫胫接鹤狗尾续貂两美同心并蒙印可 其一","f":"七言绝句","c":["浴罢轻衫出洞房，寻寻觅觅费思量。","梧桐月色炎如昼，忆著郎来便觉凉。"]},{"t":"续美人诗二首前首续上二句后首续下二句凫胫接鹤狗尾续貂两美同心并蒙印可 其二","f":"七言绝句","c":["手搴芍药坐凝思，地久天长在后时。","只写灵飞经数字，无人知道定情诗。"]},{"t":"瑶窗","f":"七言律诗","c":["羊灯未上月如丝，偷出中门步屧迟。","拂槛衣声疑竹韵，窥窗鬓影误花枝。","乍尝险味情逾怯，强定惊魂力不支。","踪迹怕人猜料著，暗中归去朗吟诗。"]},{"t":"把酒祝东风辞","f":"七言律诗","c":["龙盘镜子凤头鞋，屡卜幽期总不谐。","七泽三湘途易阻，六张五角事多乖。","花如可折难抬手，月岂能探却堕怀。","只种相思无结实，东风相祝酒如淮。"]},{"t":"淑意","f":"七言律诗","c":["人前苦嘱莫留情，无奈情深态越轻。","踪影已离君座远，眼光偏注妾边明。","廋辞纵许同心会，羞晕难防两颊呈。","非是恩浓情转淡，可知妒眼绕如城。"]},{"t":"满愿","f":"七言律诗","c":["双峰雪映日华妍，八尺龙须乍起眠。","甘后有心呈煖玉，杨妃无力出温泉。","低容不作娇羞避，缓语翻教恣意怜。","若使小家拘束态，定因匆遽失天然。"]},{"t":"病暗","f":"七言律诗","c":["扶定寒香冉冉来，轻云纤月共徘徊。","罢妆风韵全关慧，郁性温柔别是才。","微露隐肠知我解，频支倦态厌人猜。","相看一种悲愁味，画尽宣炉寸寸灰。"]},{"t":"天水","f":"七言律诗","c":["如天仪度水年华，天水由来是外家。","百病尽捐霜后箨，三生自忏雨中花。","琼楼写韵人谁到，玉尺量才事可誇。","笑我会稽王内史，十年弟子隔屏纱。"]},{"t":"书梅寄情人 其一","f":"七言绝句","c":["人间难画是相思，只画瑶台绝世姿。","脩到他生须记得，谢娘庭院雪来时。"]},{"t":"书梅寄情人 其二","f":"七言绝句","c":["玉姿清瘦不禁风，缟袂依稀薄雾笼。","记得小红阑角事，满身香雪月明中。"]},{"t":"书梅寄情人 其三","f":"七言绝句","c":["青粉墙高欲度难，暂将绿萼当珊珊。","灯前写幅横斜影，贴上屏风恣意看。"]},{"t":"书梅寄情人 其四","f":"七言绝句","c":["毕竟天姿画不成，拈毫心事更纵横。","明知卿貌花难替，只要卿知我画卿。"]},{"t":"紫云楼话月 其一","f":"七言绝句","c":["三生石碎四禅空，情梦重温雪上鸿。","贪傍一株红豆树，不知清露湿怀中。"]},{"t":"紫云楼话月 其二","f":"七言绝句","c":["樱桃小火鸭炉温，帘影条条落水痕。","楼下月明楼上语，人生能得几黄昏。"]},{"t":"紫云楼话月 其三","f":"七言绝句","c":["灯昏月瘦已三更，听尽潇湘雁过声。","修作他生真姊弟，相怜未必似今生。"]},{"t":"赠别辞","f":"七言律诗","c":["寄语琼楼仙子知，寒潮已放舻双枝。","重看正恐添惆怅，径去翻教省别离。","纵忆娇儿须强饭，便逢佳客少题诗。","留将不坏娑椤果，会有华严再见时。"]},{"t":"闲情","f":"七言绝句","c":["走马寻春得得忙，嫣红姹紫尽芬芳。","归来静对寒梅嗅，始觉閒花带草香。"]},{"t":"口佗生 其一","f":"七言律诗","c":["一寸相思一寸笺，真珠密字泪珠穿。","侯门空守黄昏约，仙洞难期碧落缘。","锦帨尚愁厖欲吠，银桥那有鹊能填。","留将玉洁冰清体，好作来生并蒂莲。"]},{"t":"口佗生 其二","f":"七言律诗","c":["一纸情书订夙因，妙莲香里證明神。","姻缘注定他生簿，才貌脩如见在身。","说到死期心转快，记来前世事须真。","风轮小劫随飘堕，佳耦先逢绝代人。"]},{"t":"潇湘楼杂忆 其一","f":"七言绝句","c":["湘帘跨出尚逡巡，要使郎看要避人。","立近小红窗一角，半容娇眼半遮身。"]},{"t":"潇湘楼杂忆 其二","f":"七言绝句","c":["闻郎声息画楼过，偷露梨花半面多。","莫恨全身看未足，情辞都已在微波。"]},{"t":"潇湘楼杂忆 其三","f":"七言绝句","c":["扇囊宠赐九天霞，上绣莲兰两种葩。","不独爱他高品格，花中此是并头花。"]},{"t":"潇湘楼杂忆 其四","f":"七言绝句","c":["碧瓯亲自捣云浆，暗度华池玉液香。","口口愿郎都吸尽，莫留点滴与人尝。"]},{"t":"潇湘楼杂忆 其五","f":"七言绝句","c":["银湾渺渺隔云端，谁道恩波天样宽。","膏露暗施花叶上，不留痕迹教人看。"]},{"t":"潇湘楼杂忆 其六","f":"七言绝句","c":["公然青鸟下蓬瀛，瞒过双鬟与长卿。","才算聪明真绝世，别无一字自分明。"]},{"t":"潇湘楼杂忆 其七","f":"七言绝句","c":["楼上闻声楼下行，楼前妒眼已成城。","隔帘微露云鬟影，料是王昌眼最明。"]},{"t":"潇湘楼杂忆 其八","f":"七言绝句","c":["下楼风恰绣裙掀，偷见弓弯窄更纤。","乞与重台莲一瓣，朝朝枕上看红尖。"]},{"t":"潇湘楼杂忆 其九","f":"七言绝句","c":["郎来红日已衔山，采伴兜留苦不閒。","终日相思能几见，累他一度又空还。"]},{"t":"潇湘楼杂忆 其十","f":"七言绝句","c":["略掀帘子露微颦，却恐消魂看未真。","侬有小鬟郎有伴，一般惧碍作閒人。"]},{"t":"潇湘楼杂忆 其十一","f":"七言绝句","c":["鹦鹉能呼燕子猜，中楼那得久徘徊。","胡麻饭罢当窗绣，郎若来时过午来。"]},{"t":"潇湘楼杂忆 其十二","f":"七言绝句","c":["楼窗蛱蝶绣将成，楼下鹦哥唤客声。","半日盼郎郎不到，教侬错认几人行。"]},{"t":"潇湘楼杂忆 其十三","f":"七言绝句","c":["两情相敬久如宾，却隔重楼迹未亲。","望见佯佯先立起，旁人只道避生人。"]},{"t":"潇湘楼杂忆 其十四","f":"七言绝句","c":["倒身我欲拜慈航，却恐卿嗤阮籍狂。","暗向神光微点首，心头自爇妙莲香。"]},{"t":"潇湘楼杂忆 其十五","f":"七言绝句","c":["无计留行且送行，画阑特地倚新晴。","难将此意教郎会，兜语双鬟送笑声。"]},{"t":"潇湘楼杂忆 其十六","f":"七言绝句","c":["茉莉香迎出浴迟，欢来是妾晚妆时。","一番走马看花去，添得消魂几首诗。"]},{"t":"指爪","f":"七言律诗","c":["粉印脂痕尚宛然，温柔如捧手兜绵。","调兰雪藕曾消受，握雨携云未结缘。","聊当搯肤成密誓，尽堪搔背遗清眠。","麻姑鸟爪亲声寄，不怕方平浪下鞭。"]},{"t":"委曲辞 其一","f":"七言绝句","c":["方胜红笺达粉奁，公然妄想学鹣鹣。","梅花肯嫁林君复，唤作卿卿傥不嫌。"]},{"t":"委曲辞 其二","f":"七言绝句","c":["忍把旁妻唤小乔，封还两字笔新标。","罗敷已有鬑鬑婿，辜负琴心着意挑。"]},{"t":"委曲辞 其三","f":"七言绝句","c":["锦字收回自悔粗，甘心鞭背谢麻姑。","愿天罚受维摩病，消得闺中薄怒无。"]},{"t":"委曲辞 其四","f":"七言绝句","c":["郎病根由细揣量，料应未解妾柔肠。","重题数字缄封去，抵得卢医肘后方。"]},{"t":"委曲辞 其五","f":"七言绝句","c":["封就鸾书少雁传，托题纨扇送君边。","如何枉负聪明煞，自把机关错眼前。"]},{"t":"委曲辞 其六","f":"七言绝句","c":["互斗聪明似弈棋，同心消息少参差。","昨宵为怯旁人看，算到卿心一着迟。"]},{"t":"委曲辞 其七","f":"七言绝句","c":["晨窗翠鸟忽衔将，小叠花笺扇角藏。","只有万千珍重字，青丝一绺裹中央。"]},{"t":"委曲辞 其八","f":"七言绝句","c":["人世婚姻定自天，争如才色自相怜。","劝郎莫认夫妻好，认作夫妻转嚼然。"]},{"t":"委曲辞 其九","f":"七言绝句","c":["手捧云笺病已差，欲脩报札转迟迟。","连朝心事从头写，当取家书莫当诗。"]},{"t":"委曲辞 其十","f":"七言绝句","c":["郎书隐语自分明，妾自关心记得清。","无限深情难下笔，只描兰蕊并头生。"]},{"t":"兰舫纪游 其一","f":"七言绝句","c":["才傍仙舟语未交，星眸早已隔帘招。","有人先我停兰桨，半晌何曾见阿翘。"]},{"t":"兰舫纪游 其二","f":"七言绝句","c":["一春玉恙闭罘罳，声息何曾外院知。","今日花前扶病出，教郎知道减轻时。"]},{"t":"兰舫纪游 其三","f":"七言绝句","c":["标格矜严渐觉宽，水天閒话倚阑干。","笑容也怕人猜料，无奈逢欢意自欢。"]},{"t":"兰舫纪游 其四","f":"七言绝句","c":["画舫潜移傍曲池，烟波何处觅西施。","玉清纵使重追著，错过良缘已片时。"]},{"t":"兰舫纪游 其五","f":"七言绝句","c":["綵云重见蓼花湾，可奈斜阳送客还。","兰棹渐移人渐远，碧纱犹自度春山。"]},{"t":"兰舫纪游 其六","f":"七言绝句","c":["春游归去病兼愁，又是经旬不下楼。","特为消魂人强起，绿窗风月控帘钩。"]},{"t":"秋词 其一","f":"七言绝句","c":["相如病骨怕秋寒，那更临风惨不欢。","千万为侬休自苦，君身安始妾心安。"]},{"t":"秋词 其二","f":"七言绝句","c":["风清露白已凉天，楼上灯红尚未眠。","如此夜深罗袖薄，为谁犹立绣窗边。"]},{"t":"秋词 其三","f":"七言绝句","c":["仙人生就骨清癯，谁识丰容是病馀。","那得纤腰真入抱，玉肌亲切看何如。"]},{"t":"纪缘尽日","f":"七言绝句","c":["未通眉语已通情，只隔湘帘不隔声。","临别回眸重一顾，累人惆怅过今生。"]},{"t":"悼词 其一","f":"七言律诗","c":["惊传神女已生天，兽鼎盟香息穗烟。","妄冀因缘酬再世，难追魂魄到重泉。","封题密札三千字，担受虚名十五年。","剩有潇湘图画影，一回展礼一潸然。"]},{"t":"悼词 其二","f":"七言律诗","c":["自怜身世太凄凉，幸遇知音玉尺量。","直道此才无敌手，每称难得有情郎。","遗文序早求张说，诔笔词还属谢庄。","痴欲凭棺成一恸，深思岂是泪能偿。"]},{"t":"悼词 其三","f":"七言律诗","c":["霜里幽兰雪里筠，可怜摧折不成春。","七情雕就颜如玉，百病磨来性出尘。","仙树逍遥无结子，慈云缥渺是前身。","弯弓欲射银蟾落，追转姮娥作世人。"]},{"t":"悼词 其四","f":"七言律诗","c":["影堂重过不胜情，无语低头一径行。","只当个人远病在，若闻来客恐心惊。","诗篇狼籍收难尽，画稿丛残半未成。","检点巾箱旧钿盒，玉环知否有来生。"]},{"t":"拜梅","f":"七言绝句","c":["青莲才思九州横，独对梅花傲不成。","七贵五侯供一笑，满身风雪拜卿卿。"]},{"t":"元日","f":"七言律诗","c":["莺啼燕语报新年，亲拜红妆玉镜前。","绝艳人如初透日，乍中年似嫩春天。","芳心密取明琼卜，茗汁迟催小玉煎。","手剥梅仁传吉语，愿郎瓜瓞更绵绵。"]},{"t":"兰房 其一","f":"七言律诗","c":["当初握手寻常事，谁道如天不可攀。","齧颈尚留纤齿印，搯肤同验炙香瘢。","持裙偷搦莲双瓣，伏枕劳舒藕一弯。","今日隔窗窥午绣，一层云纸万重山。"]},{"t":"兰房 其二","f":"七言律诗","c":["兰房寂静卧乌龙，翻促郎行坐不容。","非是热肠偏小胆，祇缘妒眼惯潜踪。","言当要处尤宜少，情果真时岂在浓。","留得清名相见好，并头曾已学芙蓉。"]},{"t":"横霞仙馆杂事 其一","f":"七言绝句","c":["佛容光艳世无寻，供养端宜紫竹林。","我愿将身化童子，朝朝合掌拜观音。"]},{"t":"横霞仙馆杂事 其二","f":"七言绝句","c":["只道粗才定品差，幽兰偏比别人家。","回瞋一笑思量著，原是梅花第一花。"]},{"t":"横霞仙馆杂事 其三","f":"七言绝句","c":["为恐狂奴思不禁，朱樱宛转避春禽。","星妃微露莲花舌，未许沾唇已许心。"]},{"t":"横霞仙馆杂事 其四","f":"七言绝句","c":["画堂相见倍矜严，眼角眉梢尽避嫌。","六幅湘裙风不动，暗传心事与鞋尖。"]},{"t":"横霞仙馆杂事 其五","f":"七言绝句","c":["郎来深坐绿窗纱，看我梳成两鬓鸦。","当着小姑留不得，待伊临去唤煎茶。"]},{"t":"横霞仙馆杂事 其六","f":"七言绝句","c":["含情低首不轻抬，还恐当窗女伴猜。","趁着金针重度候，看郎偷眼看侬来。"]},{"t":"横霞仙馆杂事 其七","f":"七言绝句","c":["相邀姊妹出花前，人自徐行我转先。","闪过小屏山一角，任郎偷搦指尖妍。"]},{"t":"横霞仙馆杂事 其八","f":"七言绝句","c":["春社如云紫陌过，重帘窣地注娇波。","谁知帘外萧郎立，促膝温存半晌多。"]},{"t":"横霞仙馆杂事 其九","f":"七言绝句","c":["戏取茶瓯当酒杯，手拈红豆教郎猜。","怪人料事偏奇中，手握双钩不肯开。"]},{"t":"横霞仙馆杂事 其十","f":"七言绝句","c":["欲度樱桃味与郎，背人离坐走佯佯。","玉瓯一点波罗蜜，分付消魂自去尝。"]},{"t":"横霞仙馆杂事 其十一","f":"七言绝句","c":["问郎底事病双眸，可恨银灯可闷愁。","好避绿窗风日煖，如何还写字蝇头。"]},{"t":"横霞仙馆杂事 其十二","f":"七言绝句","c":["仙骨姗删响佩琚，径来檀几泥相如。","玉纤替按云蓝纸，只道贪看倒薤书。"]},{"t":"情钟","f":"七言律诗","c":["伊人双颊秀芙蓉，自识相如带病容。","频蹑幽踪忘露冷，互穿衵服漏香浓。","思深不记无心过，语密亲除有用封。","薄倖自惭兼薄福，如何消受此情钟。"]},{"t":"锦袜","f":"七言律诗","c":["宝袜亲裁翠锦鲜，关心脱赠早凉天。","重绵托里情深厚，密线缝围手巧妍。","但许贴胸如妾抱，无由输意伴君眠。","他时认取斑斑迹，莫弃香笼绣箧边。"]},{"t":"娇瞋 其一","f":"七言绝句","c":["热肠冷面两难猜，越是依依越飏开。","却忆乍成欢爱日，满身香雾近人来。"]},{"t":"娇瞋 其二","f":"七言绝句","c":["错认真情是杂情，难将心迹剖分明。","只消自看淩波影，更有何人比得卿。"]},{"t":"奏记妆楼 其一","f":"七言绝句","c":["自迁楼阁可清宁，可怕高寒可睡醒。","可想玉郎声息到，推窗悄倚画屏听。"]},{"t":"奏记妆楼 其二","f":"七言绝句","c":["平时行近绣帘前，一笑双眸语早传。","今日怕掀帘子看，隔层楼似隔层天。"]},{"t":"奏记妆楼 其三","f":"七言绝句","c":["听得鹦哥唤客不，屧声已到玉梯头。","心嫌女伴私猜料，只说看花偶下楼。"]},{"t":"初夏","f":"七言律诗","c":["绿阴浓染合欢床，花里潜踪入洞房。","幽怨襟情难细语，转疑滋味胜初尝。","不知金钿何时落，谁识罗裙别有香。","道是分明原是梦，风光瞥去耐思量。"]},{"t":"牡丹下宴集 其一","f":"七言绝句","c":["锦幛围云五色齐，入窗都展绿玻瓈。","名花一种春无赛，却见倾城首亦低。"]},{"t":"牡丹下宴集 其二","f":"七言绝句","c":["斜背花枝坐绿纱，恐花羞见面如霞。","反教夺尽花颜色，人对花来不看花。"]},{"t":"牡丹下宴集 其三","f":"七言绝句","c":["女伴藏钩赌玉杯，聪明十度九赢回。","就中偏是郎心湣，却费沉吟半晌猜。"]},{"t":"牡丹下宴集 其四","f":"七言绝句","c":["郎拈梅子出花阴，剥赠梅仁示意深。","故把玉纤摩弄久，教伊知道会伊心。"]},{"t":"牡丹下宴集 其五","f":"七言绝句","c":["席罢香舆散画阑，感卿花下独来看。","比肩立尽斜阳影，相见非难别总难。"]},{"t":"记忆即书 其一","f":"七言绝句","c":["社鼓喧喧殷六街，东风摇荡画帘斜。","万花丛里偷眸看，始信梅花第一花。"]},{"t":"记忆即书 其二","f":"七言绝句","c":["一闪横波抵万金，乍掀帘已见芳心。","瓜犀赠自掺掺手，情比当年掷果深。"]},{"t":"记忆即书 其三","f":"七言绝句","c":["闻郎声息翠帘开，连日潜踪著意猜。","知道袖中藏数字，百方图便近身来。"]},{"t":"记忆即书 其四","f":"七言绝句","c":["待来何事却来迟，已近花阴月上时。","口自怨郎心自喜，暗中情味没人知。"]},{"t":"记忆即书 其五","f":"七言绝句","c":["病中消息恣窥觇，悄揭罗帏按玉纤。","平日未容亲近处，今朝不道尽无嫌。"]},{"t":"记忆即书 其六","f":"七言绝句","c":["投琼斗叶两无猜，众里横波不肯抬。","挨到上灯移坐近，一钩新月暗钩来。"]},{"t":"记忆即书 其七","f":"七言绝句","c":["盈盈绿水出芙蕖，娇韵才如二十馀。","昨日女儿相并立，风情翻较阿娘输。"]},{"t":"记忆即书 其八","f":"七言绝句","c":["临别贪看月下姿，黄昏风露下阶迟。","知郎尚有流连意，特向明蟾立片时。"]},{"t":"记忆即书 其九","f":"七言绝句","c":["心性年来倍耐愁，沉潜声影坐楼头。","轻风任墼帘钩响，不是郎来不下楼。"]},{"t":"记忆即书 其十","f":"七言绝句","c":["此生百念已灰寒，薄倖休疑会合难。","剩有丹诚心一点，可怜无计剖君看。"]},{"t":"曲房","f":"七言律诗","c":["青桐一树瘦摇凉，最密帘栊最后房。","细雨暗催眉黛绿，晚风微度鬓花香。","悄闻步屧推屏起，略近妆台触瑟忙。","一种乍尝惊颤味，清宵归卧细思量。"]},{"t":"释炻","f":"七言绝句","c":["寒暄数语出金堂，一字无由漏隐肠。","越是空来情越好，当时容易转寻常。"]},{"t":"夏词 其一","f":"七言绝句","c":["绿街迎夏夹衣更，玉秤称来并体轻。","人笑同心是天定，一同欢喜一同惊。"]},{"t":"夏词 其二","f":"七言绝句","c":["投我灵瓜美似饴，分明冰雪个人肌。","早知郑灼然心火，此物清凉可暂医。"]},{"t":"夏词 其三","f":"七言绝句","c":["鹦鹉当窗不敢呼，玉钩响处卷帘无。","风前冉冉轻云影，一幅杨妃出浴图。"]},{"t":"夏词 其四","f":"七言绝句","c":["小姑新制碧筒香，强捉檀奴尽一觞。","亲剥莲蓬瑩似玉，背灯佯置镜台旁。"]},{"t":"秋词 其一","f":"七言绝句","c":["小病恹恹过暑天，嫩黄姿色谢华铅。","今朝薄傅芙蓉粉，省得郎看瘦可怜。"]},{"t":"秋词 其二","f":"七言绝句","c":["红墙绿绦谢娘家，金凰开齐五色霞。","楼角一钩黄月淡，麻姑爪上看桃花。"]},{"t":"秋词 其三","f":"七言绝句","c":["洗空脂粉晚妆成，真色看来倍有情。","更喜一弯心字月，玉人眉额照秋清。"]},{"t":"秋词 其四","f":"七言绝句","c":["洞房轻把玉屏推，手握青丝下镜台。","知为阿侬生日到，多情先日送花来。"]},{"t":"午梦","f":"五言古诗","c":["长日因循候，閒房寂静时。","倦解樊昵侍，计遣阿侯嬉。","委地垂银押，当窗隐画丝。","近前来冉冉，却立故迟迟。","佩任湘裙妥，钗从翠鬓欹。","蒙茸珍火齐，绰约献冰肌。","侧耳风声过，关心竹影移。","喜多翻震荡，力弱为惊疑。","婉转花频就，阑珊蝶已疲。","暂推无妄疾，深负有情痴。","吃吃思前度，惺惺订后期。","难成偏好梦，惆怅定如斯。"]},{"t":"中秋","f":"七言律诗","c":["雀炉烟穗袅黄昏，月过回廊乍掩门。","虫覆叶深栖迹稳，蝶藏花小受香温。","风鬟细闪珠灯影，雪腕微沾玉露痕。","如此风情如此夜，一回相见一消魂。"]},{"t":"缝履","f":"七言律诗","c":["绿华传履制玲珑，珍重寒闺妙手功。","晓箧豫分金线碧，夜窗频剔玉釭红。","回肠默转回针处，密意潜含密缕中。","著向閒阶须护惜，祇缘缝缀费春葱。"]},{"t":"评梅","f":"七言绝句","c":["东阁南枝第一春，阿谁配得藐姑神。","无心自与梅花品，半晌低颜不应人。"]},{"t":"雨阻 其一","f":"七言绝句","c":["黄昏独自下帘栊，挑尽银釭不肯红。","有限清欢好时节，可堪抛掷雨声中。"]},{"t":"雨阻 其二","f":"七言绝句","c":["料卿知我忆卿真，绣被难安转侧身。","听尽漏声还听雨，绿窗同是未眠人。"]},{"t":"雨阻 其三","f":"七言绝句","c":["闭户沉沉长绿莎，隔条街巷抵银河。","一宵两处芭蕉上，不敌相思泪点多。"]},{"t":"雨阻 其四","f":"七言绝句","c":["兼旬梅雨苦如年，霁后晴云火欲然。","雨即阻人晴亦阻，天公难作是情天。"]},{"t":"雨阻 其五","f":"七言绝句","c":["相期隔日到妆台，苦被金闺女伴猜。","如此炎官张火伞，迎朝触热为谁来。"]},{"t":"书愤寄所思 其一","f":"七言绝句","c":["怕检罗衣旧日香，怕登楼阁睹斜阳。","眼前事事皆堪哭，特借飞花恸一场。"]},{"t":"书愤寄所思 其二","f":"七言绝句","c":["旁挠欢计阻良缘，中道风波岂偶然。","我痛世人皆欲杀，不如卿有一人怜。"]},{"t":"仙梦 其一","f":"七言律诗","c":["灯昏如梦月沉沉，曲折仙源许恣寻。","细草生香迷洞口，片云含雨阁花阴。","捣霜玉杵愁轻重，濯锦银河试浅深。","十二万年今夕事，一回追忆定沾襟。"]},{"t":"仙梦 其二","f":"七言律诗","c":["绛蜡生珠泪未挑，石鸡无奈应春潮。","合欢慢揭青绫帐，团聚从吹紫玉箫。","洞草尚含仙露湿，峡花犹带梦云摇。","风光瞥去馍糊甚，才著思量似昨朝。"]},{"t":"答怨","f":"七言律诗","c":["百尺红楼一寸诚，愿随飞絮入檐楹。","焚山终想求毛女，抱柱何辞作尾生。","薄怒音词深似笑，过防心胆易成惊。","佯推故却应须会，不负初盟肯负情。"]},{"t":"答羞","f":"七言律诗","c":["干金一刻价无酬，斗帐明姿映烛羞。","峡里云行原是梦，洞中霜煖不知秋。","抱香眠蝶忘朝暮，罥树飞花惜去留。","谁把鸳鸯颠倒配，青天易补恨难休。"]},{"t":"答疑","f":"七言律诗","c":["阳台声息误传闻，苦寄连波锦字文。","莲座久皈香一瓣，梅花敢议白三分。","有星偶近天边月，为雨原无峡外云。","沟水东西羞薄倖，锦衾长守卓文君。"]},{"t":"晓妆","f":"七言律诗","c":["水精帘下晓风凉，委地春云五尺长。","容易偷窥殊出浴，最难亲见是残妆。","愿为花朵依鬟侧，想到钗声堕枕旁。","待与侍儿商略取，红梳梳下几丝香。"]},{"t":"小字","f":"七言律诗","c":["谢公最小女偏怜，小字呼来定绛仙。","一月回悬珠树朗，百花都让玉梅妍。","疗饥自喜忘并日，消渴何辞为损年。","每向画眉窗下见，匡庐只在镜台前。"]},{"t":"排次","f":"七言律诗","c":["姊妹行中最下肩，女儿星次斗牛边。","数来指节螺纹遍，翻到眉图月晕妍。","辽后香词书宛转，丁娘丽曲索缠绵。","宋宫谢女原排十，倾国偏推第一仙。"]},{"t":"生辰","f":"七言律诗","c":["十日清和未改春，玉厨樱笋作生辰。","问年愁误波斯女，降日应推洛水神。","屈指浣花须下九，当头弦月倚初旬。","金盘香露前朝聍，浴罢如来浴美人。"]},{"t":"病悰","f":"七言律诗","c":["得遂幽期病转深，梅花开日到如今。","香盟纵结鸳鸯带，好梦难温翡翠衾。","千尺水深通素札，一重山远隔罗襟。","料无灵药能医治，愿化西天并命禽。"]},{"t":"秋窗","f":"七言律诗","c":["纸窗芦帘玉放光，朝朝线帖与针箱。","腰间欢喜潜松带，骨里鲜妍任毁妆。","画槛凭时禽注眼，绣鞋行处蝶随香。","太真瘦了春风面，一种秋魂化海棠。"]},{"t":"佳人","f":"七言律诗","c":["玉梅花下访云窝，坐对春山蹙翠蛾。","幽暗房栊听雨久，暖香屏障避风多。","论诗反索郎吟絮，作计閒教婢补萝。","踪迹自疏情自密，趁人回首注娇波。"]},{"t":"妒阻","f":"七言律诗","c":["妒眼如丛集满身，祇容相见罢相亲。","私书拌灭怀中字，幽恨难瞒镜里颦。","豆蔻含苞香触手，樱桃垂熟味沾唇。","当初只道寻常事，犹苦消魂未得真。"]},{"t":"幽窗纪事","f":"七言律诗","c":["洞房清昼似黄昏，却下重帘掩上门。","威闪星眸含薄怒，妒传风语表深恩。","鬓梢花朵防欹侧，舌本茶香恣吐吞。","容易铃声惊蛱蝶，已消孤闷未消魂。"]},{"t":"记言 其一","f":"七言绝句","c":["胆娘小胆却多情，鹦鹉才呼便吃惊。","错过今生好时节，泥人苦苦订来生。"]},{"t":"记言 其二","f":"七言绝句","c":["今生也算宿缘深，花纵分枝却一心。","脩作人间真伉俪，相怜转恐不如今。"]},{"t":"春雨代所思书闷 其一","f":"七言绝句","c":["蓝桥咫尺水盈盈，错过花朝月又明。","如此相思容易老，一生几度见云英。"]},{"t":"春雨代所思书闷 其二","f":"七言绝句","c":["梦隔心悬又十朝，绿窗风雨坐无聊。","九天屈注银湾水，那得凭空现鹊桥。"]},{"t":"春雨代所思书闷 其三","f":"七言绝句","c":["闷掩纱窗盼晓晴，几回错认画帘声。","玉阶细数沉沉滴，怨了东风怨薄情。"]},{"t":"泣别 其一","f":"七言律诗","c":["屡拣行期未有期，者番不道果临歧。","纵教齧臂坚盟约，无奈惊心重别离。","兰弱讵能胜远道，橘移还恐变芳姿。","一尊拌醉花前死，魂魄随卿好护持。"]},{"t":"泣别 其二","f":"七言律诗","c":["宁教生死隔幽关，远别情怀较死难。","人到去时看越好，泪无挥处怨尤酸。","即防永诀诚多虑，聊订前期强自宽。","留得两身憔悴在，相思祇隔路漫漫。"]},{"t":"泣别 其三","f":"七言律诗","c":["媪鬟催送上屏轩，折向空房又几番。","十步九回犹道速，一辞千嘱未嫌烦。","鬓梢花朵从欹堕，奁侧绒书任乱翻。","最是关心裙带系，玉郎亲赠别时言。"]},{"t":"泣别 其四","f":"七言律诗","c":["深闺从未涉关河，送上扁舟恨若何。","忍泪翻将词劝慰，耐心须保体安和。","相看每觉消魂尽，屡见原愁折福多。","暂别留些缘分在，镜台他日细消磨。"]},{"t":"个人生日","f":"七言律诗","c":["红药年时照绮寮，个人生日是今朝。","留宾每取头网试，拜佛亲将意可烧。","萝屋补苴原不易，兰闺行役太无聊。","重来响屧回廊下，竹影禽声总寂寥。"]},{"t":"舟夜","f":"七言律诗","c":["寻常小别上兰舟，回首山城见玉楼。","今夕依然开画桨，前行不觉过芳洲。","如何枕上醒孤梦，翻忆闺中作远游。","听尽船头风与水，绿波东下泪西流。"]},{"t":"小别","f":"五言律诗","c":["送远悲犹在，离情此又并。","暂迷三里雾，如隔一重城。","密意传眸子，归期订尾生。","临行手三反，知我定知卿。"]},{"t":"如约志喜 其一","f":"七言绝句","c":["临行坚说莫归迟，只许匆匆半月离。","不道芳心偏记得，果然不负玉郎期。"]},{"t":"如约志喜 其二","f":"七言绝句","c":["为探消息过卿居，果见明妆出绮疏。","众里相逢先问讯，别时清恙近何如。"]},{"t":"如约志喜 其三","f":"七言绝句","c":["守约如山定不更，玉蟾三五證前盟。","笑郎枉抱痴情在，准备桥头作尾生。"]},{"t":"如约志喜 其四","f":"七言绝句","c":["别不多时话已多，香肩斜倚注横波。","问郎他日天涯去，倘负归期待若何。"]},{"t":"病起","f":"七言律诗","c":["一番偎傍一凄其，若个深恩得似伊。","怜我病馀宜自爱，怕侬情重转相离。","无由汤药亲身奉，只是衾裯彻夜思。","见面但知郎瘦了，为郎消瘦却谁知。"]},{"t":"妄语","f":"七言律诗","c":["绿窗痴语太无聊，妄想重生比玉箫。","便等十年卿稚小，可知双鬓我飘萧。","浮萍纵记前生准，并蒂终嫌隔世遥。","留取悲愁缘分在，且图一见一魂消。"]},{"t":"幽踪 其一","f":"七言律诗","c":["湘帘窣地护幽房，更借屏山一曲傏。","为道狂心须自敛，漫云私语尽无妨。","潜踪尚恐衣翻角，侧耳频猜屧过廊。","重揭镜奁看鬓影，黄花手整绿云傍。"]},{"t":"幽踪 其二","f":"七言律诗","c":["漫把秋花较若何，祇应人月比姮娥。","日华映面空脂粉，云叶裁衣厌绮罗。","骨秀未容粗领略，情高常苦费猜摩。","今生幸不谐鸳牒，暂遇犹愁折福多。"]},{"t":"长恨辞 其一","f":"七言律诗","c":["秾华一树委千春，顿失蛾眉绝代颦。","呕血但知呼负负，回身犹想抱真真。","温柔尽折三生福，惊恐虚劳十载神。","一恸灵床还未敢，自怜终属薄情人。"]},{"t":"长恨辞 其二","f":"七言律诗","c":["病中密誓泪纷纷，细喘如丝语不分。","到死未能忘子建，佗生应得配参军。","玉箫果许常为媵，神女何辞暂化云。","只是费伊方寸血，相如新诔卓文君。"]},{"t":"长恨辞 其三","f":"七言律诗","c":["听到伤心伏枕辞，如何忍得泪千丝。","六州已铸今生错，万劫难消此愿痴。","眼看神娥奔月去，魂愁天女下凡迟。","不关贪守重生约，正恐轻生转负伊。"]},{"t":"长恨辞 其四","f":"七言律诗","c":["花香月色旧阑干，不忍重经况忍看。","是我心知天必忌，为卿泪滴地无乾。","浑如梦里还寻梦，虚被欢称未尽欢。","从此一双红豆颗，抛沉碧海恨漫漫。"]},{"t":"总悼一首","f":"七言律诗","c":["王夫人与管夫人，湘水神还洛水神。","身到碧空齐解脱，手拈红豆独酸辛。","愁丝日绕诗中絮，泪迹时沾画里筠。","欲报怜才恩似海，此生情海愿沉沦。"]},{"t":"阁笔","f":"七言律诗","c":["知音难得况蛾眉，手摔瑶琴谢子期。","宋璟怕题梅萼赋，杜陵悲撤海棠诗。","抽毫作诔循遗教，分俸营斋托诡辞。","我亦怜才非好色，料无人识有天知。"]},{"t":"无题和萧百堂 其一","f":"七言律诗","c":["镜中春浪洗朝霞，抛闪风情与月华。","不道负心真似铁，从来薄命定如花。","桥头误问巡官卜，江上虚猜估客槎。","帘捲西风还怅望，萧萧落叶满天涯。"]},{"t":"无题和萧百堂 其二","f":"七言律诗","c":["三年一信盼归迟，消息传来总可疑。","筝柱忽移哀雁调，钗梁偏罥喜蛛丝。","连宵梦好都无准，竟日妆成转自嗤。","小婢不知前计左，只催开镜画新眉。"]},{"t":"再和百堂 其一","f":"七言律诗","c":["裙剪湘云佩紫霞，春风消息露年华。","愁来不忍看残月，痴绝还思葬落花。","有器难收倾地水，无程可纪上天槎。","姻缘只好如鸿燕，海北江南各一涯。"]},{"t":"再和百堂 其二","f":"七言律诗","c":["果然重到不嫌迟，无奈空言祇益疑。","痴愿莫真成马角，愁身早已入蚕丝。","强为排解翻添恨，待觅商量恐受嗤。","听得邻娃倚夫婿，教依新样画蛾眉。"]},{"t":"帐檐梅花 其一","f":"七言绝句","c":["一重雾縠一重纱，写出前身萼绿华。","毕竟帷中看不见，依然暖玉当梅花。"]},{"t":"帐檐梅花 其二","f":"七言绝句","c":["罗帷春风偷揭开，寿阳妆额尚慵抬。","玉钩挂起分明看，也当巡檐索笑来。"]},{"t":"金陵女校书谢玉独居秋影楼洗妆谢客余与张香严秀才访之煮茗清谭殊有高致王脩微卞玉京一流人也临别留赠","f":"七言律诗","c":["美人从古怕妆残，邀宠争妍到此难。","要卜倾心谁妾爱，独将真色与人看。","轻身祇恐奔归月，清气偏宜坐近兰。","我有无穷天壤恨，为卿鸳牒也心寒。"]},{"t":"咏美人屧上絮","f":"七言绝句","c":["托迹红帮线绿边，步来香土欲成莲。","此生不作沾泥相，慧业能参自足禅。"]},{"t":"感蝶","f":"七言绝句","c":["庄周幻梦为蝴蝶，毕竟风流梦是空。","争似青陵台下魄，一生酣梦万花中。"]},{"t":"美人初度","f":"七言律诗","c":["如君竟体似芳莲，生在莲花一日前。","诗主性灵空倚傍，情缘洒脱愈缠绵。","巧思几越银河界，好梦常依璧月边。","绣佛灯明齐下拜，比肩人恰似同年。"]},{"t":"有悼","f":"七言律诗","c":["优昙钵里现芳华，秀在丰神慧齿牙。","吟雪尚留新起草，清霜偏折未开花。","认来小影烟如玉，归去秋魂月是家。","身到银河休怅恨，依然完得一匏瓜。"]},{"t":"折桂寄人","f":"七言绝句","c":["碾金为雪铸秋芳，合助瑶台素女妆。","此是蟾宫亲折得，满身风露尚天香。"]},{"t":"一笑","f":"七言律诗","c":["满身花片打渔郎，赢得楼头一笑偿。","岂是裂缯能博取，若为射雉始酬将。","漫誇城北徐公美，早识街西小杜狂。","却愿五陵裘马客，千金犹自费商量。"]},{"t":"戏凌客","f":"七言律诗","c":["声价空论十斛珠，羊车竟自返璠瑜。","花飞尚作随风飐，莺去犹闻隔谷呼。","叔宝祇应为小友，仲卿原不是人奴。","钟情自古招閒妒，图扇风流一例无。"]},{"t":"杂事 其一","f":"七言律诗","c":["阁翠灯红酒似潮，人间第一可怜宵。","绿熊茵展风都稳，赤凤车来雪未消。","别院箫声催月上，隔屏香气杂花飘。","蔡经得啖麒麟脯，已是麻姑指爪调。"]},{"t":"杂事 其二","f":"七言律诗","c":["此中洗面泪痕多，伏枕空持断袖罗。","北地自工操井臼，东屏何敢按笙歌。","羊车历鹿声初杳，雁柱参差调未和。","莫劝春江桃叶渡，真花还恐易摧柯。"]},{"t":"杂事 其三","f":"七言律诗","c":["留仙裙子石华裾，一种柔情玉有余。","肯负平时酬芍药，祇宜生日近芙蕖。","款宾亲设文犀箸，送远空思小犊车。","休抱王郎天壤恨，琴心未必遇相如。"]},{"t":"杂事 其四","f":"七言律诗","c":["绿纱窗紧掩罘罳，肯放轻风透一丝。","微笑岂因茶泼后，不言常似扇障时。","贪看花影吹灯早，爱受兰薰出浴迟。","未必长卿真病软，强邀纤玉为扶持。"]},{"t":"玉映","f":"七言律诗","c":["水样帘栊玉放光，语香未了杂花香。","竟邀映柱来窥伺，恰喜斜门得掩藏。","归去忽移青雀舫，重逢刚在碧鸡坊。","匆匆一笑天台路，知为刘郎为阮郎。"]},{"t":"花宴","f":"五言律诗","c":["仙手调羹巧，香涵玉盌春。","妙来无过熟，鲜极自生新。","座客贪尝饱，归犹乐道津。","嘉肴尽佳果，花宴谢花神。"]},{"t":"花烛辞调张子和比部纳姬姬静海人 其一","f":"七言绝句","c":["剪锦为帆桂作桡，渡江桃叶自吹箫。","侬家丁字沽边住，生小垂杨斗细腰。"]},{"t":"花烛辞调张子和比部纳姬姬静海人 其二","f":"七言绝句","c":["银烛生花漾翠屏，桃枝扇底玉珑玲。","一双同应天边宿，郎是郎官妾小星。"]},{"t":"花烛辞调张子和比部纳姬姬静海人 其三","f":"七言绝句","c":["五更紞鼓听鼕鼕，熏罢朝衣宿火红。","独抱云窝贪美睡，卖花声过小胡同。"]},{"t":"花烛辞调张子和比部纳姬姬静海人 其四","f":"七言绝句","c":["红条三尺署衔头，新拜都官属小秋。","左画蛾眉右书判，果然张敞最风流。"]},{"t":"蕊宫花史图并序 其一","f":"七言律诗","c":["非非妄想入诸天，管领群芳合众仙。","按月不关分甲乙，爱花原各种因缘。","九霄或有真灵在，万事都从傅会传。","比作诗家操选例，六朝唐宋一齐编。"]},{"t":"蕊宫花史图并序 其二","f":"七言律诗","c":["十二钗痕十二阑，万花深处佩珊珊。","改除时世梳妆俭，修到神仙眷属难。","点笔尽惊倾国艳，披图还认合家欢。","美人本是花真影，只当宣和画谱看。"]},{"t":"蕊宫花史图并序 其三","f":"七言律诗","c":["玉楼张出朵云新，占断瑶台四季春。","仙树参差寒暖候，神光离合古今人。","好花难得同生日，明月须知有化身。","留取埽眉真姓氏，彼人应又托传神。"]},{"t":"蕊宫花史图并序 其四","f":"七言律诗","c":["蕊珠宫殿月茫茫，我道分明即故乡。","花里便为仙世界，云边堪想古衣裳。","众香国暖春常笑，群玉山高夜放光。","愿得画中人不老，年年只作画中妆。"]},{"t":"杂纪 其一","f":"七言律诗","c":["昨夜帘栊事渺茫，花前赢得客清狂。","听歌误认回心院，映烛贪看半面妆。","箫史慢图声引凤，相如空奏曲求凰。","玉纤剥取青莲子，别想人间掷果郎。"]},{"t":"杂纪 其二","f":"七言律诗","c":["仙人画舫列瑶京，汉使乘槎犯太清。","相背已嫌如蒯彻，平看竟自学刘桢。","未妨惆怅原无益，少得团圞便有情。","不道微波萍末起，菱枝柔弱晚风倾。"]},{"t":"杂纪 其三","f":"七言律诗","c":["觞政清严石尉行，分曹射覆太纵横。","借花献佛开瑰阁，将酒骄人斗玉觥。","幸喜闻名知小宋，密教不饮救公荣。","怜才自是倾城意，恩怨何劳着眼明。"]},{"t":"杂纪 其四","f":"七言律诗","c":["归去铜龙咽漏迟，欢娘偏唱恼公诗。","盛名早慕罗昭谏，狂态宁嗤杜牧之。","竹叶翻时鸾独宿，桐花落处凤相思。","鄂君绣被香熏久，心悦夫君却未知。"]},{"t":"咏美人所制杨妃舌用海汁捣糖霜里玫瑰瓣为之取其形似也 其一","f":"七言绝句","c":["薄似银簧炙乍清，小红尖瓣本生成。","自从香口亲题后，应笑江瑶浪得名。"]},{"t":"咏美人所制杨妃舌用海汁捣糖霜里玫瑰瓣为之取其形似也 其二","f":"七言绝句","c":["西施舌好味嫌腥，新剥鸡头肉比馨。","一种妙莲花气息，是曾亲口授心经。"]},{"t":"咏美人所制杨妃舌用海汁捣糖霜里玫瑰瓣为之取其形似也 其三","f":"七言绝句","c":["一捻分明玉手将，宛然檀口吐丁香。","天生慧舌工翻案，不是杨梅强属杨。"]},{"t":"咏美人所制杨妃舌用海汁捣糖霜里玫瑰瓣为之取其形似也 其四","f":"七言绝句","c":["清品须陪雀舌茶，如酥滑腻欲胶牙。","三郎见此应微笑，亲唤玫瑰解语花。"]},{"t":"咏美人所制杨妃舌用海汁捣糖霜里玫瑰瓣为之取其形似也 其五","f":"七言绝句","c":["入口甘酸满上池，芳津直许透诗脾。","华清当日真滋味，只有宁王玉笛知。"]},{"t":"咏美人所制杨妃舌用海汁捣糖霜里玫瑰瓣为之取其形似也 其六","f":"七言绝句","c":["红得娇柔嚼未堪，香如鸡舌带微甘。","恰宜小病贪酸日，一点樱桃细细含。"]},{"t":"李松云陈云伯郭频伽诸君以蕊宫花史图题辞见寄戏书其后","f":"七言律诗","c":["碧城十二幻诸天，吴下因缘越水传。","岂有神人真示影，本来姊妹惯随肩。","司花故事原应女，脱草新诗果似仙。","传到蕊宫香口读，一时红紫尽嫣然。"]},{"t":"叠韵简顾虹桥秀才","f":"七言律诗","c":["一纸瑶章奏绿天，花台诗史早分传。","虎头笔果工添颊，蟾影图真合比肩。","清福自来关智慧，奇才方许赋神仙。","眉山叠韵还能否，更博群芳一冁然。"]},{"t":"虹桥叠韵见示以不得见图中人为辞余请以莲花代之","f":"七言律诗","c":["曾扫瑶台隶洞天，才名误被十洲传。","敢教王远嗔搔背，偶得洪崖戏拍肩。","迦叶悟时心即佛，藕花香处影皆仙。","何须亲见凌波影，身到银塘定宛然。"]},{"t":"阳羡寒辞和张椒卿六首 其一","f":"七言绝句","c":["绿波红舫即天台，花不知名烂漫开。","我比刘晨更无赖，此番瞒过阮郎来。"]},{"t":"阳羡寒辞和张椒卿六首 其二","f":"七言绝句","c":["轻衫如水剪柔蓝，占得烟波玉女潭。","自受东风披拂后，桃花红煞小城南。"]},{"t":"阳羡寒辞和张椒卿六首 其三","f":"七言绝句","c":["清脆乡音略带苏，七条弦上住罗敷。","望仙桥北垂杨路，认得当垆翠袖无。"]},{"t":"阳羡寒辞和张椒卿六首 其四","f":"七言绝句","c":["解画开元桂叶蛾，能酬主簿定情歌。","寻常一朵红兰影，已胜粗桃俗李多。"]},{"t":"阳羡寒辞和张椒卿六首 其五","f":"七言绝句","c":["张绪依依最少年，墨花狂污薛涛笺。","风情恰似灵和柳，摇曳轻风二月天。"]},{"t":"阳羡寒辞和张椒卿六首 其六","f":"七言绝句","c":["杜牧寻芳几晏时，柔情消得鬓如丝。","秋坟欲唤陈髯起，重唱迦陵绝妙词。"]},{"t":"从张椒卿问沈四消息","f":"七言律诗","c":["明知相见原无谓，消息寻来都甚真。","漫向谢三呼四字，只将苏小问乡亲。","桃花那记春前度，萍叶原为絮后身。","别有关心忘不得，莫猜渠是意中人。"]},{"t":"松陵有旧家子卖笑以养亲孙子悯其志为成四诗 其一","f":"七言绝句","c":["上弦月出两头纤，双笑花枝揭画帘。","不似小家拘束态，自然通脱自矜严。"]},{"t":"松陵有旧家子卖笑以养亲孙子悯其志为成四诗 其二","f":"七言绝句","c":["酒龙喝月笑如雷，赢得桃花上玉腮。","生小颂椒吟絮手，红酥浑未惯行杯。"]},{"t":"松陵有旧家子卖笑以养亲孙子悯其志为成四诗 其三","f":"七言绝句","c":["荥阳第宅旧平泉，券写簪花记昔年。","莫话东山丝竹事，惹侬双泪落尊前。"]},{"t":"松陵有旧家子卖笑以养亲孙子悯其志为成四诗 其四","f":"七言绝句","c":["博钱酒券替亲偿，燕玉还求暖老方。","侬自白华亲洁养，任人调笑野鸳鸯。"]},{"t":"艳体联句","f":"五言古诗","c":["楚地人双艳，卢家燕并栖。","恰当春暖热，转忆夜凄迷。","刬袜惊初见，倾襟语尚低。","肌凝姑射比，眉蹙女峰齐。","笑索香兰媚，间贫杜若携。","神光离与合，仙手挈还提。","密誓肤亲搯，觕才眼得鎞。","心知圆有镜，身愿捏成泥。","咫尺红楼近，寻常素简稽。","每偏恩雨露，许吐气虹霓。","豆颗相思种，花名远志题。","浮云指直北，弱水溯流西。","浊质惭晨肇，清狂称阮嵇。","来占乾鹊噪，静恼乳鸦啼。","隐语芙蓉妙，新词芍药诋。","折苕留翡翠，攀树引蝤蛴。","小字唐宫显，哀弦蜀国悽。","窗幽飞野马，房暗镇文犀。","怕听风闻撰，虚传海誓赍。","纸空猜鲗墨，分阻夺鸾篦。","偷祝坤灵扇，佯扶月窟梯。","问桃酸自酿，围棘苦难栖。","诗绣罗巾幅，书缄绛箧绨。","画图才仿佛，琴调是端倪。","美疢求丹鼎，芳年想玉笄。","喜蛛丝网盒，威凤羽裁袿。","写竹钤螭印，团香剔麝脐。","性灵鱼纵壑，踪迹鹿循蹊。","要订三生石，休虞百丈溪。","秋情枯瘦柳，宵梦握柔荑。","栩栩园迷蝶，胶胶枕报鸡。","联函千万语，无路达琼闺。"]},{"t":"有女郎临死自焚其诗稿者 其一","f":"七言绝句","c":["一方红泪滴琼瑰，拚把生香换死灰。","留下人间谁解读，除非侬再返魂来。"]},{"t":"有女郎临死自焚其诗稿者 其二","f":"七言绝句","c":["炉灰拨尽尚沉吟，身死何须要赏音。","遗恨有情偷记去，无从灰得此人心。"]},{"t":"赠秀卿 其一","f":"七言律诗","c":["销断琼楼与赤城，求浆只合问云英。","呼来小字珠无价，听到新歌月有声。","细搦丰肌容瘦削，偶装憨态越聪明。","寒宵称意熏炉畔，笑看双烟一气生。"]},{"t":"赠秀卿 其二","f":"七言律诗","c":["低窗窄槛易黄昏，汤沸茶垆瑞雾喷。","寂静互传眉角语，清寒频度指尖温。","人疑胡蝶依依梦，春逗梅花浅浅痕。","坐到月华如雪满，若吹银烛更消魂。"]},{"t":"赠秀卿 其三","f":"七言律诗","c":["瑶台飞下玉无尘，天与寒梅作替身。","姑射肌肤原处子，孤山婚嫁待诗人。","细论心曲宜长夜，亲说年庚恰嫩春。","怪底生香香不断，百花生日是生辰。"]},{"t":"赠秀卿 其四","f":"七言律诗","c":["屈指春光到画阑，玉郎车马上长安。","归期纵说相逢早，隔岁先愁欲别难。","梦雨愿随行李去，泪珠偷共烛花弹。","才人标格知多少，不似伊家耐细看。"]},{"t":"为兰风题天上人间图即以志别 其一","f":"七言绝句","c":["聘玉盟处玉化烟，生天小像写婵娟。","侬心别有兰香影，知在华鬟第几天。"]},{"t":"为兰风题天上人间图即以志别 其二","f":"七言绝句","c":["何必仙山缥缈踪，人间楼阁怕云封。","只消一片桃花纸，便隔人天万万重。"]},{"t":"为兰风题天上人间图即以志别 其三","f":"七言绝句","c":["索性神娥化玉京，磨刀割断藕丝情。","如何同在人间住，拚得参商过一生。"]},{"t":"为兰风题天上人间图即以志别 其四","f":"七言绝句","c":["就使飞身入广寒，常娥还许夜深看。","卿家更在青天上，要把琉瓈揭去难。"]},{"t":"为兰风题天上人间图即以志别 其五","f":"七言绝句","c":["借君图画写侬诗，各种情天各样辞。","亦有天台同梦处，杀花声里咒相思。"]},{"t":"为兰风题天上人间图即以志别 其六","f":"七言绝句","c":["碧浪红槎事渺冥，杨花未必见浮萍。","分明掌上珍珠颗，何处天宫作小星。"]},{"t":"为兰风题天上人间图即以志别 其七","f":"七言绝句","c":["春明好梦易蹉跎，掣泪同听小玉歌。","他日霓裳天宝曲，又添公案一重多。"]},{"t":"赠初蓉 其一","f":"七言律诗","c":["澹云微雨日西斜，细语轻怜隔浅纱。","帘影低迷防燕子，衣香清远袭梅花。","洛灵久断黄初梦，汉使难通碧落槎。","只当忘年真小友，出门动即到君家。"]},{"t":"赠初蓉 其二","f":"七言律诗","c":["玉梅花下写朝云，更比梅花瘦几分。","尽许眉间传月彩，难从骨里绘兰芬。","高情未称金泥屋，真色惟应雪浣裙。","俗眼但知浓艳好，相如羞对卓文君。"]},{"t":"题谢娘秋影照 其一","f":"七言绝句","c":["心多力弱篆烟微，隔着天河见影稀。","柳絮无情偏有福，因风还向谢家飞。"]},{"t":"题谢娘秋影照 其二","f":"七言绝句","c":["一重香雾百重门，月过閒阶不记痕。","落尽桐华深院锁，为谁风露立黄昏。"]},{"t":"题谢娘秋影照 其三","f":"七言绝句","c":["秦淮昔梦散如尘，太傅池台宿草新。","我是东山旧宾客，可堪重对卷中人。"]},{"t":"沪城花事绝句十二首 其一","f":"七言绝句","c":["千丛玉树万丛兰，曲折红桥四百栏。","不是道人骑鹤去，也应迷路出花难。"]},{"t":"沪城花事绝句十二首 其二","f":"七言绝句","c":["桂叶双眉秀绝尘，飞觞喝月斗千巡。","彦回枉杀髯如戟，沉醉东风让太真。"]},{"t":"沪城花事绝句十二首 其三","f":"七言绝句","c":["仙吏栽花绣满园，风前唱杀护花幡。","一枝偏赏琼林树，听报沿街女状元。"]},{"t":"沪城花事绝句十二首 其四","f":"七言绝句","c":["士龙才思枉如龙，抛得明珠堕海中。","亏我摩挲双醉眼，亲擒明月水晶宫。"]},{"t":"沪城花事绝句十二首 其五","f":"七言绝句","c":["俞生绝调太纵横，不数杭州苏老兵。","博得如皋轻一笑，当筵亲拜女门生。"]},{"t":"沪城花事绝句十二首 其六","f":"七言绝句","c":["调铅杀粉写珠娘，谁似华亭改七香。","喜字亲书三十六，他生修作紫鸳鸯。"]},{"t":"沪城花事绝句十二首 其七","f":"七言绝句","c":["老我清狂杜牧之，紫云吹散海棠丝。","东风牵惹閒枝叶，又值伤春病酒时。"]},{"t":"沪城花事绝句十二首 其八","f":"七言绝句","c":["酒龙意气颠如雷，一饮直须三百杯。","孤山处士果痴绝，醉插金英当玉梅。"]},{"t":"沪城花事绝句十二首 其九","f":"七言绝句","c":["香海花天酒满池，铁公绕指化柔丝。","玉皇敕赐双飞寺，醉杀偎红倚翠师。"]},{"t":"沪城花事绝句十二首 其十","f":"七言绝句","c":["凤尾红云海上开，连宵清梦宴瑶台。","黑风吹堕生罗刹，也有消魂李赤来。"]},{"t":"沪城花事绝句十二首 其十一","f":"七言绝句","c":["小队羊车窄袖身，银灯照耀玉精神。","张家世有莲花貌，也入花丛斗早春。"]},{"t":"沪城花事绝句十二首 其十二","f":"七言绝句","c":["小部霓裳舞柘枝，春灯斜映断红姿。","替他小史然眉急，偏是英雄李药师。"]},{"t":"重来 其一","f":"七言律诗","c":["重来碧玉旧情人，认取灯前窈窕身。","百媚生成无若秀，七情流露莫如真。","眼波能剪魂摇水，肌雪全消酒入春。","应笑桃花未开日，何曾洞口见刘晨。"]},{"t":"重来 其二","f":"七言律诗","c":["湘帘高揭字如丁，认得秦楼小凤翎。","十索歌成嫌夜促，四弦弹彻当秋听。","偶提往事颜微赤，偏遇才人眼最青。","珍重海棠休易落，杨花犹得化浮萍。"]},{"t":"为子和姬人题团扇 其一","f":"七言绝句","c":["皎洁齐纨妙剪裁，画眉窗下影徘徊。","分明一个天边月，偏落嫦娥素手来。"]},{"t":"为子和姬人题团扇 其二","f":"七言绝句","c":["洞房秋暖不知寒，莫取班姬古传看。","自制合欢新样子，更无一日不团圞。"]},{"t":"为子和姬人题团扇 其三","f":"七言绝句","c":["石阑点笔称题诗，树底轻凉拂面时。","谁唱画屏团扇曲，侍儿犹是谢芳姿。"]},{"t":"歌女","f":"七言绝句","c":["一曲檀槽语若丝，十三年纪太娇痴。","分明不解人情思，也有千拦百就时。"]},{"t":"戏赠罗仙 其一","f":"七言绝句","c":["人前绝不避嫌猜，身似采花堕我怀。","底事昨宵灯暗后，隔筵伸过凤头鞋。"]},{"t":"戏赠罗仙 其二","f":"七言绝句","c":["春浮香雨洒曼陀，一寸横波抵爱河。","不是散花天女使，如何能起病维摩。"]},{"t":"戏赠罗仙 其三","f":"七言绝句","c":["砚匣浓香拂翠裾，泥金扇索瘦金书。","回身又掣宣毫去，忆着相如病未除。"]},{"t":"戏赠罗仙 其四","f":"七言绝句","c":["推去偏来近又离，摘花擒蝶戏难支。","无端误触欢娘恼，翻得温存尔许时。"]},{"t":"懊侬","f":"七言律诗","c":["懊恼传呼老画师，生绡苦要写芳姿。","低头巳怕窗光逼，对面偏逢笔性迟。","何惜天人留本相，恐劳尘世惹相思。","切休刻画西家貌，暗属当筵顾凯之。"]},{"t":"罗浮","f":"七言律诗","c":["罗浮山顶有飞仙，不就梅花不肯眠。","双眼防教禅欲破，一生喜与俗无缘。","沈机翻觉情怀澹，薄怒偏增意态妍。","閒对春风成一笑，尽人评泊恣人怜。"]},{"t":"送菘畴归","f":"七言绝句","c":["一丸冷月片帆开，无计留君且送回。","明日紫荆花树下，有人还望折花来。"]},{"t":"赠别罗仙 其一","f":"七言律诗","c":["安榴花映泪斑红，别绪都含不语中。","佛愿纵悭成并蒂，仙踪何苦类顠蓬。","搯眉凄切盟沉水，捉臂矜持护守宫。","金锁暂笼么凤去，此生心已挂梧桐。"]},{"t":"赠别罗仙 其二","f":"七言律诗","c":["嘱郎珍重要郎安，收拾啼颜强作欢。","新月尽留圆后想，好花尤耐别时看。","伤心且说相逢易，行迹终愁自定难。","玉手亲除金缠臂，愿天重与铸团圞。"]},{"t":"赠别罗仙 其三","f":"七言律诗","c":["暂时小别尚萦牵，况是分飞各一天。","流水倘然终不返，浮云何似竟无缘。","香浓自古留难久，梦好从来续未全。","赠我青丝才一绺，如何穿尽泪珠圆。"]},{"t":"赠别罗仙 其四","f":"七言律诗","c":["同心稳抱此情芽，缘到春深会发葩。","大海有时逢断梗，小星甘自守匏瓜。","果营金屋先量地，若到银河定有楂。","手写红笺教记取，碧桃花坞第三家。"]},{"t":"别有所赠 其一","f":"七言绝句","c":["四条弦索酒双尊，记得离筵月一痕。","今夜绿纱窗外雨，又因桃叶念桃根。"]},{"t":"别有所赠 其二","f":"七言绝句","c":["枇杷花里小门关，金鸭香消玉柱间。","才是卸头鸳枕畔，无聊拥背话虞山。"]},{"t":"赠徐雪园女史","f":"七言律诗","c":["虹桥西去谢娘家，旧有才名出绛纱。","频典荆钗酬药物，自关茅屋种梅花。","綵毫得意能消福，玉佩当心最辟邪。","寄语江东徐小淑，清琴好好伴秦嘉。"]},{"t":"雨中同菘畴小霞泛舟至罗仙家送春","f":"七言律诗","c":["湖山如梦雨如尘，道是寻春却送春。","画桨双枝天上水，红楼一角意中人。","难遮去路唯青草，不定来踪是绿蘋。","究竟为谁惆怅煞，閒愁才洗又重新。"]},{"t":"立秋日得罗仙问","f":"七言律诗","c":["青鸟殷勤下碧城，蓝桥重许见云英。","书随梧叶先秋至，人比荷花隔水迎。","百恨尽抛云外释，双眸豫喜月边明。","却愁好事临期阻，抱柱依然作尾生。"]},{"t":"喜罗仙至","f":"七言律诗","c":["桃根持楫渡江来，奁具亲携玉镜台。","小别丰容看较瘦，浪传情事见先猜。","微闻密坐芝兰息，细验重襟豆蔻胎。","整掠云鬟照秋水，莲花羞对妙鬘开。"]},{"t":"供兰图 其一","f":"七言绝句","c":["三生公案證幽兰，珍重珠香白玉阑。","除却此花无当意，春风笑折一枝看。"]},{"t":"供兰图 其二","f":"七言绝句","c":["胆瓶欲插费商量，爱好天生事审详。","位置一花非草草，才人文笔佛心肠。"]},{"t":"水轩纪事 其一","f":"七言绝句","c":["银塘急雨响飕飕，水溅荷衣万叶愁。","一朵玉莲波上立，天风吹杀不低头。"]},{"t":"水轩纪事 其二","f":"七言绝句","c":["怜卿消瘦惜卿贫，肺腑深谭字字真。","却被芳心成一笑，始知洗耳有高人。"]},{"t":"悔恨词 其一","f":"七言律诗","c":["无端打鸭误惊鸳，竟作孤飞綵凤骞。","西子难追乘月艇，东君空竖护花幡。","情缘过爱翻成悔，事为沉几易受冤。","此夕秋灯风露里，谁怜憔悴病文园。"]},{"t":"悔恨词 其二","f":"七言律诗","c":["一纸相思两鬓丝，渡江桃叶竟无期。","薄言纵使逢卿怒，消息终应寄我知。","犹恐再圆仍易缺，果然重到不嫌迟。","崔微图画分明在，痴把银釭照几时。"]},{"t":"重九即事","f":"七言绝句","c":["相逢巾帔喜飘扬，双鬓寒花满屋香。","细雨幽窗低语处，人生能得几重阳。"]},{"t":"归舟","f":"七言绝句","c":["橹枝摇出荻花湾，隐约船头露翠鬟。","料得个人鸳枕上，梦魂先我到虞山。"]},{"t":"金凤曲为周生菘畴作 其一","f":"七言绝句","c":["迷香小洞曲珑玲，衣染幽兰叶叶馨。","脩到今生兼福慧，亲题诗上照春屏。"]},{"t":"金凤曲为周生菘畴作 其二","f":"七言绝句","c":["乍抛媚眼整云翘，顾曲心魂已暗消。","不索泉邱帷幕聘，只图夫婿会吹箫。"]},{"t":"金凤曲为周生菘畴作 其三","f":"七言绝句","c":["手拈红豆记琵琶，的的亲封捉臂纱。","侬自愿栖金井树，不知郎可是桐花。"]},{"t":"金凤曲为周生菘畴作 其四","f":"七言绝句","c":["双飞心事比鸳鸯，谁改婴兰小字香。","怕听跃龙宫里曲，九华深帐贮归郎。"]},{"t":"金凤曲为周生菘畴作 其五","f":"七言绝句","c":["果然公瑾似醇醪，情比秋江八月涛。","学赋梅花篇未了，又弹清泪赋离骚。"]},{"t":"戏集唐句","f":"七言律诗","c":["抱膝灯前影伴身，少年会遇洛川神。","相逢相失还如梦，倾国倾城不在人。","更被东风劝惆怅，静留迟日学因循。","须知此恨消难得，豆蔻花红十二春。"]},{"t":"温梦","f":"七言律诗","c":["高唐原是梦生涯，绿水红楼第四家。","北地胭脂中妇艳，南朝玉树后庭花。","渔郎潜混秦人服，织女偷邀汉使查。","惊觉风流真一霎，恼他鹦鹉唤煎茶。"]},{"t":"重次前韵","f":"七言律诗","c":["洞门回首即天涯，碧树深藏碧玉家。","三度事成三夜梦，一番寒减一分花。","频来得似穿帘燕，欲近难如上水查。","剩有顾侬心迹在，玉纤亲赐凤团茶。"]},{"t":"黄花比瘦图友人属题亡姬照 其一","f":"七言律诗","c":["栴檀风里散云英，薄命黄花悟此生。","愿作鸳鸯难比翼，怕闻鹦鹉尚呼名。","玉箫旧谱盟犹在，锦瑟华年续未成。","借取断肠诗一句，红儿小照雪儿情。"]},{"t":"黄花比瘦图友人属题亡姬照 其二","f":"七言律诗","c":["帘卷西风蝶梦孤，瘦秋人已化曼殊。","难求梁革回生药，祇剩崔徽卧病图。","蠹帙纵横签罢整，象床零落簟空铺。","髯翁手制朝云偈，一字分明一泪珠。"]},{"t":"谢雪卿挽辞钱子霞姬人 其一","f":"七言绝句","c":["逝水年华悼总笄，雪堂前梦太凄迷。","生憎点点因风絮，才上梅花便堕泥。"]},{"t":"谢雪卿挽辞钱子霞姬人 其二","f":"七言绝句","c":["芳姿格韵本如仙，了却春痕玉化烟。","手把定情团扇子，九原辛苦尚流连。"]},{"t":"谢雪卿挽辞钱子霞姬人 其三","f":"七言绝句","c":["晴雪难留短命身，秋风诀别太酸辛。","要郎记得营斋日，每到生辰是忌辰。"]},{"t":"谢雪卿挽辞钱子霞姬人 其四","f":"七言绝句","c":["我有伤心不可言，年年肠断木犀天。","借他湿翠啼红恨，自證幽兰院里禅。"]},{"t":"纪遇","f":"七言律诗","c":["绿梅花下记调笙，有个人人酷似卿。","天分不关仪彷佛，风神都在思聪明。","回眸宛尔偷成笑，熟视几乎错唤名。","愧我閒情如薙草，春风才到又重生。"]},{"t":"醉赠","f":"七言律诗","c":["皋桥西去美人家，绝世聪明沈婺华。","清瘦身材宜倚竹，玲珑指爪擅簪花。","双声叫出雌雄凤，两颊烘成早莫霞。","我醉欲归归未得，任他急雨洒窗纱。"]},{"t":"客有问吾邑者书此答之","f":"七言律诗","c":["软红尘里小蓬莱，画阁文疏对岸开。","七水流香穿郭过，半山飞绿进城来。","酒多按节倾家酿，花不论钱遍地栽。","莫笑耕夫多识字，梁时便有读书台。"]},{"t":"望海楼","f":"七言律诗","c":["翠微深处有高楼，海色飞来画栋浮。","落日惯招千古梦，乱云难扫一天愁。","鱼龙气湿腾空际，鸡犬声微出上头。","莫问潮生与潮落，雄心久已付闲鸥。"]}]};